insert into grammar_points
  (id, pattern, level, commonality, difficulty, formality, politeness, senses, match_strings, final_only, updated_at)
values
('더니', '-더니', 'advanced', 3, 4, 45, 50, $$[{"label": "Cause & result", "definition": "Connects a past observed situation with a natural consequence that followed: 'X was happening, and as a result Y.' The subject is usually a third person being observed.", "formation": "Verb/Adj stem + -더니 (cause-result reading)", "examples": [["그 친구가 매일 운동을 하더니 살이 많이 빠졌어요.", "That friend exercised every day, and as a result they lost a lot of weight."], ["친구는 전화를 받더니 수업 중간에 나가 버렸어요.", "My friend got a call, and then left in the middle of class."]], "notes": "The second clause is a natural/logical outcome of the first — this differs from the contrastive reading of -더니.", "label_ko": null, "label_vi": null, "definition_ko": "과거에 관찰한 상황과 그로 인해 자연스럽게 이어진 결과를 연결한다: 'X하더니 Y했다'. 보통 3인칭을 관찰할 때 쓴다.", "definition_vi": "Kết nối một tình huống đã quan sát trong quá khứ với kết quả tự nhiên xảy ra sau đó: 'X rồi thì Y'. Thường dùng khi quan sát người thứ ba.", "notes_ko": "두 번째 절은 첫 번째 절의 자연스럽고 논리적인 결과이며, 대조적 용법의 -더니와는 다르다.", "notes_vi": "Vế sau là kết quả tự nhiên, hợp lý của vế trước — khác với cách dùng đối lập của -더니."}, {"label": "Contrast", "definition": "Connects two opposite or contradictory situations, often with surprise or irony: 'X was the case (before), but now Y.'", "formation": "Verb/Adj stem + -더니 (contrastive reading)", "examples": [["아까는 울더니 지금은 잘 웃네요.", "A little while ago they were crying, but now they're laughing happily."], ["전에는 한국어를 못하더니 이제는 유창하게 하네요.", "Before, they couldn't speak Korean at all, but now they speak it fluently."]], "notes": "The contrast is between what the speaker previously observed and what is now true; subject is often a third party.", "label_ko": null, "label_vi": null, "definition_ko": "서로 반대되거나 모순되는 두 상황을 놀람이나 반어의 느낌으로 연결한다: '전에는 X했는데 지금은 Y하다'.", "definition_vi": "Kết nối hai tình huống trái ngược nhau, thường mang sắc thái ngạc nhiên: 'trước thì X, giờ lại Y'.", "notes_ko": "화자가 예전에 관찰한 것과 지금 사실인 것 사이의 대조이며, 주어는 대개 제3자다.", "notes_vi": "Đối lập giữa điều người nói từng quan sát và điều đang đúng bây giờ; chủ ngữ thường là người thứ ba."}]$$::jsonb, $$["더니"]$$::jsonb, false, now()),
('는-대로', '-는 대로', 'intermediate', 5, 2, 50, 50, $$[{"label": "As soon as", "definition": "Means 'as soon as X happens' — the second action follows immediately after the first.", "formation": "Verb stem + -는 대로", "examples": [["수업이 끝나는 대로 바로 식당으로 오세요.", "Come to the restaurant as soon as class ends."], ["도착하는 대로 저한테 전화 좀 해 주세요.", "Please call me as soon as you arrive."]], "notes": "Similar to -자마자 but slightly more neutral/planned in tone.", "label_ko": null, "label_vi": null, "definition_ko": "'X하자마자'라는 뜻으로, 앞의 행동이 끝나는 즉시 뒤의 행동이 이어진다.", "definition_vi": "Nghĩa là 'ngay khi X xảy ra' — hành động thứ hai diễn ra ngay sau hành động thứ nhất.", "notes_ko": "-자마자와 비슷하지만 좀 더 중립적이고 계획된 느낌이다.", "notes_vi": "Giống -자마자 nhưng trung tính và có vẻ được lên kế hoạch hơn."}, {"label": "Exactly as / in accordance with", "definition": "Means 'exactly as / in accordance with X' — an action is performed in the same manner or following the same standard as described.", "formation": "Verb stem + -는 대로", "examples": [["선생님이 가르쳐 주는 대로 공부하면 시험을 잘 볼 수 있어요.", "If you study exactly the way the teacher taught you, you can do well on the test."], ["요리책에 나와 있는 대로 순서대로 따라 했어요.", "I followed along exactly in the order shown in the cookbook."]], "notes": "A separate meaning from the 'as soon as' sense above, despite the identical form — context determines which applies.", "label_ko": null, "label_vi": null, "definition_ko": "'X한 그대로 / X에 맞춰서'라는 뜻으로, 설명되거나 정해진 방식과 똑같이 행동함을 나타낸다.", "definition_vi": "Nghĩa là 'đúng như / theo đúng X' — hành động được thực hiện đúng theo cách hoặc tiêu chuẩn đã nêu.", "notes_ko": "위의 '~하자마자' 의미와 형태는 같지만 뜻이 다르며, 문맥으로 구별한다.", "notes_vi": "Có hình thức giống nghĩa 'ngay khi' ở trên nhưng ý nghĩa khác — ngữ cảnh quyết định cách hiểu."}]$$::jsonb, $$["는 대로"]$$::jsonb, false, now()),
('는지-은지-ㄴ지', '-는지/은지/ㄴ지', 'advanced', 4, 4, 50, 50, $$[{"label": "Degree ('so X that...') — with 어찌나/얼마나", "definition": "Expresses an extreme degree of something that caused or explains a result: 'it was so X that...'. 어찌나/얼마나 both mean 'so much / to such a degree,' with 얼마나 more neutral and 어찌나 more exclamatory.", "formation": "어찌나/얼마나 + Verb/Adj + -는지/은지/ㄴ지 (+ result clause)", "examples": [["어찌나 피곤한지 앉자마자 잠이 들었어요.", "I was so exhausted that I fell asleep the moment I sat down."], ["얼마나 반가운지 눈물이 날 뻔했어요.", "I was so glad to see them that I nearly burst into tears."]], "notes": "The result clause often describes a natural or surprising consequence; can also be used as a rhetorical exclamation with no explicit result.", "label_ko": "정도 ('너무 X해서...') — 어찌나/얼마나와 함께", "label_vi": "Mức độ ('X đến mức...') — dùng với 어찌나/얼마나", "definition_ko": "결과를 일으키거나 설명하는 극도의 정도를 나타낸다: '너무 X해서...'. 어찌나와 얼마나는 둘 다 '그만큼'이라는 뜻이며, 얼마나는 좀 더 중립적이고 어찌나는 좀 더 감탄조다.", "definition_vi": "Diễn tả mức độ cực đoan dẫn đến hoặc giải thích một kết quả: 'X đến mức...'. 어찌나 và 얼마나 đều nghĩa là 'đến mức đó', trong đó 얼마나 trung tính hơn còn 어찌나 mang sắc thái cảm thán hơn.", "notes_ko": "결과절은 자연스럽거나 놀라운 결과를 나타내는 경우가 많다. 결과절 없이 감탄으로만 쓰이기도 한다.", "notes_vi": "Vế kết quả thường diễn tả một hệ quả tự nhiên hoặc bất ngờ; cũng có thể dùng như một câu cảm thán không cần vế kết quả."}, {"label": "Indirect question ('whether/if X')", "definition": "Embeds an indirect question or expresses uncertainty: 'whether X,' 'I wonder if X,' or 'I'm not sure X.' Turns a clause into an indirect question, often the object of 모르다, 알다, 궁금하다.", "formation": "Verb/Adj modifier form + -는지/은지/ㄴ지", "examples": [["왜 그런지 이해가 안 돼요.", "I can't understand why that is."], ["그 사람이 괜찮은지 걱정이 돼요.", "I'm worried about whether that person is okay."]], "notes": "Distinct from the degree construction with 얼마나/어찌나; alone, it signals uncertainty or an embedded question rather than intensity.", "label_ko": "간접 의문문 ('X인지 아닌지')", "label_vi": "Câu hỏi gián tiếp ('có X hay không')", "definition_ko": "간접 의문이나 불확실함을 나타낸다: 'X인지', 'X일지 모르겠다'. 모르다, 알다, 궁금하다 등의 목적어로 쓰인다.", "definition_vi": "Diễn tả câu hỏi gián tiếp hoặc sự không chắc chắn: 'có phải X hay không', 'không biết có X hay không'. Thường làm tân ngữ cho 모르다, 알다, 궁금하다.", "notes_ko": "얼마나/어찌나와 함께 쓰이는 정도 표현과는 다르다. 단독으로 쓰이면 보통 불확실함이나 간접 의문을 나타낸다.", "notes_vi": "Khác với cách dùng chỉ mức độ đi cùng 얼마나/어찌나. Khi đứng một mình, thường biểu thị sự không chắc chắn hoặc câu hỏi gián tiếp."}]$$::jsonb, $$["는지", "은지", "ㄴ지"]$$::jsonb, false, now()),
('거든-요', '-거든(요)', 'intermediate', 5, 2, 25, 45, $$[{"label": "Connective — sets up a condition/precondition ('if/when X, then...')", "definition": "Gives a reason or precondition for what follows, often used to set up a request, instruction, or plan: 'if/when X (happens/is the case), then...'. Very common in casual spoken Korean.", "formation": "Verb/Adj stem + -거든 (+ instruction or follow-up clause)", "examples": [["고향에 도착하거든 이메일 보내 주세요.", "When you arrive home, please send me an email."], ["시간이 있거든 저 좀 도와주세요.", "If you have time, please help me out."]], "notes": "Also used sentence-finally (-거든요) simply to give a reason/explanation for something just said, without a following instruction — see the separate -거든요 entry for that use.", "label_ko": "연결형 — 조건/전제를 제시 ('만약/할 때 X하면...')", "label_vi": "Liên kết — nêu điều kiện/tiền đề ('nếu/khi X thì...')", "definition_ko": "뒤에 이어질 요청, 지시, 계획을 위한 이유나 전제조건을 제시한다: '만약 X하면(이면)...'. 구어체에서 매우 흔하다.", "definition_vi": "Nêu lý do hoặc điều kiện tiền đề cho điều sắp nói: 'nếu/khi X thì...'. Rất phổ biến trong khẩu ngữ.", "notes_ko": "문장 끝에서(-거든요) 단순히 방금 말한 것에 대한 이유를 설명할 때도 쓰인다 — 그 용법은 다음 항목 참고.", "notes_vi": "Cũng dùng ở cuối câu (-거든요) chỉ để giải thích lý do cho điều vừa nói — xem nghĩa riêng bên dưới."}, {"label": "Sentence-final — gives a reason/explanation ('you see, because X')", "definition": "A sentence-final ending that gives a reason or explanation for something just said or observed, without necessarily setting up an instruction: 'you see, because X.'", "formation": "Verb/Adj stem (or Noun+이) + -거든요", "examples": [["배가 고파요. 아침부터 아무것도 안 먹었거든요.", "I'm hungry — you see, I haven't eaten anything since this morning."], ["저 오늘 좀 늦을 것 같아요. 차가 막히거든요.", "I think I'll be a bit late today — traffic's backed up, you see."]], "notes": "Distinct from the connective -거든 (which sets up a following instruction) — this sentence-final use simply explains or justifies.", "label_ko": "문장 종결형 — 이유/설명 제시 ('있잖아요, X해서요')", "label_vi": "Kết thúc câu — đưa ra lý do/giải thích ('vì X đó')", "definition_ko": "방금 말했거나 관찰한 것에 대한 이유나 설명을 제시하는 문장 종결형이다: '있잖아요, X해서요'.", "definition_vi": "Là đuôi kết thúc câu, đưa ra lý do hoặc giải thích cho điều vừa nói hoặc quan sát được: 'vì X đó'.", "notes_ko": "뒤에 지시가 이어지는 연결형 -거든과는 다르며, 이 종결형은 단순히 설명하거나 정당화하는 역할만 한다.", "notes_vi": "Khác với liên từ -거든 (dẫn đến một mệnh lệnh/chỉ dẫn theo sau) — cách dùng cuối câu này chỉ đơn thuần giải thích hoặc biện minh."}]$$::jsonb, $$["거든요", "거든"]$$::jsonb, false, now()),
('으-ㄹ걸-요', '-(으)ㄹ걸(요)', 'advanced', 3, 4, 20, 40, $$[{"label": "Regret about a past choice ('should have done X')", "definition": "Expresses regret about something the speaker didn't do but wishes they had: 'I should have done X.' Without 그랬다, it trails off with implied regret.", "formation": "Verb stem + -(으)ㄹ걸 (그랬다)", "examples": [["미리 예약할걸 그랬어요. 이제 자리가 없네요.", "I should have made a reservation in advance. Now there are no seats left."], ["돈이 있을 때 좀 아껴서 쓸걸 그랬어요.", "I should have been more frugal while I had money."]], "notes": "Without 그랬다 and with falling intonation, -(으)ㄹ걸 alone can instead express a guess about the present/future.", "label_ko": "과거의 선택에 대한 후회 ('X할 걸 그랬다')", "label_vi": "Hối tiếc về lựa chọn trong quá khứ ('lẽ ra nên X')", "definition_ko": "하지 않았지만 했었더라면 좋았을 일에 대한 후회를 나타낸다: 'X할 걸 그랬어요'. 그랬다 없이 쓰면 후회의 여운만 남긴다.", "definition_vi": "Diễn tả sự hối tiếc về điều đã không làm nhưng lẽ ra nên làm: 'lẽ ra nên X'. Nếu không có 그랬다, câu để lại dư âm tiếc nuối.", "notes_ko": "그랬다 없이 내림조 억양으로 쓰면 현재/미래에 대한 추측을 나타낼 수도 있다.", "notes_vi": "Nếu không có 그랬다 và xuống giọng, -(으)ㄹ걸 một mình có thể diễn tả một dự đoán về hiện tại/tương lai."}, {"label": "Confident guess/speculation ('I bet X')", "definition": "A sentence-final ending expressing a confident guess or speculation: 'I bet X' or 'it's probably X,' often when the speaker knows something the listener doesn't.", "formation": "Verb/Adj stem + -(으)ㄹ걸요", "examples": [["영미 씨는 감기에 걸려서 오늘 학교에 못 올걸요.", "Yeong-mi has a cold, so she probably won't be able to come to school today."], ["지금 출발하면 늦지 않을걸요.", "If you leave now, I bet you won't be late."]], "notes": "Distinct from -(으)ㄹ걸 그랬다 (regret about a past choice) — this is a present/future guess, not regret.", "label_ko": "확신하는 추측 ('아마 X일걸요')", "label_vi": "Đoán chắc chắn ('chắc là X')", "definition_ko": "화자가 상대방이 모르는 것을 알고 있을 때 자주 쓰는, 확신에 찬 추측이나 짐작을 나타내는 문장 종결형이다: '아마 X일걸요'.", "definition_vi": "Là đuôi kết thúc câu diễn tả một dự đoán chắc chắn, thường dùng khi người nói biết điều gì đó mà người nghe không biết: 'chắc là X'.", "notes_ko": "과거의 선택을 후회하는 -(으)ㄹ걸 그랬다와는 다르며, 이것은 후회가 아니라 현재/미래에 대한 추측이다.", "notes_vi": "Khác với -(으)ㄹ걸 그랬다 (hối tiếc về lựa chọn quá khứ) — đây là dự đoán về hiện tại/tương lai, không phải hối tiếc."}]$$::jsonb, $$["을걸요", "ㄹ걸요", "을걸", "ㄹ걸"]$$::jsonb, true, now()),
('도록', '-도록', 'intermediate', 4, 3, 55, 55, $$[{"label": "Purpose / extent ('so that X' / 'to the point of X')", "definition": "Two main uses: (1) purpose — 'so that X / in order that X'; (2) extent — 'to the point of X / so much that X.' Also used in directives: 'make sure to do X.'", "formation": "Verb stem + -도록", "examples": [["모두가 이해할 수 있도록 천천히 설명해 주세요.", "Please explain slowly so that everyone can understand."], ["밤이 늦도록 딸이 돌아오지 않아서 걱정이에요.", "I'm worried because my daughter hasn't come home even though it's gotten late."]], "notes": "Context determines the reading: with effort/instruction verbs it signals purpose; with degree expressions it signals extreme extent. The related -도록 하다 softens it into an imperative ('make sure to...').", "label_ko": "목적/정도 ('X하도록' / 'X할 정도로')", "label_vi": "Mục đích/mức độ ('để X' / 'đến mức X')", "definition_ko": "두 가지 주요 용법이 있다: (1) 목적 — 'X하도록(하기 위해)'; (2) 정도 — 'X할 정도로'. 지시할 때 '반드시 X하세요'라는 뜻으로도 쓰인다.", "definition_vi": "Có hai cách dùng chính: (1) mục đích — 'để X'; (2) mức độ — 'đến mức X'. Cũng dùng trong mệnh lệnh: 'hãy chắc chắn X'.", "notes_ko": "문맥에 따라 해석이 달라진다: 노력/지시 동사와 쓰이면 목적, 정도 표현과 쓰이면 극도의 정도를 나타낸다. 관련 표현 -도록 하다는 부드러운 명령이 된다.", "notes_vi": "Ngữ cảnh quyết định cách hiểu: với động từ chỉ nỗ lực/chỉ dẫn thì mang nghĩa mục đích, với cụm từ chỉ mức độ thì mang nghĩa cực độ. -도록 하다 liên quan là cách ra lệnh nhẹ nhàng hơn."}, {"label": "+ 하다: softened imperative ('make sure to do X')", "definition": "A softened imperative meaning 'make sure to do X' or 'be sure that X happens' — a gentler, more formal way of giving an instruction.", "formation": "Verb stem + -도록 하다", "examples": [["여러분, 지각하지 말고 일찍 오도록 하세요.", "Everyone, please make sure not to be late and come early."], ["회의에 늦지 않도록 하세요.", "Please make sure not to be late for the meeting."]], "notes": "Closely related to plain -도록; adding 하다 turns it into a polite command/instruction.", "label_ko": "+하다: 부드러운 명령 ('반드시 X하세요')", "label_vi": "+하다: mệnh lệnh nhẹ nhàng hơn ('hãy nhớ X')", "definition_ko": "'반드시 X하세요'라는 뜻의 부드러운 명령형으로, 좀 더 정중하고 부드럽게 지시하는 방법이다.", "definition_vi": "Là cách ra lệnh nhẹ nhàng nghĩa là 'hãy chắc chắn làm X' — cách chỉ dẫn lịch sự và dịu dàng hơn.", "notes_ko": "일반 -도록과 밀접하게 관련되며, 하다를 붙이면 정중한 명령/지시가 된다.", "notes_vi": "Có liên hệ chặt chẽ với -도록 đơn thuần; thêm 하다 biến nó thành mệnh lệnh/chỉ dẫn lịch sự."}]$$::jsonb, $$["도록"]$$::jsonb, false, now()),
('게', '-게', 'intermediate', 5, 1, 50, 50, $$[{"label": "Adverbializer / manner-purpose ('in an X way', 'so that X')", "definition": "Turns a descriptive verb (adjective) into an adverb, or expresses the manner/purpose/degree of the following action: 'in an X way' or 'so that X'.", "formation": "Adjective stem + -게 (+ following verb)", "examples": [["아이가 알아듣게 천천히 말해 주세요.", "Please speak slowly so the child can understand."], ["예쁘게 꾸몄어요.", "I decorated it nicely."]], "notes": "One of the most basic and versatile connective endings; combines with 하다 to form the causative -게 하다.", "label_ko": "부사화/방법-목적 ('X하게', 'X하도록')", "label_vi": "Trạng từ hóa/cách thức-mục đích ('một cách X', 'để X')", "definition_ko": "형용사를 부사로 바꾸거나, 뒤에 오는 행동의 방법·목적·정도를 나타낸다: 'X하게' 또는 'X하도록'.", "definition_vi": "Biến tính từ thành trạng từ, hoặc diễn tả cách thức/mục đích/mức độ của hành động theo sau: 'một cách X' hoặc 'để X'.", "notes_ko": "가장 기본적이고 다양하게 쓰이는 연결어미 중 하나이며, 하다와 결합해 사동 -게 하다를 만든다.", "notes_vi": "Một trong những vĩ tố liên kết cơ bản và linh hoạt nhất; kết hợp với 하다 tạo thành thể sai khiến -게 하다."}, {"label": "+ 하다: causative ('to make/let someone do X')", "definition": "The productive (long-form) causative: 'to make/let someone do X' or 'to cause X to happen.'", "formation": "Verb/Adj stem + -게 하다", "examples": [["오래 기다리게 해서 미안해요.", "I'm sorry for making you wait so long."], ["선생님은 학생들에게 책을 읽게 했어요.", "The teacher had the students read a book."]], "notes": "Works with virtually any verb, unlike the irregular short causative suffixes (이/히/리/기/우/구/추).", "label_ko": "+하다: 사동 ('누군가에게 X하게 하다')", "label_vi": "+하다: thể sai khiến ('làm/cho ai đó X')", "definition_ko": "생산적으로(장형) 쓰이는 사동형으로, '누군가에게 X를 하게 만들다/시키다'라는 뜻이다.", "definition_vi": "Là thể sai khiến (dài) mang tính sản sinh, nghĩa là 'khiến/cho phép ai đó làm X'.", "notes_ko": "불규칙한 단형 사동 접미사(이/히/리/기/우/구/추)와 달리 거의 모든 동사에 쓸 수 있다.", "notes_vi": "Không giống các hậu tố sai khiến ngắn bất quy tắc (이/히/리/기/우/구/추), -게 하다 dùng được với hầu hết mọi động từ."}]$$::jsonb, $$["게"]$$::jsonb, false, now()),
('만-못하다', '-만 못하다', 'intermediate', 3, 3, 55, 50, $$[{"label": null, "definition": "Expresses that one thing is inferior to or not as good as another: 'X is not as good as Y / X falls short of Y.'", "formation": "Noun + 만 못하다", "examples": [["전망은 이 방만 못하지만 밝고 깨끗해요.", "The view isn't as good as this room's, but it's bright and clean."], ["요즘 만드는 음식은 어머니가 해 주시던 것만 못해요.", "The food I make these days isn't as good as what my mother used to make."]], "notes": "The compared noun (Y) takes 만; 못하다 conjugates like a regular adjective.", "label_ko": null, "label_vi": null, "definition_ko": "한 대상이 다른 대상보다 못하거나 그만 못함을 나타낸다: 'X는 Y만 못하다'.", "definition_vi": "Diễn tả một thứ kém hơn hoặc không bằng thứ khác: 'X không bằng Y'.", "notes_ko": "비교 대상(Y)에 만이 붙으며, 못하다는 일반 형용사처럼 활용한다.", "notes_vi": "Danh từ được so sánh (Y) đi với 만; 못하다 chia giống tính từ thông thường."}]$$::jsonb, $$["만 못하다"]$$::jsonb, false, now()),
('고-해서', '-고 해서', 'intermediate', 3, 3, 30, 50, $$[{"label": null, "definition": "Gives one reason among possibly several for an action, implying 'partly because X (and other reasons too)'. Softer and less definitive than stating a single direct cause.", "formation": "Verb/Adj stem + -고 해서", "examples": [["여름도 되고 해서 머리 모양을 좀 바꿔 봤어요.", "Since it's become summer (among other reasons), I decided to change my hairstyle a bit."], ["배도 고프고 해서 우리 뭐 좀 먹으러 갈까요?", "I'm a bit hungry (among other things), so shall we go grab something to eat?"]], "notes": "Implies there were other unstated reasons too — contrast with -아/어서, which states a single direct cause.", "label_ko": null, "label_vi": null, "definition_ko": "'다른 이유도 있지만 특히 X해서'라는 뜻으로, 여러 이유 중 하나를 부드럽게 제시한다.", "definition_vi": "Nêu một trong nhiều lý do, ngụ ý 'một phần vì X (và còn lý do khác nữa)'.", "notes_ko": "다른 이유가 더 있음을 암시한다 — 하나의 직접적 이유만 말하는 -아/어서와 대조된다.", "notes_vi": "Ngụ ý còn có những lý do khác chưa nói ra — khác với -아/어서 vốn nêu một lý do trực tiếp duy nhất."}]$$::jsonb, $$["고 해서"]$$::jsonb, false, now()),
('간접화법-축약형-abbreviated-indirect-speech', '간접화법 축약형 (Abbreviated Indirect Speech)', 'advanced', 5, 4, 15, 35, $$[{"label": null, "definition": "Casual, contracted forms of reported (indirect quotation) speech used in everyday conversation, replacing the fuller -다고 해요 / -냐고 해요 / -라고 해요 / -자고 해요 patterns.", "formation": "Statement: -대(요) ← -다고 해요 · Question: -냬(요) ← -냐고 해요 · Command: -래(요) ← -라고 해요 · Suggestion: -재(요) ← -자고 해요", "examples": [["음식이 싸고 맛있대요.", "They say the food is cheap and delicious. (← 맛있다고 해요)"], ["같이 가재요.", "They're suggesting we go together. (← 같이 가자고 해요)"]], "notes": "Purely a spoken-register contraction; the meaning is identical to the full indirect-speech form, just shorter and more casual.", "label_ko": null, "label_vi": null, "definition_ko": "-다고 해요/냐고 해요/라고 해요/자고 해요의 축약형으로, 일상 대화에서 간접화법을 짧게 줄여 쓰는 구어체 표현이다.", "definition_vi": "Là dạng rút gọn của -다고 해요/냐고 해요/라고 해요/자고 해요, dùng để nói gián tiếp ngắn gọn trong hội thoại hàng ngày.", "notes_ko": "순전히 구어체적인 축약이며, 의미는 완전한 간접화법 형태와 동일하고 단지 더 짧고 캐주얼할 뿐이다.", "notes_vi": "Chỉ là dạng rút gọn trong khẩu ngữ; ý nghĩa hoàn toàn giống dạng gián tiếp đầy đủ, chỉ ngắn gọn và thân mật hơn."}]$$::jsonb, $$[]$$::jsonb, false, now()),
('기는요', '-기는요', 'intermediate', 4, 2, 15, 45, $$[{"label": null, "definition": "A dismissive or modest response used to downplay a compliment, deny an assumption, or contradict what was just said: 'Not really,' 'Far from it,' 'What are you talking about.'", "formation": "Verb/Adj stem (or Noun+이) + -기는요", "examples": [["A: 한국어를 참 잘하시네요! B: 잘하기는요. 아직 멀었어요.", "A: You're really good at Korean! B: Not really — I still have a long way to go."], ["A: 요즘 바쁘시죠? B: 바쁘기는요. 완전 한가해요.", "A: You must be busy these days, right? B: Busy? Not at all — I'm totally free."]], "notes": "Almost always a direct reaction to something the other person just said; rarely used to open a new topic.", "label_ko": null, "label_vi": null, "definition_ko": "칭찬을 겸손히 낮추거나, 가정을 부정하거나, 방금 들은 말에 반박할 때 쓰는 표현이다: '아니에요, 뭘요'.", "definition_vi": "Dùng để khiêm tốn từ chối lời khen, phủ nhận một giả định, hoặc phản bác điều vừa nghe: 'đâu có, gì mà'.", "notes_ko": "거의 항상 상대방이 방금 한 말에 대한 직접적인 반응이며, 새로운 화제를 꺼낼 때는 잘 안 쓴다.", "notes_vi": "Hầu như luôn là phản ứng trực tiếp với điều người khác vừa nói; hiếm khi dùng để mở đầu chủ đề mới."}]$$::jsonb, $$["기는요"]$$::jsonb, true, now()),
('피동-passive-voice', '피동 (Passive Voice)', 'advanced', 4, 4, 50, 50, $$[{"label": null, "definition": "The Korean passive voice, expressing that the subject receives the action rather than performs it: 'is done / gets done (to something) by something.'", "formation": "Short passive: verb stem + 이/히/리/기 · Long passive: verb stem + -아/어지다", "examples": [["소리가 잘 안 들려요.", "The sound isn't heard well (I can't hear it well)."], ["문제가 잘 풀렸어요.", "The problem got solved well."]], "notes": "Only a fixed set of verbs take the short passive suffixes (이/히/리/기); most others use -아/어지다 instead. Not every active verb has a corresponding passive form.", "label_ko": null, "label_vi": null, "definition_ko": "주어가 행동을 하는 것이 아니라 행동을 당하는 한국어의 피동태를 나타낸다: '(무엇에 의해) X되다/당하다'.", "definition_vi": "Thể bị động trong tiếng Hàn, diễn tả chủ ngữ chịu tác động của hành động chứ không thực hiện hành động: 'bị/được X'.", "notes_ko": "정해진 일부 동사만 단형 피동 접미사(이/히/리/기)를 쓰고, 나머지는 대부분 -아/어지다를 쓴다. 모든 능동사가 피동형을 갖는 것은 아니다.", "notes_vi": "Chỉ một số động từ cố định dùng hậu tố bị động ngắn (이/히/리/기); phần lớn còn lại dùng -아/어지다. Không phải động từ chủ động nào cũng có dạng bị động tương ứng."}]$$::jsonb, $$[]$$::jsonb, false, now()),
('고-요', '-고(요)', 'intermediate', 3, 2, 35, 55, $$[{"label": null, "definition": "Adds a supplementary or additional piece of information at the end of a sentence, in a soft, conversational tone: 'and also...', 'oh, and...'", "formation": "Verb/Adj stem (or sentence-final form) + -고(요)", "examples": [["오늘 날씨가 좋네요. 바람도 시원하고요.", "The weather's nice today. And the breeze is cool too."], ["이 식당 음식이 참 맛있어요. 가격도 저렴하고요.", "The food at this restaurant is really good. And it's inexpensive too."]], "notes": "The 요 is optional and simply adds politeness; without it, it's plain/casual speech.", "label_ko": null, "label_vi": null, "definition_ko": "부드럽고 대화체적인 어조로 문장 끝에 추가 정보를 덧붙인다: '그리고 X도요...'.", "definition_vi": "Thêm thông tin bổ sung ở cuối câu với giọng điệu mềm mại, thân mật: 'với lại còn X nữa...'.", "notes_ko": "요는 선택 사항이며 단지 공손함을 더할 뿐이다. 없으면 평어체/반말이 된다.", "notes_vi": "요 là tùy chọn, chỉ thêm sự lịch sự; nếu bỏ đi thì trở thành lời nói suồng sã/thân mật."}]$$::jsonb, $$["고요", "고"]$$::jsonb, true, now()),
('는-대신-에', '-는 대신(에)', 'intermediate', 4, 2, 50, 50, $$[{"label": null, "definition": "Indicates that one thing is done, given, or true 'in place of' or 'in exchange for' another: 'instead of X' or 'in return for X.'", "formation": "Verb (present) -는 대신(에) · Adjective -(으)ㄴ 대신(에) · Noun 대신(에)", "examples": [["내가 한국어를 가르쳐 주는 대신에 너는 중국어를 가르쳐 줘.", "I'll teach you Korean, and in exchange you teach me Chinese."], ["요즘은 현금을 내는 대신에 교통카드를 많이 써요.", "These days, instead of paying cash, people mostly use transit cards."]], "notes": "Can express either a trade-off (mutual exchange) or a simple substitution, depending on context.", "label_ko": null, "label_vi": null, "definition_ko": "한 가지가 다른 것을 '대신하여' 또는 '교환하여' 이루어짐을 나타낸다: 'X 대신에 Y'.", "definition_vi": "Diễn tả một việc được làm/cho 'thay cho' hoặc 'đổi lấy' việc khác: 'thay vì X thì Y'.", "notes_ko": "상호 교환이나 단순한 대체 둘 다를 나타낼 수 있으며 문맥에 따라 다르다.", "notes_vi": "Có thể diễn tả sự trao đổi qua lại hoặc chỉ đơn giản là thay thế, tùy theo ngữ cảnh."}]$$::jsonb, $$["는 대신", "은 대신", "ㄴ 대신"]$$::jsonb, false, now()),
('을-ㄹ-뿐-만-아니라', '-을/ㄹ 뿐(만) 아니라', 'intermediate', 4, 3, 60, 55, $$[{"label": null, "definition": "Means 'not only X, but also Y' — adds a second, often more significant, fact on top of the first.", "formation": "Verb/Adj stem + -을/ㄹ 뿐만 아니라 (also -는 것뿐만 아니라 for nouns/nominalized clauses)", "examples": [["내 친구는 운동도 잘할 뿐만 아니라 공부도 잘한다.", "My friend is not only good at sports but also good at studying."], ["이 가방은 디자인이 예쁠 뿐만 아니라 아주 실용적이다.", "This bag isn't just pretty in design — it's also very practical."]], "notes": "만 is optional and adds emphasis; the core meaning is the same with or without it.", "label_ko": null, "label_vi": null, "definition_ko": "'X할 뿐만 아니라 Y도'라는 뜻으로, 첫 번째 사실 위에 더 중요한 두 번째 사실을 덧붙인다.", "definition_vi": "Nghĩa là 'không những X mà còn Y' — thêm một sự thật thứ hai, thường quan trọng hơn, vào sự thật đầu tiên.", "notes_ko": "만은 선택 사항이며 강조를 더할 뿐, 핵심 의미는 만이 있든 없든 같다.", "notes_vi": "만 là tùy chọn và chỉ thêm sự nhấn mạnh; ý nghĩa cốt lõi giống nhau dù có hay không có 만."}]$$::jsonb, $$["뿐만 아니라", "뿐 아니라"]$$::jsonb, false, now()),
('자마자', '-자마자', 'intermediate', 5, 2, 50, 50, $$[{"label": null, "definition": "Means 'as soon as X' — the second action happens immediately after the first, with no gap in between.", "formation": "Verb stem + -자마자", "examples": [["나는 방학을 하자마자 고향으로 돌아갈 생각이에요.", "As soon as school lets out, I plan to go back to my hometown."], ["개봉하자마자 관객 수가 20만 명을 넘었대요.", "As soon as it was released, it apparently drew over 200,000 viewers."]], "notes": "Both clauses must have a very short time gap between them; not used for actions separated by a longer interval.", "label_ko": null, "label_vi": null, "definition_ko": "'X하자마자'라는 뜻으로, 두 번째 행동이 첫 번째 행동 직후 간격 없이 일어난다.", "definition_vi": "Nghĩa là 'ngay khi X' — hành động thứ hai xảy ra ngay sau hành động thứ nhất, không có khoảng cách thời gian.", "notes_ko": "두 절 사이의 시간 간격이 매우 짧아야 하며, 간격이 긴 행동에는 쓰지 않는다.", "notes_vi": "Khoảng cách thời gian giữa hai vế phải rất ngắn; không dùng cho các hành động cách nhau lâu."}]$$::jsonb, $$["자마자"]$$::jsonb, false, now()),
('느라고', '-느라고', 'intermediate', 4, 3, 40, 50, $$[{"label": null, "definition": "Gives the reason for a negative or unfortunate result, where the cause is a time-consuming or effortful action: 'because I was busy doing X (something bad resulted).'", "formation": "Verb stem + -느라고", "examples": [["친구들이랑 노느라고 숙제를 못 했어요.", "I was busy hanging out with friends, so I couldn't do my homework."], ["밤새 시험 공부를 하느라고 한숨도 못 잤어요.", "I was up all night studying for the exam, so I didn't get a wink of sleep."]], "notes": "The result clause is almost always negative (couldn't do something, was late, etc.); both clauses must share the same subject.", "label_ko": null, "label_vi": null, "definition_ko": "부정적이거나 아쉬운 결과의 이유를 제시하며, 그 원인이 시간이나 노력이 드는 행동이다: 'X하느라고 (안 좋은 일이 생겼다)'.", "definition_vi": "Nêu lý do cho một kết quả tiêu cực hoặc đáng tiếc, khi nguyên nhân là một việc tốn thời gian/công sức: 'vì mải X nên (điều không hay xảy ra)'.", "notes_ko": "결과절은 거의 항상 부정적이다(못 했다, 늦었다 등). 두 절의 주어가 같아야 한다.", "notes_vi": "Vế kết quả hầu như luôn tiêu cực (không làm được, bị trễ, v.v.). Hai vế phải có cùng chủ ngữ."}]$$::jsonb, $$["느라고"]$$::jsonb, false, now()),
('사동-causative-voice', '사동 (Causative Voice)', 'advanced', 4, 4, 50, 50, $$[{"label": null, "definition": "The Korean causative voice, expressing that the subject makes or lets someone/something else perform an action: '(subject) makes/has X do Y.'", "formation": "Short causative: verb stem + 이/히/리/기/우/구/추 · Long causative: verb stem + -게 하다", "examples": [["밥도 먹이고 같이 놀아주기도 해요.", "I feed them and also play with them."], ["아이를 일찍 자게 했어요.", "I made the child go to sleep early."]], "notes": "Like the passive, only certain verbs take the short causative suffixes; -게 하다 works productively with almost any verb.", "label_ko": null, "label_vi": null, "definition_ko": "주어가 다른 사람/사물이 행동을 하게 만들거나 허락함을 나타내는 한국어의 사동태다: '(주어가) X에게 Y를 하게/시키다'.", "definition_vi": "Thể sai khiến trong tiếng Hàn, diễn tả chủ ngữ khiến hoặc cho phép người/vật khác thực hiện hành động: '(chủ ngữ) khiến/cho X làm Y'.", "notes_ko": "피동형처럼 특정 동사만 단형 사동 접미사를 쓰며, -게 하다는 거의 모든 동사에 생산적으로 쓸 수 있다.", "notes_vi": "Giống thể bị động, chỉ một số động từ dùng hậu tố sai khiến ngắn; -게 하다 dùng được với hầu hết mọi động từ."}]$$::jsonb, $$[]$$::jsonb, false, now()),
('을-ㄹ까-봐', '-을/ㄹ까 봐', 'intermediate', 5, 2, 35, 50, $$[{"label": null, "definition": "Expresses worry or concern that something (usually unwanted) might happen, and often explains a precaution taken because of that worry: 'because I was worried that X might happen.'", "formation": "Verb/Adj stem + -을/ㄹ까 봐", "examples": [["아이가 다칠까 봐 걱정이에요.", "I'm worried the child might get hurt."], ["대학교 입학시험에 떨어질까 봐 걱정이에요.", "I'm worried I might fail the university entrance exam."]], "notes": "Frequently paired with 걱정이다/걱정하다, but can also stand alone before an action taken as a precaution.", "label_ko": null, "label_vi": null, "definition_ko": "보통 원하지 않는 일이 일어날까 봐 걱정하는 마음을 나타내며, 그 걱정 때문에 취한 예방 조치를 설명할 때도 쓰인다: 'X할까 봐 (걱정이다)'.", "definition_vi": "Diễn tả sự lo lắng rằng điều gì đó (thường không mong muốn) có thể xảy ra, và thường giải thích biện pháp phòng ngừa vì lo lắng đó: 'lo rằng X sẽ xảy ra'.", "notes_ko": "걱정이다/걱정하다와 자주 함께 쓰이지만, 예방 조치로 취한 행동 앞에 단독으로도 쓸 수 있다.", "notes_vi": "Thường đi cùng 걱정이다/걱정하다, nhưng cũng có thể đứng riêng trước một hành động được thực hiện như biện pháp phòng ngừa."}]$$::jsonb, $$["을까 봐", "ㄹ까 봐"]$$::jsonb, false, now()),
('는-ㄴ다는-것이', '-는/ㄴ다는 것이', 'advanced', 2, 4, 45, 50, $$[{"label": null, "definition": "Describes an unintended slip or mistake: the speaker meant to do one thing but ended up doing something else instead — 'I meant to do X, but (ended up doing Y).'", "formation": "Verb stem + -는/ㄴ다는 것이 (+ unintended result)", "examples": [["전화를 끊는다는 것이 실수로 다른 사람한테 걸었어요.", "I meant to hang up the phone, but I accidentally called someone else instead."], ["친구에게 문자를 보낸다는 것이 실수로 다른 사람에게 보냈어요.", "I meant to text my friend, but I accidentally sent it to someone else instead."]], "notes": "Almost always followed by a clause describing the unintended slip; conveys mild embarrassment or apology.", "label_ko": null, "label_vi": null, "definition_ko": "의도치 않은 실수를 나타낸다: 화자가 한 가지를 하려 했지만 결국 다른 것을 하게 된 경우다 — 'X하려던 것이 (Y하게 됐다)'.", "definition_vi": "Diễn tả một sai lầm ngoài ý muốn: người nói định làm một việc nhưng lại vô tình làm việc khác — 'định X mà lại (thành Y)'.", "notes_ko": "거의 항상 뒤에 의도치 않은 결과를 설명하는 절이 따라오며, 약간의 당황함이나 사과의 뉘앙스를 담는다.", "notes_vi": "Hầu như luôn theo sau bởi một mệnh đề mô tả kết quả ngoài ý muốn; mang sắc thái hơi ngượng ngùng hoặc xin lỗi."}]$$::jsonb, $$["다는 것이"]$$::jsonb, false, now()),
('는-은-ㄴ-모양이다', '-는, 은/ㄴ 모양이다', 'intermediate', 4, 3, 45, 55, $$[{"label": null, "definition": "Expresses an inference based on visible evidence or circumstances: 'it looks like X / it seems that X (based on what I can see).'", "formation": "Verb (present) -는 모양이다 · Verb (past) -은/ㄴ 모양이다 · Adjective -(으)ㄴ 모양이다", "examples": [["수업 시간에 조는 걸 보니 피곤한 모양이에요.", "Seeing them dozing off in class, they seem to be tired."], ["집에 불이 꺼진 걸 보니 아무도 없는 모양이다.", "Seeing the lights off at home, it seems like no one's there."]], "notes": "Grounded specifically in observable evidence, similar in spirit to -는/은 것 같다 but slightly more formal/written in tone.", "label_ko": null, "label_vi": null, "definition_ko": "눈에 보이는 증거나 상황에 근거한 추측을 나타낸다: '보아하니 X인가 보다'.", "definition_vi": "Diễn tả một suy đoán dựa trên bằng chứng hoặc hoàn cảnh quan sát được: 'nhìn có vẻ như X'.", "notes_ko": "특히 관찰 가능한 증거에 근거하며, -는/은 것 같다와 비슷하지만 조금 더 격식적/문어체적이다.", "notes_vi": "Dựa cụ thể vào bằng chứng quan sát được, giống -는/은 것 같다 nhưng trang trọng/văn viết hơn một chút."}]$$::jsonb, $$["모양이다", "모양이에요", "모양이야"]$$::jsonb, true, now()),
('아-어-여-놓다-두다', '-아/어/여 놓다/두다', 'intermediate', 5, 2, 40, 50, $$[{"label": null, "definition": "Indicates that an action was completed and its result is intentionally being kept/maintained, often as preparation for something later: 'to do X (and leave it that way) / to do X in advance.'", "formation": "Verb stem + -아/어/여 놓다 or -아/어/여 두다", "examples": [["비자를 연장하려고 예약해 놓았거든요.", "You see, I made the reservation in advance to extend my visa."], ["문을 열어 두세요.", "Please leave the door open."]], "notes": "놓다 and 두다 are largely interchangeable; both emphasize that the resulting state is being deliberately preserved, often for future convenience.", "label_ko": null, "label_vi": null, "definition_ko": "행동이 완료되었고 그 결과가 의도적으로 유지되고 있음을 나타내며, 나중을 위한 준비인 경우가 많다: 'X해 놓다/두다'.", "definition_vi": "Diễn tả một hành động đã hoàn thành và kết quả của nó được cố ý duy trì, thường là để chuẩn bị cho sau này: 'X sẵn'.", "notes_ko": "놓다와 두다는 거의 같은 뜻으로 바꿔 쓸 수 있으며, 둘 다 결과 상태가 나중의 편의를 위해 의도적으로 유지됨을 강조한다.", "notes_vi": "놓다 và 두다 hầu như có thể thay thế cho nhau; cả hai đều nhấn mạnh trạng thái kết quả được cố ý giữ lại để tiện lợi sau này."}]$$::jsonb, $$["놓다", "놓았", "놓을", "두다", "두었"]$$::jsonb, false, now()),
('다-가-보면', '-다(가) 보면', 'intermediate', 5, 2, 40, 50, $$[{"label": null, "definition": "Means 'if you keep doing X, you will eventually find / it will turn out that Y' — a gradual process where a continuous action leads naturally to an outcome over time.", "formation": "Action verb stem + -다(가) 보면", "examples": [["계속 연습하다 보면 실력이 늘 거예요.", "If you keep on practicing, your skills will improve over time."], ["같이 생활하다 보면 서로 더 잘 이해하게 될 거예요.", "As you keep living together, you'll come to understand each other better."]], "notes": "-다가 emphasizes the ongoing nature of the action; -보면 adds the sense of 'discovering through experience.'", "label_ko": null, "label_vi": null, "definition_ko": "'계속 X하다 보면 결국 Y하게 될 것이다'라는 뜻으로, 지속적인 행동이 시간이 지나며 자연스럽게 결과로 이어지는 점진적 과정을 나타낸다.", "definition_vi": "Nghĩa là 'nếu cứ tiếp tục làm X, dần dần sẽ Y' — một quá trình dần dần trong đó hành động liên tục tự nhiên dẫn đến kết quả theo thời gian.", "notes_ko": "-다가는 행동의 지속성을 강조하고, -보면은 '경험을 통해 알게 되다'라는 뉘앙스를 더한다.", "notes_vi": "-다가 nhấn mạnh tính liên tục của hành động; -보면 thêm sắc thái 'nhận ra qua trải nghiệm'."}]$$::jsonb, $$["다 보면", "다가 보면"]$$::jsonb, false, now()),
('을-ㄹ-뻔하다', '-을/ㄹ 뻔하다', 'intermediate', 5, 2, 35, 50, $$[{"label": null, "definition": "Describes a near-miss: something almost happened but ultimately did not. 'Almost did X,' 'nearly X-ed,' 'came close to X-ing' — the event did NOT actually happen.", "formation": "Verb stem + -(으)ㄹ 뻔하다", "examples": [["길을 건너다가 차에 치일 뻔했어요.", "I was crossing the street and nearly got hit by a car."], ["아침에 급하게 뛰어오다가 넘어질 뻔했어요.", "I was rushing over this morning and almost tripped and fell."]], "notes": "Crucial: the event did not happen. Contrast with -았/었는데 which can set up a related follow-up clause.", "label_ko": null, "label_vi": null, "definition_ko": "하마터면 일어날 뻔했지만 결국 일어나지 않은 아슬아슬한 상황을 나타낸다: 'X할 뻔했다' — 실제로는 일어나지 않았다.", "definition_vi": "Diễn tả tình huống suýt xảy ra nhưng cuối cùng không xảy ra: 'suýt X' — sự việc thực ra KHÔNG xảy ra.", "notes_ko": "핵심은 그 일이 실제로 일어나지 않았다는 점이다. 후속 절을 이어갈 수 있는 -았/었는데와 대조된다.", "notes_vi": "Điểm mấu chốt: sự việc đã KHÔNG xảy ra. Khác với -았/었는데 vốn có thể dẫn tới một mệnh đề tiếp theo liên quan."}]$$::jsonb, $$["뻔했", "뻔하다", "뻔할"]$$::jsonb, true, now()),
('았-었-였더니', '-았/었/였더니', 'advanced', 3, 4, 35, 50, $$[{"label": null, "definition": "Connects a past action the speaker personally performed with a result or discovery that followed: 'I did X, and then (as a result) Y' or 'when I did X, I found that Y.'", "formation": "Verb stem + -았/었/였더니", "examples": [["매일 일찍 일어났더니 생활이 규칙적이 됐어요.", "I got up early every day, and as a result my routine became much more regular."], ["그 식당에 가 봤더니 이미 문을 닫았더라고요.", "I went to that restaurant, only to find it had already closed."]], "notes": "The first-person subject requirement distinguishes this from plain -더니 (third-person observation).", "label_ko": null, "label_vi": null, "definition_ko": "화자가 직접 한 과거 행동과 그로 인해 뒤따른 결과나 발견을 연결한다: 'X했더니 Y했다/그랬더라'.", "definition_vi": "Kết nối một hành động trong quá khứ do chính người nói thực hiện với kết quả hoặc phát hiện xảy ra sau đó: 'đã X thì thấy Y'.", "notes_ko": "주어가 반드시 1인칭(화자)이어야 하는 점이 3인칭 관찰을 나타내는 일반 -더니와 다르다.", "notes_vi": "Yêu cầu chủ ngữ nhất thiết phải là ngôi thứ nhất (người nói) — khác với -더니 thông thường vốn dùng để quan sát ngôi thứ ba."}]$$::jsonb, $$["았더니", "었더니", "였더니"]$$::jsonb, false, now()),
('기에는', '-기에는', 'advanced', 3, 4, 45, 50, $$[{"label": null, "definition": "Means 'for the purpose of X-ing, [something falls short / is too much / is just right].' Evaluates whether something is suitable, excessive, or insufficient relative to a purpose.", "formation": "Verb stem + -기에는", "examples": [["이 방은 혼자 쓰기에는 너무 넓어요.", "This room is too big for one person to use alone."], ["하루 만에 끝내기에는 할 일이 너무 많아요.", "There's too much to do to finish it all in just one day."]], "notes": "Often paired with 너무 or 충분히: 'too [adj] to do X' / 'not [adj] enough to do X.'", "label_ko": null, "label_vi": null, "definition_ko": "'X하는 목적/기준으로 보면 [무언가가 부족하다/과하다/딱 맞다]'라는 뜻으로, 어떤 행동에 비추어 적합한지 과한지 부족한지를 평가한다.", "definition_vi": "Nghĩa là 'xét theo mục đích/tiêu chuẩn X thì [điều gì đó không đủ/quá mức/vừa đủ]' — đánh giá mức độ phù hợp so với một hành động.", "notes_ko": "너무나 충분히와 함께 자주 쓰인다: 'X하기에는 너무 ~하다' / 'X하기에는 충분히 ~하지 않다'.", "notes_vi": "Thường đi cùng 너무 hoặc 충분히: 'quá... để X' / 'không đủ... để X'."}]$$::jsonb, $$["기에는"]$$::jsonb, false, now()),
('다니-이-라니', '-다니 / (이)라니', 'advanced', 3, 3, 30, 45, $$[{"label": null, "definition": "Expresses strong surprise, disbelief, or emotional reaction to something just heard: 'I can't believe that…,' 'to think that…!'", "formation": "Verb/Adj plain form + -다니 · Noun + -(이)라니", "examples": [["그 사람이 이미 결혼을 했다니 정말 놀라워요.", "I can't believe they're already married — that's really shocking."], ["이 가격에 이런 서비스라니, 너무 좋다!", "To think you get this kind of service at this price — this is amazing!"]], "notes": "The sentence often ends without a main predicate — the expression of emotion is the point.", "label_ko": null, "label_vi": null, "definition_ko": "방금 들은 일에 대한 강한 놀람이나 믿기지 않는 감정을 나타낸다: '~하다니 정말 놀랍다!', '~라니!'.", "definition_vi": "Diễn tả sự ngạc nhiên mạnh mẽ hoặc không thể tin được về điều vừa nghe: 'không thể tin được là...!'.", "notes_ko": "문장이 서술어 없이 끝나는 경우가 많다 — 감정 표현 자체가 핵심이다.", "notes_vi": "Câu thường kết thúc mà không có vị ngữ chính — bản thân việc thể hiện cảm xúc mới là trọng tâm."}]$$::jsonb, $$["다니", "라니"]$$::jsonb, false, now()),
('을-ㄹ-수가-있어야지-요', '-을/ㄹ 수가 있어야지(요)', 'advanced', 2, 4, 15, 35, $$[{"label": null, "definition": "A rhetorical negative: 'there's no way one can X' or 'how could anyone possibly X?' Emphasizes that something is completely out of the question.", "formation": "Verb stem + -(으)ㄹ 수가 있어야지(요)", "examples": [["이렇게 시끄러운데 잠을 잘 수가 있어야지요.", "With all this noise, there's no way anyone could sleep."], ["물가가 이렇게 비싼데 돈을 모을 수가 있어야지요.", "With prices this high, there's just no way anyone could save money."]], "notes": "The -야지 ending signals a condition that isn't met; combined with 있어야, the phrase rhetorically denies possibility.", "label_ko": null, "label_vi": null, "definition_ko": "반어적인 부정을 나타낸다: 'X할 수가 있어야지요' — '도저히 X할 수 없다'는 뜻으로, 무언가가 완전히 불가능함을 강조한다.", "definition_vi": "Là một cách phủ định mang tính phản vấn: 'làm sao mà X được' — nhấn mạnh rằng điều gì đó hoàn toàn không thể xảy ra.", "notes_ko": "-야지 어미는 충족되지 않은 조건을 나타내며, 있어야와 결합해 전체적으로 가능성을 반어적으로 부정한다.", "notes_vi": "Đuôi -야지 biểu thị một điều kiện không được đáp ứng; kết hợp với 있어야, cả cụm phản vấn phủ nhận khả năng xảy ra."}]$$::jsonb, $$["수가 있어야지"]$$::jsonb, true, now()),
('을-ㄹ-뿐이다', '-을/ㄹ 뿐이다', 'intermediate', 4, 3, 55, 55, $$[{"label": null, "definition": "Means 'it is merely / only X; nothing more.' Limits the scope of something and can express resigned acceptance: 'all one can do is X.'", "formation": "Verb stem + -(으)ㄹ 뿐이다", "examples": [["저는 그냥 제 의견을 말했을 뿐이에요.", "I merely expressed my own opinion — nothing more than that."], ["그는 아무 말도 없이 웃고만 있을 뿐이다.", "He's just smiling without saying anything."]], "notes": "More formal/reflective in tone than -만; excludes anything beyond what is stated.", "label_ko": null, "label_vi": null, "definition_ko": "'그저 X일 뿐이다, 그 이상은 아니다'라는 뜻이다. 어떤 것의 범위를 제한하며, 체념적 수용을 나타내기도 한다: '그저 X할 뿐이다'.", "definition_vi": "Nghĩa là 'chỉ là X thôi, không hơn'. Giới hạn phạm vi của điều gì đó, đôi khi thể hiện sự chấp nhận cam chịu: 'chỉ có thể X thôi'.", "notes_ko": "만보다 더 격식적이고 사색적인 어조를 띠며, 언급된 것 이상은 배제한다.", "notes_vi": "Mang giọng điệu trang trọng, chiêm nghiệm hơn 만; loại trừ mọi thứ ngoài điều đã nêu."}]$$::jsonb, $$["뿐이다", "뿐이에요", "뿐이야"]$$::jsonb, true, now()),
('았-었-였더라면', '-았/었/였더라면', 'advanced', 3, 4, 55, 50, $$[{"label": null, "definition": "A past counterfactual conditional: 'if X had been the case (but it wasn't), then Y would have happened.' Expresses regret, relief, or speculation about the past.", "formation": "Verb/Adj stem + -았/었/였더라면", "examples": [["더 열심히 공부했더라면 좋은 결과를 얻었을 거예요.", "If I had studied harder, I would have gotten better results."], ["시험 준비를 열심히 했더라면 합격했을 텐데.", "If I had prepared hard for the exam, I would have passed."]], "notes": "Both clauses refer to the past and the condition is contrary to fact; often paired with -았/었을 텐데 or -았/었을 거예요.", "label_ko": null, "label_vi": null, "definition_ko": "과거 사실에 반하는 조건문이다: '만약 X했더라면 (그러지 않았지만) Y했을 것이다'. 후회, 안도, 또는 과거에 대한 추측을 나타낸다.", "definition_vi": "Là câu điều kiện phản thực trong quá khứ: 'nếu đã X (nhưng thực tế không) thì đã Y'. Diễn tả sự hối tiếc, nhẹ nhõm hoặc suy đoán về quá khứ.", "notes_ko": "두 절 모두 과거를 가리키며 조건은 사실에 반한다. -았/었을 텐데나 -았/었을 거예요와 자주 함께 쓰인다.", "notes_vi": "Cả hai vế đều chỉ quá khứ và điều kiện trái với sự thật; thường đi cùng -았/었을 텐데 hoặc -았/었을 거예요."}]$$::jsonb, $$["더라면"]$$::jsonb, false, now()),
('다가는', '-다가는', 'advanced', 3, 3, 35, 45, $$[{"label": null, "definition": "Warns that if the current behavior continues, a negative consequence will result: 'if you keep on doing X, Y (bad thing) will happen.'", "formation": "Verb stem + -다가는", "examples": [["그렇게 무리하다가는 건강을 해칠 거예요.", "If you keep pushing yourself like that, you'll ruin your health."], ["그렇게 계속 늦잠을 자다가는 지각하기 십상이에요.", "If you keep oversleeping like that, you're bound to end up late."]], "notes": "The result clause is almost always negative — different from -다 보면, which is neutral or positive about gradual outcomes.", "label_ko": null, "label_vi": null, "definition_ko": "지금의 행동이 계속되면 부정적인 결과가 생길 것이라고 경고한다: '그렇게 계속 X하다가는 (안 좋은 일) Y가 생길 것이다'.", "definition_vi": "Cảnh báo rằng nếu tiếp tục hành vi hiện tại, hậu quả tiêu cực sẽ xảy ra: 'cứ tiếp tục X kiểu đó thì Y (điều xấu) sẽ xảy ra'.", "notes_ko": "결과절은 거의 항상 부정적이다 — 점진적 결과에 대해 중립적이거나 긍정적인 -다 보면과 다르다.", "notes_vi": "Vế kết quả hầu như luôn tiêu cực — khác với -다 보면 vốn trung tính hoặc tích cực về kết quả dần dần."}]$$::jsonb, $$["다가는"]$$::jsonb, false, now()),
('는-은-ㄴ-을-ㄹ-듯-이', '-는/은/ㄴ/을/ㄹ 듯(이)', 'advanced', 3, 4, 55, 50, $$[{"label": null, "definition": "Means 'as if X' or 'as though X' — describes the manner of an action by comparing it to something else. 듯이 is adverbial; 듯 alone can modify a noun.", "formation": "Verb/Adj modifier + 듯(이)", "examples": [["날아갈 듯이 기뻤어요.", "I was so happy it felt like I could fly."], ["그 사람은 돈을 물 쓰듯이 쓴다.", "That person spends money like water."]], "notes": "Similar to -는 것처럼 but slightly more literary/poetic in tone.", "label_ko": null, "label_vi": null, "definition_ko": "'마치 X인 것처럼'이라는 뜻으로, 어떤 것에 비유해 행동이나 상태의 모습을 묘사한다. 듯이는 부사형이고, 듯만 쓰면 명사를 수식할 수 있다.", "definition_vi": "Nghĩa là 'như thể X' — mô tả cách thức của một hành động/trạng thái bằng cách so sánh với điều gì đó. 듯이 là dạng trạng từ; 듯 một mình có thể bổ nghĩa cho danh từ.", "notes_ko": "-는 것처럼과 비슷하지만 좀 더 문학적이거나 시적인 어조를 띤다.", "notes_vi": "Tương tự -는 것처럼 nhưng mang giọng điệu văn chương/thơ mộng hơn một chút."}]$$::jsonb, $$["듯이", "듯"]$$::jsonb, false, now()),
('아-어-여-버리다', '-아/어/여 버리다', 'intermediate', 5, 2, 30, 50, $$[{"label": null, "definition": "Indicates an action was completed fully and decisively, often with a sense of relief, regret, or finality — the action is done and there's no going back.", "formation": "Verb stem + -아/어/여 버리다", "examples": [["오래된 옷들을 전부 버려 버렸어요.", "I just went ahead and threw out all my old clothes."], ["실수로 중요한 파일을 삭제해 버렸어요.", "I accidentally deleted the important file — and now it's gone."]], "notes": "The emotional nuance (relief vs. regret) is determined by context, not by the grammar itself.", "label_ko": null, "label_vi": null, "definition_ko": "행동이 완전하고 결정적으로 끝났음을 나타내며, 안도·후회·최종성의 느낌을 담는 경우가 많다: 'X해 버리다' — 되돌릴 수 없다.", "definition_vi": "Diễn tả một hành động đã hoàn thành trọn vẹn và dứt khoát, thường mang cảm giác nhẹ nhõm, hối tiếc hoặc dứt điểm: 'X luôn/mất' — không thể quay lại.", "notes_ko": "안도인지 후회인지의 감정적 뉘앙스는 문법 자체가 아니라 문맥에 따라 결정된다.", "notes_vi": "Sắc thái cảm xúc (nhẹ nhõm hay hối tiếc) do ngữ cảnh quyết định, không phải do bản thân ngữ pháp."}]$$::jsonb, $$["버리다", "버렸", "버릴"]$$::jsonb, false, now()),
('으라고-라고', '-으라고/라고', 'advanced', 4, 4, 45, 50, $$[{"label": null, "definition": "Reports an indirect command, instruction, or request: 'X told/asked/said [for someone] to do Y.' Can also express purpose with motion verbs: 'in order to do Y.'", "formation": "Verb stem + -(으)라고 (indirect command)", "examples": [["선생님이 내일까지 제출하라고 하셨어요.", "The teacher said to submit it by tomorrow."], ["조용히 하라고 했는데 왜 계속 떠들어요?", "I told you to be quiet — why do you keep making noise?"]], "notes": "Distinguish from -라고 (quoting declarative sentences) and plain -고 (quoting statements) — this specifically quotes commands.", "label_ko": null, "label_vi": null, "definition_ko": "누군가가 한 간접 명령, 지시, 요청을 전달한다: 'X가 Y하라고 했다'. 이동 동사와 함께 쓰이면 목적('~하기 위해')을 나타내기도 한다.", "definition_vi": "Thuật lại một mệnh lệnh, chỉ dẫn hoặc yêu cầu gián tiếp: 'X bảo Y làm gì đó'. Khi đi với động từ chuyển động cũng có thể diễn tả mục đích ('để làm gì').", "notes_ko": "선언문을 인용하는 -라고, 그리고 단순 인용의 -고와 구별해야 한다 — 이것은 특히 명령을 인용한다.", "notes_vi": "Cần phân biệt với -라고 (trích dẫn câu trần thuật) và -고 (trích dẫn đơn thuần) — mẫu này chuyên dùng để trích dẫn mệnh lệnh."}]$$::jsonb, $$["으라고", "라고"]$$::jsonb, false, now()),
('는-ㄴ-다-싶다', '-는/ㄴ, -다 싶다', 'advanced', 3, 4, 35, 45, $$[{"label": null, "definition": "Expresses the speaker's internal impression or fleeting thought at a moment: 'I thought/felt/it seemed to me that X.' Captures an intuitive impression rather than deliberate reasoning.", "formation": "Verb/Adj modifier or plain form + 싶다", "examples": [["이러다가 늦겠다 싶어서 서둘렀어요.", "I had the feeling I was going to be late, so I hurried."], ["그 사람 말이 맞는 것 같다 싶었어요.", "I had the impression that what that person said might actually be right."]], "notes": "The present modifier (-는/ㄴ 싶다) describes current impressions; the plain form (-다 싶다) quotes a thought more directly.", "label_ko": null, "label_vi": null, "definition_ko": "화자가 그 순간 느낀 인상이나 생각을 나타낸다: '~라고 생각했다/느꼈다/그런 것 같았다'. 심사숙고보다는 순간적이고 직관적인 인상을 담는다.", "definition_vi": "Diễn tả ấn tượng hoặc suy nghĩ thoáng qua của người nói tại một thời điểm: 'cảm thấy/nghĩ là...'. Là ấn tượng trực giác, không phải suy luận có chủ đích.", "notes_ko": "현재형 수식 표현(-는/ㄴ 싶다)은 현재의 인상을 나타내고, 평서형(-다 싶다)은 생각을 더 직접적으로 인용한다.", "notes_vi": "Dạng hiện tại (-는/ㄴ 싶다) diễn tả ấn tượng hiện tại; dạng nguyên thể (-다 싶다) trích dẫn suy nghĩ trực tiếp hơn."}]$$::jsonb, $$["다 싶", "나 싶"]$$::jsonb, false, now()),
('는가-은-ㄴ가-하면', '-는가, 은/ㄴ가 하면', 'advanced', 2, 4, 70, 55, $$[{"label": null, "definition": "Introduces one item in a contrasting or listing pair: 'while on the one hand X, on the other hand Y.' Presents two contrasting or complementary examples.", "formation": "Verb/Adj modifier + -는가/은가/ㄴ가 하면", "examples": [["전통을 중요시하는가 하면, 변화를 원하는 사람도 많아요.", "While some value tradition highly, there are also many people who want change."], ["값이 싼 물건이 있는가 하면 터무니없이 비싼 물건도 있다.", "There are items that are cheap, while there are also ones that are absurdly expensive."]], "notes": "Common in expository writing/speech when surveying different aspects of a topic.", "label_ko": null, "label_vi": null, "definition_ko": "대조되거나 나열되는 쌍 중 하나를 제시한다: '한편으로는 X, 다른 한편으로는 Y'. 서로 대조되거나 상호 보완적인 두 예시나 측면을 보여줄 때 쓴다.", "definition_vi": "Giới thiệu một vế trong cặp đối lập hoặc liệt kê: 'một mặt thì X, mặt khác thì Y'. Dùng để trình bày hai ví dụ hoặc khía cạnh tương phản/bổ sung cho nhau.", "notes_ko": "어떤 주제의 다양한 측면을 살펴보는 설명적인 글이나 말에서 흔히 쓰인다.", "notes_vi": "Thường dùng trong văn nói/viết mang tính khảo sát khi xem xét các khía cạnh khác nhau của một chủ đề."}]$$::jsonb, $$["가 하면"]$$::jsonb, false, now()),
('긴-나-봐요', '-긴 -나 봐요', 'advanced', 2, 4, 20, 40, $$[{"label": null, "definition": "Concedes a point while signaling something else is also true or an inference: 'I'll grant you X, but apparently/it seems Y.'", "formation": "Verb/Adj stem + -긴 하다 / -긴 -나 봐요", "examples": [["바쁘긴 바쁜데 그래도 운동은 해야 하나 봐요.", "Admittedly I am busy, but it seems I still need to find time to exercise."], ["맵긴 하나 봐요. 그래도 사람들이 줄을 서서 먹더라고요.", "It does seem to be spicy, yet people were lining up to eat it."]], "notes": "The -긴 portion must repeat the same verb stem: 가긴 가다, 좋긴 좋다.", "label_ko": null, "label_vi": null, "definition_ko": "한 가지를 인정하면서('그렇긴 하지만') 동시에 다른 것도 사실임을 암시하거나 추측을 나타낸다: '~하긴 한데 그래도/아무래도 Y인가 보다'.", "definition_vi": "Thừa nhận một điều ('đúng là vậy') trong khi ngụ ý điều khác cũng đúng, hoặc đưa ra một suy đoán: 'đúng là X nhưng hình như Y'.", "notes_ko": "-긴 부분은 반드시 같은 동사 어간을 반복해야 한다: 가긴 가다, 좋긴 좋다.", "notes_vi": "Phần -긴 nhất thiết phải lặp lại cùng một gốc động từ: 가긴 가다, 좋긴 좋다."}]$$::jsonb, $$["나 봐요", "긴 하"]$$::jsonb, false, now()),
('아무리-기로서니', '(아무리) -기로서니', 'advanced', 1, 5, 65, 40, $$[{"label": null, "definition": "Used to rebuke or express disbelief: 'even granting that X is the case, how could you possibly do Y?' Often paired with 아무리 for intensity.", "formation": "Verb/Adj stem + -기로서니", "examples": [["아무리 바쁘기로서니 식사도 건너뛰면 안 되죠.", "No matter how busy you are, skipping meals entirely is just not okay."], ["아무리 화가 나기로서니 그렇게 소리를 지르면 안 되지.", "No matter how angry you are, you shouldn't yell like that."]], "notes": "Conveys mild reproach or surprise; the result clause is almost always negative in tone.", "label_ko": null, "label_vi": null, "definition_ko": "질책하거나 믿기지 않음을 나타낼 때 쓴다: '아무리 X하기로서니 어떻게 Y할 수 있어?'. 전제는 인정하지만 그것이 결과를 정당화하지 못한다고 주장한다.", "definition_vi": "Dùng để trách móc hoặc bày tỏ sự không thể tin được: 'dù có X đi nữa thì sao có thể Y được?'. Thừa nhận tiền đề nhưng cho rằng nó không biện minh được cho kết quả.", "notes_ko": "가벼운 질책이나 놀람을 전달하며, 결과절은 거의 항상 부정적인 어조를 띤다.", "notes_vi": "Truyền tải sự trách móc hoặc ngạc nhiên nhẹ; vế kết quả hầu như luôn mang giọng điệu tiêu cực."}]$$::jsonb, $$["기로서니"]$$::jsonb, false, now()),
('기는커녕', '-기는커녕', 'advanced', 3, 4, 40, 45, $$[{"label": null, "definition": "A strong negative concession meaning 'far from doing X, not even Y.' Not only did the greater thing not happen, but even the lesser thing didn't either.", "formation": "Verb/Adj/Noun + -기는커녕", "examples": [["감사하기는커녕 오히려 화를 내더라고요.", "Far from being thankful, she actually got angry at me."], ["사과하기는커녕 오히려 저한테 잘못을 떠넘기더라고요.", "Far from apologizing, he actually tried to pin the blame on me instead."]], "notes": "The clause after -기는커녕 typically describes something worse or lesser than the first clause.", "label_ko": null, "label_vi": null, "definition_ko": "'X는커녕 Y조차도 아니다'라는 강한 부정적 양보를 나타낸다. 더 큰 일이 일어나지 않았을 뿐 아니라 더 작은 일조차 일어나지 않았음을 나타낸다.", "definition_vi": "Là một cách nhượng bộ phủ định mạnh mẽ: 'đừng nói là X, ngay cả Y cũng không'. Không những điều lớn hơn không xảy ra, mà ngay cả điều nhỏ hơn cũng không.", "notes_ko": "-기는커녕 뒤에 오는 절은 보통 첫 번째보다 더 나쁘거나 못한 상황을 묘사한다.", "notes_vi": "Mệnh đề sau -기는커녕 thường mô tả điều tệ hơn hoặc kém hơn so với mệnh đề đầu."}]$$::jsonb, $$["기는커녕"]$$::jsonb, false, now()),
('는-둥-마는-둥-하다', '-는 둥 마는 둥 하다', 'advanced', 2, 4, 20, 40, $$[{"label": null, "definition": "Describes doing something so half-heartedly or carelessly that one can hardly say it was done at all: 'barely going through the motions.'", "formation": "Action verb stem + -는 둥 마는 둥 하다", "examples": [["밥을 먹는 둥 마는 둥 하고 바로 나가 버렸어요.", "He barely touched his food and then left right away."], ["어제는 너무 피곤해서 씻는 둥 마는 둥 하고 바로 잤어요.", "I was so tired yesterday that I barely washed up before going straight to sleep."]], "notes": "Always describes a volitional action; cannot be used with states or adjectives.", "label_ko": null, "label_vi": null, "definition_ko": "너무 건성으로, 대충 해서 했다고 말하기도 어려운 정도를 나타낸다: '건성으로 하는 둥 마는 둥 하다'.", "definition_vi": "Diễn tả việc làm gì đó qua loa, cẩu thả đến mức khó có thể nói là đã làm: 'làm cho có, làm qua loa'.", "notes_ko": "항상 의지적 행동을 묘사하며, 상태나 형용사에는 쓸 수 없다.", "notes_vi": "Luôn mô tả một hành động có chủ ý; không dùng được với trạng thái hoặc tính từ."}]$$::jsonb, $$["둥 마는 둥"]$$::jsonb, false, now()),
('으-랴-으-랴', '-(으)랴 -(으)랴', 'advanced', 1, 5, 25, 40, $$[{"label": null, "definition": "Enumerates two or more demanding actions happening at once, conveying that the subject is overwhelmed: 'what with X-ing and Y-ing.'", "formation": "Verb stem + -(으)랴 … -(으)랴 (two different verbs)", "examples": [["애들 돌보랴 집안일 하랴 정신이 없어요.", "What with looking after the kids and keeping up with the housework, I'm completely frazzled."], ["손님을 맞으랴 음식을 준비하랴 하루 종일 바빴어요.", "What with greeting guests and preparing food, I was busy all day long."]], "notes": "Usually spoken/informal, expressing being pulled in multiple directions.", "label_ko": null, "label_vi": null, "definition_ko": "동시에 벌어지는 두세 가지 부담스러운 일을 나열하며, 주어가 그것들을 감당하느라 정신없음을 전달한다: 'X하랴 Y하랴 정신이 없다'.", "definition_vi": "Liệt kê hai hoặc nhiều việc nặng nề xảy ra cùng lúc, thể hiện chủ thể đang quay cuồng vì phải xử lý cả hai: 'vừa X vừa Y, bận không kịp thở'.", "notes_ko": "구어체나 격식 없는 문체에서 여러 방향으로 정신없이 시달림을 나타낼 때 주로 쓴다.", "notes_vi": "Chủ yếu dùng trong văn nói/không trang trọng để diễn tả cảm giác bị kéo về nhiều hướng cùng lúc."}]$$::jsonb, $$[]$$::jsonb, false, now()),
('으-면-몰라도', '-(으)면 몰라도', 'advanced', 2, 4, 45, 50, $$[{"label": null, "definition": "Introduces the only condition under which the main clause might be acceptable, implying that since it doesn't hold, the main clause is unreasonable: 'unless X, Y is out of the question.'", "formation": "Verb/Adj stem + -(으)면 몰라도 · Noun + -(이)면 몰라도", "examples": [["전문가면 몰라도 초보자가 그 일을 하기는 어려워요.", "Unless you're an expert, it's really hard for a beginner to do that kind of work."], ["돈이 많으면 몰라도 지금 형편으로는 유학이 어려워요.", "Unless we had a lot of money, studying abroad is difficult given our current situation."]], "notes": "The speaker typically implies the condition is unlikely or counterfactual.", "label_ko": null, "label_vi": null, "definition_ko": "본절이 받아들여질 수 있는 유일한 가정 조건을 제시하며, 그 조건이 성립하지 않으므로 본절이 무리하거나 받아들이기 어렵다고 암시한다: 'X라면 몰라도, Y는 아니다'.", "definition_vi": "Đưa ra điều kiện giả định duy nhất mà mệnh đề chính có thể chấp nhận được, ngụ ý vì điều kiện đó không đúng nên mệnh đề chính là vô lý: 'nếu là X thì còn được, chứ Y thì không'.", "notes_ko": "화자는 보통 그 조건이 일어날 가능성이 낮거나 사실이 아님을 암시한다.", "notes_vi": "Người nói thường ngụ ý điều kiện đó khó xảy ra hoặc trái với thực tế."}]$$::jsonb, $$["면 몰라도"]$$::jsonb, false, now()),
('건만-건마는', '-건만 (-건마는)', 'advanced', 1, 5, 80, 50, $$[{"label": null, "definition": "A literary/formal connective expressing disappointment or lament: 'even though X, unfortunately Y.' Stronger and more poetic than -지만.", "formation": "Verb/Adj stem + -건만", "examples": [["열심히 준비했건만 결과는 좋지 않았어요.", "I prepared so hard for it, and yet the results were disappointing."], ["몸은 힘들건만 마음만은 행복했어요.", "My body was exhausted, and yet my heart was happy."]], "notes": "Common in literature, song lyrics, and formal essays; the longer form -건마는 is also correct.", "label_ko": null, "label_vi": null, "definition_ko": "실망이나 한탄, 대조를 나타내는 문어체적·문학적 연결어미다: 'X이지만(안타깝게도) Y'. -지만보다 강하고 시적이다.", "definition_vi": "Là liên từ mang tính văn chương, trang trọng, diễn tả sự thất vọng hoặc than tiếc: 'dù X (đáng tiếc thay) nhưng Y'. Mạnh và thơ mộng hơn -지만.", "notes_ko": "문학, 노래 가사, 격식 있는 수필에서 자주 쓰인다. 긴 형태인 -건마는도 맞는 표현이다.", "notes_vi": "Thường gặp trong văn học, lời bài hát, tiểu luận trang trọng. Dạng dài hơn -건마는 cũng đúng."}]$$::jsonb, $$["건만"]$$::jsonb, false, now()),
('같아선-같아서는', '같아선 (같아서는)', 'advanced', 1, 4, 25, 40, $$[{"label": null, "definition": "Means 'judging from the perspective of / if things stay as they are with X.' Often used for predictions or fears based on a current state.", "formation": "Noun/pronoun + 같아선 / 같아서는", "examples": [["이 속도 같아선 마감을 맞추기가 힘들 것 같아요.", "At this rate, it looks like we'll have trouble meeting the deadline."], ["내 마음 같아선 지금 당장 그만두고 싶어요.", "If it were up to how I feel, I'd want to quit right this instant."]], "notes": "Short for -과 같아서는; frequently combined with future tense or a warning tone.", "label_ko": null, "label_vi": null, "definition_ko": "'X의 관점에서 보면 / 지금 이대로라면'이라는 뜻이다. 현재 상태나 사람의 행동을 바탕으로 한 판단, 예측, 걱정을 나타낼 때 쓴다.", "definition_vi": "Nghĩa là 'xét theo góc nhìn của X / nếu cứ như thế này'. Dùng để đưa ra nhận định, dự đoán hoặc lo lắng dựa trên tình trạng hiện tại.", "notes_ko": "-과 같아서는의 줄임말이며, 미래 시제나 경고하는 어조와 자주 함께 쓰인다.", "notes_vi": "Là dạng rút gọn của -과 같아서는; thường đi cùng thì tương lai hoặc giọng điệu cảnh báo."}]$$::jsonb, $$["같아선", "같아서는"]$$::jsonb, true, now()),
('은-ㄴ-채-로', '-은/ㄴ 채(로)', 'advanced', 3, 3, 50, 50, $$[{"label": null, "definition": "Describes a state that remains unchanged while a second action takes place: 'with X still in place,' 'while remaining X.'", "formation": "Action verb past modifier (-은/ㄴ) + 채(로)", "examples": [["신발을 신은 채로 방에 들어오지 마세요.", "Please don't come into the room with your shoes still on."], ["불을 켠 채로 잠이 들어 버렸어요.", "I fell asleep with the lights still on."]], "notes": "The condition must result from a previous action, so the verb must be an action verb, not a descriptive adjective.", "label_ko": null, "label_vi": null, "definition_ko": "두 번째 행동이 일어나는 동안 변하지 않고 유지되는 상태나 조건을 나타낸다: 'X한 채로 (그대로 두고) Y하다'.", "definition_vi": "Diễn tả một trạng thái/điều kiện không thay đổi trong khi hành động thứ hai diễn ra: 'giữ nguyên X mà Y'.", "notes_ko": "그 상태는 이전 행동의 결과여야 하므로 동사는 반드시 동작 동사여야 하고 형용사는 쓸 수 없다.", "notes_vi": "Trạng thái đó phải là kết quả của một hành động trước đó, nên động từ phải là động từ hành động, không dùng được với tính từ."}]$$::jsonb, $$["은 채로", "ㄴ 채로", "은 채", "ㄴ 채"]$$::jsonb, false, now()),
('으-련만-으-련마는', '(으)련만 ((으)련마는)', 'advanced', 1, 5, 80, 50, $$[{"label": null, "definition": "Expresses a wistful, regretful, or counterfactual wish: 'if only X were the case, Y would be true — but it isn't.'", "formation": "Verb/Adj stem + -(으)련만", "examples": [["시간이 있으련만, 요즘은 너무 바빠서 힘드네요.", "If only I had the time — but lately I've been so busy it's just not possible."], ["돈이 좀 있으련만, 다 써 버려서 하나도 없네요.", "I wish I had some money — but I've spent it all, so I have none."]], "notes": "More formal/literary than -면 좋겠는데; closely related to -건만 in tone.", "label_ko": null, "label_vi": null, "definition_ko": "아쉽거나 후회스럽거나 사실과 반대되는 소망을 나타낸다: 'X이면 좋으련만 (그렇지 않다)'. 화자는 그 조건이 이루어질 수 없음을 알면서도 그 간극을 아쉬워한다.", "definition_vi": "Diễn tả một điều ước tiếc nuối, mang tính trái ngược thực tế: 'giá mà X thì tốt biết mấy (nhưng không phải vậy)'. Người nói biết điều kiện đó không thể đạt được nhưng vẫn tiếc nuối.", "notes_ko": "-건만과 어조가 비슷하며 둘 다 시적이고 애상적인 느낌을 담는다.", "notes_vi": "Giọng điệu gần giống -건만; cả hai đều mang cảm giác thơ mộng, u hoài."}]$$::jsonb, $$["련만"]$$::jsonb, true, now()),
('거니와', '-거니와', 'advanced', 1, 5, 85, 60, $$[{"label": null, "definition": "A formal connective meaning 'not only X, but also Y,' adding a second piece of information with escalating weight. More formal than -뿐만 아니라.", "formation": "Verb/Adj stem + -거니와", "examples": [["그분은 실력이 뛰어나거니와 인품도 훌륭합니다.", "Not only is she highly skilled, but her character is also admirable."], ["이 식당은 음식도 맛있거니와 서비스도 훌륭하다.", "Not only is the food at this restaurant delicious, but the service is excellent as well."]], "notes": "Common in speeches, academic writing, and news; both clauses typically share a similar sentiment.", "label_ko": null, "label_vi": null, "definition_ko": "'X할 뿐만 아니라 Y도'라는 뜻의 격식체 연결어미로, 첫 번째 정보 위에 더 무게 있는 두 번째 정보를 덧붙인다. -뿐만 아니라보다 더 격식적이다.", "definition_vi": "Là liên từ trang trọng nghĩa là 'không những X mà còn Y', thêm một thông tin thứ hai có trọng lượng hơn vào thông tin đầu. Trang trọng hơn -뿐만 아니라.", "notes_ko": "연설, 학술적 글쓰기, 뉴스에서 흔히 쓰이며, 두 절은 보통 비슷한 어조(둘 다 긍정적이거나 둘 다 부정적)를 띤다.", "notes_vi": "Thường gặp trong diễn văn, văn học thuật, tin tức; hai vế thường có cùng sắc thái (cùng tích cực hoặc cùng tiêu cực)."}]$$::jsonb, $$["거니와"]$$::jsonb, false, now()),
('더라도', '-더라도', 'intermediate', 4, 3, 55, 55, $$[{"label": null, "definition": "Means 'even if X is or were the case, Y still holds.' A strong concessive: the speaker grants the hypothetical truth of the first clause but insists the second still applies.", "formation": "Verb/Adj stem + -더라도", "examples": [["힘들더라도 포기하지 마세요.", "Even if it gets hard, please don't give up."], ["비가 오더라도 행사는 예정대로 진행됩니다.", "Even if it rains, the event will proceed as scheduled."]], "notes": "Can refer to real or hypothetical situations; does not specify whether the condition is actually true.", "label_ko": null, "label_vi": null, "definition_ko": "'설령 X이더라도(이라 하더라도) Y는 여전히 유효하다'는 뜻이다. 앞 절의 가정적 사실을 인정하면서도 뒤 절이 여전히 성립한다고 주장하는 강한 양보를 나타낸다.", "definition_vi": "Nghĩa là 'dù cho X có xảy ra thì Y vẫn đúng'. Diễn tả sự nhượng bộ mạnh mẽ: thừa nhận sự thật giả định của vế trước nhưng khẳng định vế sau vẫn đúng.", "notes_ko": "실제 상황이든 가상 상황이든 가리킬 수 있으며, 조건이 사실인지 아닌지는 특정하지 않는다.", "notes_vi": "Có thể chỉ tình huống thật hoặc giả định; không xác định điều kiện có đúng hay không."}]$$::jsonb, $$["더라도"]$$::jsonb, false, now()),
('더라고-요', '-더라고(요)', 'intermediate', 5, 2, 30, 50, $$[{"label": null, "definition": "Reports a first-hand observation the speaker discovered in the past, now shared as new information: 'I saw/found/noticed that X.' Expresses evidentiality — direct sensory evidence.", "formation": "Verb/Adj stem + -더라고(요)", "examples": [["그 식당 음식이 정말 맛있더라고요.", "I noticed (tried it and found) that the food at that restaurant was really delicious."], ["어제 공원에 갔는데 사람이 정말 많더라고요.", "I went to the park yesterday, and there were so many people there, I noticed."]], "notes": "Cannot be used for things you couldn't directly observe; the -고요 ending softens it into a conversational tone.", "label_ko": null, "label_vi": null, "definition_ko": "화자가 과거에 직접 목격하거나 알게 된 것을 새로운 정보로 전달한다: '(직접 보니/느껴보니) X이더라고요'. 화자가 직접 감각적·지각적 증거를 가지고 있음을 나타낸다.", "definition_vi": "Truyền đạt một quan sát/trải nghiệm trực tiếp mà người nói phát hiện trong quá khứ, giờ chia sẻ như thông tin mới: '(tôi thấy/trải nghiệm) là X đó'. Thể hiện người nói có bằng chứng cảm quan trực tiếp.", "notes_ko": "직접 관찰할 수 없는 것에는 쓸 수 없다. -고요 어미가 붙어 대화체로 부드러워진다.", "notes_vi": "Không dùng được cho điều không thể quan sát trực tiếp. Đuôi -고요 làm câu trở nên mềm mại, thân mật hơn."}]$$::jsonb, $$["더라고요", "더라고"]$$::jsonb, true, now()),
('음으로써', '-음으로써', 'advanced', 2, 4, 80, 55, $$[{"label": null, "definition": "Expresses the means or method by which a result is achieved: 'by doing X, Y is accomplished.' More formal/written than -해서.", "formation": "Verb stem + -음으로써", "examples": [["꾸준히 연습함으로써 실력을 키울 수 있어요.", "By practicing consistently, you can build up your skills."], ["적극적으로 참여함으로써 좋은 결과를 얻을 수 있었다.", "By participating actively, we were able to achieve good results."]], "notes": "The full form is -음으로써; -음으로 alone is used but is slightly less emphatic about the means.", "label_ko": null, "label_vi": null, "definition_ko": "결과를 이루는 수단이나 방법을 나타낸다: 'X함으로써 Y를 이루다'. -해서보다 더 격식적이고 문어체적이다.", "definition_vi": "Diễn tả phương tiện hoặc cách thức đạt được kết quả: 'bằng cách X thì đạt được Y'. Trang trọng và mang tính văn viết hơn -해서.", "notes_ko": "완전한 형태는 -음으로써이며, -음으로만 쓰기도 하지만 수단을 강조하는 느낌은 조금 약하다.", "notes_vi": "Dạng đầy đủ là -음으로써; -음으로 một mình cũng dùng được nhưng nhấn mạnh phương tiện yếu hơn một chút."}]$$::jsonb, $$["음으로써", "ㅁ으로써"]$$::jsonb, false, now()),
('길래', '-길래', 'intermediate', 4, 2, 25, 45, $$[{"label": null, "definition": "A causal connective (spoken) introducing an observed reason that prompted the speaker's reaction: 'because I saw/noticed that X, (so) I did Y.'", "formation": "Verb/Adj stem + -길래", "examples": [["세일을 하길래 충동적으로 사 버렸어요.", "I saw there was a sale going on, so I impulsively bought it."], ["하늘이 흐리길래 우산을 챙겨서 나왔어요.", "The sky looked cloudy, so I brought an umbrella with me."]], "notes": "Unlike -니까, often carries a slightly defensive or explanatory nuance about a reaction to a directly perceived stimulus.", "label_ko": null, "label_vi": null, "definition_ko": "화자가 직접 관찰한 것을 원인으로 제시해 이어지는 반응을 설명하는 구어체 인과 연결어미다: '(직접 보니/들으니) X하길래 Y했다'.", "definition_vi": "Là liên từ nhân quả trong khẩu ngữ, nêu nguyên nhân mà người nói trực tiếp quan sát được để giải thích phản ứng tiếp theo: '(thấy) X nên (đã) Y'.", "notes_ko": "-니까와 달리 직접 지각한 자극에 대한 반응을 설명하는 다소 방어적인 뉘앙스를 띠기도 한다.", "notes_vi": "Khác với -니까, đôi khi mang sắc thái hơi biện minh khi giải thích phản ứng với một tác nhân được cảm nhận trực tiếp."}]$$::jsonb, $$["길래"]$$::jsonb, false, now()),
('는-데', '-는 데', 'advanced', 4, 4, 50, 50, $$[{"label": null, "definition": "데 is a bound noun meaning 'a place,' 'a matter,' or 'a point.' -는 데 lets a verb clause function as a noun phrase referring to a situation, task, or location.", "formation": "Verb modifier + 데 (bound noun)", "examples": [["전통 문화를 보존하는 데 많은 노력이 필요해요.", "It takes a great deal of effort when it comes to preserving traditional culture."], ["이 문제를 해결하는 데 시간이 좀 걸릴 것 같아요.", "It seems like it'll take some time to solve this problem."]], "notes": "Must be distinguished from the conjunctive -는데 (no space, meaning 'but/and') — as a bound noun, there is a space before 데.", "label_ko": null, "label_vi": null, "definition_ko": "데는 '장소', '일', '점'을 뜻하는 의존명사다. -는 데는 동사절을 '~하는 데(에)', '~하는 일에', '~하는 점에서'와 같은 명사구로 만들어 준다.", "definition_vi": "데 là danh từ phụ thuộc, nghĩa là 'nơi', 'việc', 'điểm'. -는 데 biến một mệnh đề động từ thành cụm danh từ như 'trong việc làm gì', 'ở điểm nào'.", "notes_ko": "'그런데/그러나'를 뜻하는 연결형 -는데(띄어쓰기 없음)와 구별해야 한다 — 의존명사로 쓰일 때는 데 앞에 띄어쓰기가 있다.", "notes_vi": "Cần phân biệt với liên từ -는데 (không có khoảng trắng, nghĩa 'nhưng/và') — khi là danh từ phụ thuộc thì có khoảng trắng trước 데."}]$$::jsonb, $$["는 데"]$$::jsonb, false, now()),
('기-나름이다-n-나름이다', '-기 나름이다 / N 나름이다', 'intermediate', 3, 3, 40, 50, $$[{"label": null, "definition": "Means 'it all depends on X' or 'it's entirely up to X' — the outcome varies entirely according to the factor mentioned.", "formation": "Verb stem + -기 나름이다 · Noun + 나름이다", "examples": [["취미 생활도 어떻게 하기 나름이에요.", "Hobbies, too — it all depends on how you approach them."], ["행복은 생각하기 나름이에요.", "Happiness is all about how you think about it."]], "notes": "Comes from 나름대로 ('in its own way'); often used as encouragement or to reject a fixed view.", "label_ko": null, "label_vi": null, "definition_ko": "'그것은 전적으로 X에 달려 있다'는 뜻이다. 결과나 질이 고정된 것이 아니라 언급된 요인에 따라 완전히 달라짐을 강조한다.", "definition_vi": "Nghĩa là 'điều đó hoàn toàn tùy thuộc vào X'. Nhấn mạnh rằng kết quả/chất lượng không cố định mà thay đổi hoàn toàn theo yếu tố được nêu.", "notes_ko": "나름대로('나름의 방식으로')에서 유래했으며, 격려하거나 고정관념을 반박할 때 자주 쓰인다.", "notes_vi": "Bắt nguồn từ 나름대로 ('theo cách riêng'); thường dùng để khích lệ hoặc bác bỏ một quan điểm cố định."}]$$::jsonb, $$["나름이다", "나름이에요"]$$::jsonb, true, now()),
('을-ㄹ-줄만-알았지', '-을/ㄹ 줄만 알았지', 'advanced', 2, 4, 25, 45, $$[{"label": null, "definition": "Expresses that the speaker mistakenly assumed only X would happen, but something else occurred: 'I only thought/expected X — I didn't realize Y.'", "formation": "Verb stem + -(으)ㄹ 줄만 알았지", "examples": [["쉬울 줄만 알았지, 막상 해 보니 정말 어렵네요.", "I only thought it would be easy — but now that I'm actually doing it, it's really hard."], ["그 사람이 착한 줄만 알았지, 이렇게 이기적인 줄은 몰랐어요.", "I only thought he was kind — I had no idea he could be this selfish."]], "notes": "Carries a self-reproaching or mildly regretful nuance; implies 'but in fact Y happened.'", "label_ko": null, "label_vi": null, "definition_ko": "화자가 X만 일어날 줄 알았는데 실제로는 다른 일이 일어났음을 나타낸다: '그저 X인 줄만 알았지, Y는 몰랐다'.", "definition_vi": "Diễn tả việc người nói chỉ tưởng rằng X sẽ xảy ra, nhưng thực tế lại xảy ra chuyện khác: 'cứ tưởng chỉ có X thôi, không ngờ Y'.", "notes_ko": "약간 자책하거나 아쉬워하는 뉘앙스를 담고 있으며, '그런데 실제로는 Y가 일어났다'는 암시를 포함한다.", "notes_vi": "Mang sắc thái hơi tự trách hoặc tiếc nuối; ngụ ý 'nhưng thực ra Y đã xảy ra'."}]$$::jsonb, $$["줄만 알았지"]$$::jsonb, true, now()),
('는-한', '-는 한', 'advanced', 3, 4, 60, 55, $$[{"label": null, "definition": "Means 'as long as X, Y holds' — Y is affirmed to be true for as long as X remains true. Common in promises and strong assertions.", "formation": "Verb modifier + 한 (bound noun: as long as)", "examples": [["내가 있는 한 절대로 포기하지 않을 거예요.", "As long as I am here, I will absolutely never give up."], ["네가 노력하는 한 나는 언제나 널 응원할 거야.", "As long as you keep trying, I will always support you."]], "notes": "Should not be confused with -ㄴ 한이 있더라도 ('even if it comes to that'); -는 한 expresses a sustaining condition.", "label_ko": null, "label_vi": null, "definition_ko": "'X인 한 Y가 성립한다'는 뜻이다. X가 사실인 동안에는 언제나 Y가 참임을 보장하는 조건을 나타낸다. 약속이나 강한 단언에 흔히 쓰인다.", "definition_vi": "Nghĩa là 'chừng nào X thì Y'. Diễn tả một điều kiện duy trì: Y đúng trong suốt thời gian X còn đúng. Thường dùng trong lời hứa hoặc khẳng định mạnh mẽ.", "notes_ko": "'설령 그렇게 되더라도'를 뜻하는 -ㄴ 한이 있더라도와 혼동하지 말 것 — -는 한은 지속되는 조건을 나타낸다.", "notes_vi": "Đừng nhầm với -ㄴ 한이 있더라도 (nghĩa 'dù có phải như vậy') — -는 한 diễn tả một điều kiện duy trì liên tục."}]$$::jsonb, $$["는 한"]$$::jsonb, false, now()),
('되', '-되', 'advanced', 1, 5, 90, 60, $$[{"label": null, "definition": "A formal connective meaning 'but,' 'however,' or 'while doing X, with the condition that Y.' Introduces a limiting proviso, common in legal/official Korean.", "formation": "Verb/Adj stem + -되", "examples": [["지원은 가능하되, 서류를 먼저 제출해야 합니다.", "Applications are accepted; however, documents must be submitted first."], ["물건은 반품하되, 영수증을 반드시 지참해야 합니다.", "You may return the item; however, you must bring the receipt without fail."]], "notes": "Mostly written/formal; relatively rare in everyday speech. Often seen in regulations and contracts.", "label_ko": null, "label_vi": null, "definition_ko": "'그러나', '다만', 'X하되 Y라는 조건으로'를 뜻하는 격식체 연결어미다. 첫 번째 절에 조건이나 제한을 다는 두 번째 절을 연결한다. 법률·공문서 한국어에서 흔하다.", "definition_vi": "Là liên từ trang trọng nghĩa 'nhưng', 'tuy nhiên', 'X nhưng với điều kiện là Y'. Nối hai mệnh đề trong đó mệnh đề sau thêm điều kiện/giới hạn cho mệnh đề trước. Phổ biến trong tiếng Hàn pháp lý, công văn.", "notes_ko": "주로 문어체/격식체이며 일상 대화에서는 비교적 드물다. 규정, 계약서, 공식 지침에서 자주 보인다.", "notes_vi": "Chủ yếu là văn viết/trang trọng, khá hiếm trong hội thoại hàng ngày. Thường thấy trong quy định, hợp đồng, chỉ thị chính thức."}]$$::jsonb, $$[]$$::jsonb, false, now()),
('거나', '-거나', 'intermediate', 5, 1, 50, 50, $$[{"label": null, "definition": "Connects two or more alternatives, meaning 'or': one option or the other (possibly both) applies.", "formation": "Verb/Adj stem + -거나", "examples": [["스트레스를 받으면 운동을 하거나 청소를 해요.", "When I'm stressed, I either exercise or clean."], ["주말에는 영화를 보거나 책을 읽어요.", "On weekends, I either watch a movie or read a book."]], "notes": "Can chain more than two alternatives; unlike 아니면, it attaches directly to the verb/adjective stem.", "label_ko": null, "label_vi": null, "definition_ko": "'X 아니면 Y'라는 뜻으로 두 가지 이상의 대안을 연결한다. 둘 중 하나(또는 둘 다)가 적용됨을 나타낸다.", "definition_vi": "Nối hai hoặc nhiều lựa chọn thay thế, nghĩa là 'X hoặc Y' — một trong hai (hoặc cả hai) đều đúng.", "notes_ko": "두 개 이상의 대안을 연결할 수 있으며, 아니면과 달리 동사/형용사 어간에 직접 붙는다.", "notes_vi": "Có thể nối nhiều hơn hai lựa chọn; khác với 아니면, nó gắn trực tiếp vào gốc động từ/tính từ."}]$$::jsonb, $$["거나"]$$::jsonb, false, now()),
('고-나서', '-고 나서', 'intermediate', 5, 1, 50, 50, $$[{"label": null, "definition": "Means 'after finishing X' — the second action happens only once the first is fully completed.", "formation": "Verb stem + -고 나서", "examples": [["주말에 청소를 하고 나서 요리를 했어요.", "On the weekend, after cleaning, I cooked."], ["숙제를 다 하고 나서 게임을 해도 돼요.", "You can play games after you finish all your homework."]], "notes": "Emphasizes completion of the first action before the second begins, more so than plain -고.", "label_ko": null, "label_vi": null, "definition_ko": "'X를 끝낸 후에'라는 뜻으로, 첫 번째 행동이 완전히 끝난 뒤에야 두 번째 행동이 일어난다.", "definition_vi": "Nghĩa là 'sau khi hoàn thành X' — hành động thứ hai chỉ xảy ra sau khi hành động đầu tiên đã hoàn tất.", "notes_ko": "단순 -고보다 첫 번째 행동의 완료를 더 강조한다.", "notes_vi": "Nhấn mạnh sự hoàn thành của hành động đầu tiên nhiều hơn so với -고 đơn thuần."}]$$::jsonb, $$["고 나서"]$$::jsonb, false, now()),
('는-길에', '-는 길에', 'intermediate', 3, 2, 40, 50, $$[{"label": null, "definition": "Means 'on the way while doing X' — an incidental action happens in the course of going somewhere.", "formation": "Verb (present) modifier + 길에", "examples": [["집에 돌아오는 길에 과일 좀 사 오세요.", "On your way home, please pick up some fruit."], ["회사에 가는 길에 우연히 옛 친구를 만났어요.", "On my way to work, I happened to run into an old friend."]], "notes": "Limited to motion verbs like 가다/오다/나가다 — describes something done en route.", "label_ko": null, "label_vi": null, "definition_ko": "'X하러 가는 길에'라는 뜻으로, 어딘가로 가는 도중에 부수적인 행동이 일어남을 나타낸다.", "definition_vi": "Nghĩa là 'trên đường X' — một hành động phụ xảy ra trong khi đang di chuyển đến đâu đó.", "notes_ko": "가다/오다/나가다 같은 이동 동사에 한정되며, 도중에 하는 일을 나타낸다.", "notes_vi": "Giới hạn ở các động từ chuyển động như 가다/오다/나가다 — mô tả việc làm dọc đường."}]$$::jsonb, $$["는 길에"]$$::jsonb, false, now()),
('는-데다가', '-는 데다가', 'intermediate', 4, 3, 50, 50, $$[{"label": null, "definition": "Means 'on top of X / in addition to X' — adds a second fact that compounds or intensifies the first, often making a situation more extreme.", "formation": "Verb (present) -는 데다가 · Adjective -(으)ㄴ 데다가", "examples": [["오늘은 비가 오는 데다가 바람까지 불어서 제대로 걸을 수가 없다.", "Today it's not only raining, but the wind is blowing too, so I can barely walk."], ["그 사람은 성격이 좋은 데다가 능력도 뛰어나요.", "That person not only has a good personality, but is also highly capable."]], "notes": "Both facts usually point in the same direction (both positive or both negative), intensifying the overall statement.", "label_ko": null, "label_vi": null, "definition_ko": "'X한 데다가 Y까지'라는 뜻으로, 첫 번째 사실을 더 극단적으로 만드는 두 번째 사실을 덧붙인다.", "definition_vi": "Nghĩa là 'không những X mà còn Y nữa' — thêm một sự thật thứ hai làm tình huống trở nên cực đoan hơn.", "notes_ko": "두 사실은 보통 같은 방향(둘 다 긍정적이거나 둘 다 부정적)을 가리켜 전체 진술을 강화한다.", "notes_vi": "Hai sự thật thường cùng chiều hướng (cùng tích cực hoặc cùng tiêu cực), làm tăng cường tuyên bố tổng thể."}]$$::jsonb, $$["데다가"]$$::jsonb, false, now()),
('든지', '-든지', 'intermediate', 4, 2, 45, 50, $$[{"label": null, "definition": "Means 'whether X or Y' / 'no matter which' — expresses that the choice among alternatives doesn't matter to the outcome.", "formation": "Verb/Adj stem + -든지 (often doubled: -든지 -든지)", "examples": [["우산이 비싸든지 싸든지 무조건 사 오세요.", "Whether the umbrella is expensive or cheap, just buy it no matter what."], ["먹든지 말든지 네 마음대로 해.", "Whether you eat it or not, do as you please."]], "notes": "Often doubled across two alternatives, or combined with question words (누구든지, 언제든지) to mean 'anyone/anytime at all.'", "label_ko": null, "label_vi": null, "definition_ko": "'X든 Y든'이라는 뜻으로, 대안 중 어느 것을 선택해도 결과에 영향이 없음을 나타낸다.", "definition_vi": "Nghĩa là 'dù X hay Y' — chọn phương án nào cũng không ảnh hưởng đến kết quả.", "notes_ko": "두 대안에 겹쳐서 자주 쓰이거나, 의문사와 결합해(누구든지, 언제든지) '누구든/언제든 상관없이'라는 뜻이 된다.", "notes_vi": "Thường lặp lại giữa hai lựa chọn, hoặc kết hợp với từ để hỏi (누구든지, 언제든지) để nghĩa là 'bất kỳ ai/khi nào'."}]$$::jsonb, $$["든지"]$$::jsonb, false, now()),
('아-어도', '-아/어도', 'intermediate', 5, 1, 50, 50, $$[{"label": null, "definition": "Means 'even if / even though X' — the result in the second clause holds true regardless of the first clause.", "formation": "Verb/Adj stem + -아/어도", "examples": [["무슨 일이 있어도 오늘까지는 이 일을 꼭 끝내야 해요.", "No matter what happens, I have to finish this by today."], ["아무리 바빠도 하루에 한 번은 운동을 해요.", "No matter how busy I am, I exercise at least once a day."]], "notes": "The most basic/common concessive ending; less formal than -더라도.", "label_ko": null, "label_vi": null, "definition_ko": "'설령 X이더라도'라는 뜻으로, 앞 절과 상관없이 뒤 절의 결과가 성립함을 나타낸다.", "definition_vi": "Nghĩa là 'dù có X đi nữa' — kết quả ở vế sau vẫn đúng bất kể vế trước.", "notes_ko": "가장 기본적이고 흔한 양보 어미이며, -더라도보다 덜 격식적이다.", "notes_vi": "Là vĩ tố nhượng bộ cơ bản và phổ biến nhất; ít trang trọng hơn -더라도."}]$$::jsonb, $$["아도", "어도", "여도"]$$::jsonb, false, now()),
('으-나-마나', '-(으)나 마나', 'intermediate', 3, 3, 30, 45, $$[{"label": null, "definition": "Means 'whether you do X or not, the result is the same' — implies doing X is essentially pointless because the outcome won't change.", "formation": "Verb stem + -(으)나 마나", "examples": [["선생님께 물어보나 마나 허락하지 않으실 거예요.", "Whether we ask the teacher or not, they're not going to allow it anyway."], ["그 사람 성격을 보나 마나 분명히 거절할 거예요.", "Whether we sound out his personality or not, he's clearly going to refuse."]], "notes": "Carries a resigned or slightly dismissive tone about the futility of the action.", "label_ko": null, "label_vi": null, "definition_ko": "'X를 하든 안 하든 결과는 같다'는 뜻으로, X를 하는 것이 사실상 무의미함을 암시한다.", "definition_vi": "Nghĩa là 'dù có làm X hay không thì kết quả cũng vậy' — ngụ ý làm X gần như vô ích.", "notes_ko": "행동의 무익함에 대해 다소 체념하거나 무심한 어조를 띤다.", "notes_vi": "Mang giọng điệu hơi cam chịu hoặc thờ ơ về sự vô ích của hành động."}]$$::jsonb, $$["나 마나"]$$::jsonb, false, now()),
('으-려고', '-(으)려고', 'intermediate', 5, 1, 45, 50, $$[{"label": null, "definition": "Expresses intention or purpose: 'intending to X' or 'in order to X,' setting up the reason behind the main clause's action.", "formation": "Verb stem + -(으)려고", "examples": [["친구 결혼식 때 입으려고 양복을 미리 사 두었다.", "I bought a suit in advance, intending to wear it to my friend's wedding."], ["다이어트를 하려고 저녁마다 운동을 시작했어요.", "I started exercising every evening, intending to lose weight."]], "notes": "Cannot be followed directly by a command or suggestion in the same clause; states intent behind a separate action.", "label_ko": null, "label_vi": null, "definition_ko": "의도나 목적을 나타낸다: 'X하려고(하기 위해)'로, 본절 행동의 이유가 되는 의도를 밝힌다.", "definition_vi": "Diễn tả ý định hoặc mục đích: 'định X' / 'để X' — nêu ý định làm nền tảng cho hành động ở mệnh đề chính.", "notes_ko": "같은 절 안에서 바로 명령이나 제안이 뒤따를 수 없으며, 별도의 행동 뒤에 있는 의도를 말한다.", "notes_vi": "Không thể theo sau ngay bằng mệnh lệnh/đề nghị trong cùng mệnh đề; nêu ý định đằng sau một hành động riêng biệt."}]$$::jsonb, $$["으려고", "려고"]$$::jsonb, false, now()),
('으-려다가', '-(으)려다가', 'intermediate', 3, 2, 40, 50, $$[{"label": null, "definition": "Means 'was about to/intending to do X, but then (something else happened instead).' The original intention was interrupted or changed.", "formation": "Verb stem + -(으)려다가", "examples": [["친구랑 밥을 먹으러 가려다가 그냥 도서관에 가기로 했다.", "I was going to go eat with a friend, but then decided to just go to the library instead."], ["택시를 타려다가 그냥 걸어가기로 했어요.", "I was going to take a taxi, but decided to just walk instead."]], "notes": "Always implies a change of plan — the original intention was not carried out.", "label_ko": null, "label_vi": null, "definition_ko": "'X하려고 했는데 (대신 다른 일이 일어났다)'라는 뜻으로, 원래 의도가 중간에 바뀌거나 중단되었음을 나타낸다.", "definition_vi": "Nghĩa là 'định X nhưng rồi (lại xảy ra chuyện khác)' — ý định ban đầu bị gián đoạn hoặc thay đổi.", "notes_ko": "항상 계획의 변경을 암시한다 — 원래 의도는 실행되지 않았다.", "notes_vi": "Luôn ngụ ý một sự thay đổi kế hoạch — ý định ban đầu đã không được thực hiện."}]$$::jsonb, $$["으려다가", "려다가"]$$::jsonb, false, now()),
('으-려면', '-(으)려면', 'intermediate', 5, 2, 45, 50, $$[{"label": null, "definition": "Means 'if you intend to / want to do X, (then you need to do Y)' — sets up a condition tied to a goal or intention.", "formation": "Verb stem + -(으)려면", "examples": [["한국어를 잘하려면 열심히 공부해야 돼요.", "If you want to become good at Korean, you have to study hard."], ["건강해지려면 규칙적으로 운동해야 돼요.", "If you want to become healthy, you need to exercise regularly."]], "notes": "Almost always paired with a following clause stating what's required to achieve the stated intention.", "label_ko": null, "label_vi": null, "definition_ko": "'X하려면 (Y를 해야 한다)'라는 뜻으로, 목표나 의도에 관련된 조건을 제시한다.", "definition_vi": "Nghĩa là 'nếu muốn X thì (cần phải Y)' — đặt ra một điều kiện gắn với mục tiêu hoặc ý định.", "notes_ko": "거의 항상 그 의도를 이루기 위해 필요한 것을 말하는 절이 뒤따른다.", "notes_vi": "Hầu như luôn theo sau bởi mệnh đề nêu điều cần thiết để đạt được ý định đó."}]$$::jsonb, $$["으려면", "려면"]$$::jsonb, false, now()),
('으-ㄹ수록', '-(으)ㄹ수록', 'intermediate', 5, 2, 50, 50, $$[{"label": null, "definition": "Means 'the more X, the more Y' — expresses a proportional relationship where increasing one thing increases another.", "formation": "Verb/Adj stem + -(으)ㄹ수록 (often doubled: -(으)면 -(으)ㄹ수록)", "examples": [["한국어는 배우면 배울수록 재미있어요.", "The more you learn Korean, the more interesting it gets."], ["나이가 들수록 시간이 빨리 가는 것 같아요.", "The older I get, the faster time seems to pass."]], "notes": "Frequently appears in the doubled pattern -(으)면 -(으)ㄹ수록 for extra emphasis on the proportional relationship.", "label_ko": null, "label_vi": null, "definition_ko": "'X할수록 Y하다'는 뜻으로, 한쪽이 늘어남에 따라 다른 쪽도 늘어나는 비례 관계를 나타낸다.", "definition_vi": "Nghĩa là 'càng X thì càng Y' — diễn tả mối quan hệ tỉ lệ thuận, cái này tăng thì cái kia cũng tăng.", "notes_ko": "이 비례 관계를 더 강조하기 위해 -(으)면 -(으)ㄹ수록의 겹친 형태로 자주 쓰인다.", "notes_vi": "Thường xuất hiện ở dạng lặp -(으)면 -(으)ㄹ수록 để nhấn mạnh thêm mối quan hệ tỉ lệ này."}]$$::jsonb, $$["을수록", "ㄹ수록"]$$::jsonb, false, now()),
('으-면서', '-(으)면서', 'intermediate', 5, 1, 50, 50, $$[{"label": null, "definition": "Means 'while X-ing' — two actions happen at the same time, performed by the same subject.", "formation": "Verb stem + -(으)면서", "examples": [["저는 음악을 들으면서 공부를 해요.", "I study while listening to music."], ["저는 텔레비전을 보면서 밥을 먹어요.", "I eat while watching TV."]], "notes": "Both actions must share the same subject and happen simultaneously; can also imply mild contrast in some contexts ('while X, also Y').", "label_ko": null, "label_vi": null, "definition_ko": "'X하면서 (동시에) Y하다'라는 뜻으로, 같은 주어가 두 가지 행동을 동시에 함을 나타낸다.", "definition_vi": "Nghĩa là 'vừa X vừa Y' — cùng một chủ ngữ thực hiện hai hành động đồng thời.", "notes_ko": "두 행동은 반드시 같은 주어를 공유하고 동시에 일어나야 한다. 문맥에 따라 가벼운 대조('X이면서도 Y')를 나타낼 수도 있다.", "notes_vi": "Hai hành động phải cùng chủ ngữ và diễn ra đồng thời; tùy ngữ cảnh cũng có thể diễn tả sự đối lập nhẹ ('vừa X vừa Y' theo nghĩa tương phản)."}]$$::jsonb, $$["으면서", "면서"]$$::jsonb, false, now()),
('으-ㄹ-정도로', '-(으)ㄹ 정도로', 'intermediate', 4, 3, 50, 50, $$[{"label": null, "definition": "Means 'to the extent/degree that X' — describes how intense or extreme something is by comparing it to a resulting degree.", "formation": "Verb/Adj stem + -(으)ㄹ 정도로", "examples": [["그 영화는 눈물이 날 정도로 슬펐지만 울지 않고 참았다.", "The movie was sad enough to bring tears, but I held back and didn't cry."], ["손이 떨릴 정도로 긴장이 됐어요.", "I was so nervous that my hands were trembling."]], "notes": "Similar in spirit to -을/ㄹ 만큼; both describe degree via a comparison point.", "label_ko": null, "label_vi": null, "definition_ko": "'X할 정도로'라는 뜻으로, 결과로 나타나는 정도에 비추어 무언가가 얼마나 강렬하거나 극단적인지를 묘사한다.", "definition_vi": "Nghĩa là 'đến mức X' — mô tả mức độ mãnh liệt hoặc cực đoan của điều gì đó qua một kết quả tương ứng.", "notes_ko": "-을/ㄹ 만큼과 취지가 비슷하며, 둘 다 비교 기준을 통해 정도를 나타낸다.", "notes_vi": "Có tinh thần giống -을/ㄹ 만큼; cả hai đều diễn tả mức độ qua một điểm so sánh."}]$$::jsonb, $$["정도로"]$$::jsonb, false, now()),
('곤-하다', '-곤 하다', 'intermediate', 4, 2, 45, 50, $$[{"label": null, "definition": "Describes a habitual or repeated action in the past or as a general tendency: 'used to do X (regularly)' or 'X happens from time to time.'", "formation": "Verb stem + -곤 하다", "examples": [["나는 시간이 나면 공원을 산책하곤 해요.", "When I have free time, I often take a walk in the park."], ["어렸을 때는 할머니 댁에 자주 놀러 가곤 했어요.", "When I was little, I used to often go visit my grandmother's house."]], "notes": "Implies repetition over time, not a one-off occurrence.", "label_ko": null, "label_vi": null, "definition_ko": "과거의 습관적이거나 반복적인 행동, 또는 일반적인 경향을 나타낸다: '(예전에) 자주/가끔 X하곤 했다'.", "definition_vi": "Diễn tả một hành động lặp đi lặp lại trong quá khứ hoặc một xu hướng chung: '(trước đây) thường/hay X'.", "notes_ko": "일회성이 아니라 시간에 걸친 반복을 암시한다.", "notes_vi": "Ngụ ý sự lặp lại theo thời gian, không phải một lần duy nhất."}]$$::jsonb, $$["곤 하"]$$::jsonb, true, now()),
('기-마련이다', '-기 마련이다', 'intermediate', 4, 3, 55, 55, $$[{"label": null, "definition": "Means 'it's bound to be the case that X' or 'naturally X' — expresses a general truth or inevitable tendency.", "formation": "Verb/Adj stem + -기 마련이다", "examples": [["사람은 나이가 들면 누구나 늙기 마련이에요.", "Everyone is bound to grow old as they age — that's just natural."], ["열심히 노력하면 언젠가는 성공하기 마련이에요.", "If you work hard, you're bound to succeed eventually."]], "notes": "States a universal or near-universal truth, often used to reassure or normalize a situation.", "label_ko": null, "label_vi": null, "definition_ko": "'X하기 마련이다'는 뜻으로, 일반적인 진리나 피할 수 없는 경향을 나타낸다: '당연히/자연히 X하게 된다'.", "definition_vi": "Nghĩa là 'tất nhiên/đương nhiên X' — diễn tả một chân lý chung hoặc xu hướng không thể tránh khỏi.", "notes_ko": "보편적이거나 거의 보편적인 진리를 말하며, 상황을 안심시키거나 정상화할 때 자주 쓰인다.", "notes_vi": "Nêu một chân lý phổ quát hoặc gần như phổ quát; thường dùng để trấn an hoặc bình thường hóa một tình huống."}]$$::jsonb, $$["마련이다", "마련이에요", "마련이야"]$$::jsonb, true, now()),
('기로-하다', '-기로 하다', 'intermediate', 5, 2, 45, 50, $$[{"label": null, "definition": "Means 'to decide to do X' — the subject makes a decision or plan to carry out an action.", "formation": "Verb stem + -기로 하다", "examples": [["이번 방학에는 친구와 함께 여행을 가기로 했어요.", "This vacation, I've decided to go traveling with a friend."], ["이번 주말부터 다이어트를 시작하기로 했어요.", "I've decided to start dieting starting this weekend."]], "notes": "Marks a firm decision, often about future plans, and is very commonly used in everyday conversation.", "label_ko": null, "label_vi": null, "definition_ko": "'X하기로 하다'는 뜻으로, 주어가 어떤 행동을 하기로 결정하거나 계획함을 나타낸다.", "definition_vi": "Nghĩa là 'quyết định X' — chủ ngữ quyết định hoặc lên kế hoạch thực hiện một hành động.", "notes_ko": "확고한 결정을 나타내며, 주로 미래 계획에 대해 쓰이고 일상 대화에서 매우 흔하다.", "notes_vi": "Đánh dấu một quyết định chắc chắn, thường về kế hoạch tương lai, rất phổ biến trong hội thoại hàng ngày."}]$$::jsonb, $$["기로 했", "기로 하"]$$::jsonb, true, now()),
('게-되다', '-게 되다', 'intermediate', 5, 2, 45, 50, $$[{"label": null, "definition": "Means 'to come to be / end up X-ing' — describes a change of state that happens due to circumstances, often not by the subject's own direct choice.", "formation": "Verb/Adj stem + -게 되다", "examples": [["다음 달에 미국으로 유학을 가게 되었어요.", "It's been arranged that I'll go study abroad in the US next month."], ["우연히 그 사람과 다시 만나게 되었어요.", "I ended up running into that person again by chance."]], "notes": "Often implies the change came about through circumstance rather than deliberate personal decision — contrast with -기로 하다, which implies a direct decision.", "label_ko": null, "label_vi": null, "definition_ko": "'X하게 되다'는 뜻으로, 주로 주어의 직접적인 선택이 아니라 상황에 의해 일어나는 상태 변화를 나타낸다.", "definition_vi": "Nghĩa là 'trở nên/hóa ra X' — diễn tả sự thay đổi trạng thái xảy ra do hoàn cảnh, thường không phải do chủ ngữ trực tiếp lựa chọn.", "notes_ko": "그 변화가 개인의 결정이 아니라 상황에 의해 이루어졌음을 암시하는 경우가 많다 — 직접적 결정을 나타내는 -기로 하다와 대조된다.", "notes_vi": "Thường ngụ ý sự thay đổi đến từ hoàn cảnh chứ không phải quyết định cá nhân — khác với -기로 하다 vốn diễn tả quyết định trực tiếp."}]$$::jsonb, $$["게 되었", "게 됐", "게 되"]$$::jsonb, true, now()),
('는-수가-있다', '-는 수가 있다', 'intermediate', 3, 3, 40, 50, $$[{"label": null, "definition": "Warns that there are cases/situations where a particular (usually undesirable) outcome can occur: 'there are times when X can happen.'", "formation": "Verb (present) modifier + 수가 있다", "examples": [["그렇게 공부를 안 하다가는 후회하는 수가 있어요.", "If you keep not studying like that, there may come a time you regret it."], ["밤에 커피를 마시면 잠을 못 자는 수가 있어요.", "If you drink coffee at night, there can be times you're unable to sleep."]], "notes": "Used more as a cautionary warning than plain -을 수 있다, which is neutral possibility.", "label_ko": null, "label_vi": null, "definition_ko": "특정한(보통 바람직하지 않은) 결과가 일어날 수 있는 경우나 상황이 있음을 경고한다: '~하는 수가 있다'.", "definition_vi": "Cảnh báo rằng có những trường hợp/tình huống mà một kết quả nhất định (thường không mong muốn) có thể xảy ra: 'có thể sẽ X đấy'.", "notes_ko": "중립적 가능성을 나타내는 일반 -을 수 있다보다 경고성 어조로 더 많이 쓰인다.", "notes_vi": "Được dùng nhiều hơn với sắc thái cảnh báo, khác với -을 수 있다 thông thường vốn trung tính về khả năng."}]$$::jsonb, $$["는 수가 있"]$$::jsonb, true, now()),
('던데요', '-던데요', 'intermediate', 4, 3, 30, 50, $$[{"label": null, "definition": "Shares a past observation with a tone that invites reaction or sets up context, often with mild surprise: 'it was X, you know' or 'X, as I recall.'", "formation": "Verb/Adj stem + -던데요", "examples": [["어제 그 영화를 봤는데 엄청 재미있던데요.", "I watched that movie yesterday, and it was really fun, you know."], ["그 카페에 가 봤는데 분위기가 정말 좋던데요.", "I went to that cafe, and the atmosphere was really nice, I have to say."]], "notes": "Reports a direct past observation, similar to -더라고요, but with a more conversational, reaction-inviting tone.", "label_ko": null, "label_vi": null, "definition_ko": "과거의 관찰을 공유하며 반응을 유도하거나 맥락을 제시하는 어조를 띤다. 종종 약간의 놀람을 담는다: '~하던데요'.", "definition_vi": "Chia sẻ một quan sát trong quá khứ với giọng điệu mời gọi phản ứng hoặc thiết lập bối cảnh, thường mang chút ngạc nhiên: 'X đấy, biết không'.", "notes_ko": "-더라고요와 비슷하게 직접적인 과거 관찰을 전달하지만, 좀 더 대화체적이고 반응을 유도하는 어조를 띤다.", "notes_vi": "Tương tự -더라고요 ở việc truyền đạt quan sát trực tiếp trong quá khứ, nhưng giọng điệu thân mật và mời gọi phản ứng hơn."}]$$::jsonb, $$["던데요"]$$::jsonb, true, now()),
('아-어-있다', '-아/어 있다', 'intermediate', 5, 1, 50, 50, $$[{"label": null, "definition": "Describes a resultant state: the subject is currently in the state that resulted from a completed action, e.g., 'is (sitting/standing/hung, etc.).'", "formation": "Verb stem + -아/어 있다", "examples": [["우리 교실 벽에는 세계지도와 시계가 걸려 있다.", "On our classroom wall, there's a world map and a clock hanging."], ["문이 열려 있어서 그냥 들어갔어요.", "The door was open, so I just went in."]], "notes": "Only used with a limited set of verbs describing position/state changes (앉다, 서다, 걸리다, 열리다, etc.) — contrast with -고 있다, which describes an ongoing action.", "label_ko": null, "label_vi": null, "definition_ko": "완료된 행동으로 인해 생긴 결과 상태를 나타낸다. 예: '(앉아/서/걸려) 있다'처럼 현재 그 상태에 있음을 나타낸다.", "definition_vi": "Diễn tả trạng thái kết quả từ một hành động đã hoàn thành, ví dụ: 'đang (ngồi/đứng/treo)' — hiện đang ở trạng thái đó.", "notes_ko": "앉다, 서다, 걸리다, 열리다처럼 위치·상태 변화를 나타내는 한정된 동사에만 쓰인다 — 진행 중인 동작을 나타내는 -고 있다와 대조된다.", "notes_vi": "Chỉ dùng với một nhóm động từ giới hạn diễn tả vị trí/thay đổi trạng thái như 앉다, 서다, 걸리다, 열리다 — khác với -고 있다 diễn tả hành động đang diễn ra."}]$$::jsonb, $$["아 있", "어 있"]$$::jsonb, true, now()),
('았-었으면-하다', '-았/었으면 하다', 'intermediate', 4, 2, 60, 65, $$[{"label": null, "definition": "Expresses a wish or hope, often gentler and more indirect than -고 싶다: 'I hope that X (would happen).'", "formation": "Verb/Adj stem + -았/었으면 하다", "examples": [["대학교를 졸업하고 한국에서 직장을 구했으면 합니다.", "I hope that after graduating from university, I can find a job in Korea."], ["이번 방학에는 가족과 함께 여행을 갔으면 해요.", "I hope that this vacation, I can go traveling together with my family."]], "notes": "Softer and more polite than stating a direct wish; commonly used in formal or written requests.", "label_ko": null, "label_vi": null, "definition_ko": "-고 싶다보다 더 부드럽고 간접적인 소망이나 바람을 나타낸다: '~했으면 한다'.", "definition_vi": "Diễn tả một điều ước hoặc hy vọng nhẹ nhàng, gián tiếp hơn -고 싶다: 'mong rằng...'.", "notes_ko": "직접적인 소망을 말하는 것보다 더 부드럽고 공손하며, 격식적이거나 문어체적인 요청에서 흔히 쓰인다.", "notes_vi": "Mềm mại và lịch sự hơn việc nói thẳng điều ước; thường dùng trong yêu cầu trang trọng hoặc văn viết."}]$$::jsonb, $$["았으면 하", "었으면 하"]$$::jsonb, true, now()),
('으-려나-보다', '-(으)려나 보다', 'advanced', 3, 4, 35, 50, $$[{"label": null, "definition": "Expresses a tentative guess that something is about to happen, based on indirect evidence: 'it seems like X is about to happen / I guess X.'", "formation": "Verb stem + -(으)려나 보다", "examples": [["하늘이 어두워지는 걸 보니 비가 오려나 봐요.", "Seeing the sky get dark, I guess it's about to rain."], ["전화를 안 받는 걸 보니 바쁘려나 봐요.", "Since they're not answering the phone, I guess they must be busy."]], "notes": "A softer, more tentative inference than -는 모양이다; often based on a small observed cue.", "label_ko": null, "label_vi": null, "definition_ko": "간접적인 증거를 바탕으로 무언가가 곧 일어날 것 같다는 잠정적인 추측을 나타낸다: '~하려나 봐요'.", "definition_vi": "Diễn tả một suy đoán dè dặt rằng điều gì đó sắp xảy ra, dựa trên bằng chứng gián tiếp: 'chắc là sắp X'.", "notes_ko": "-는 모양이다보다 더 조심스럽고 잠정적인 추측이며, 작은 단서에 근거하는 경우가 많다.", "notes_vi": "Là suy đoán dè dặt, tạm thời hơn -는 모양이다, thường dựa trên một manh mối nhỏ."}]$$::jsonb, $$["려나 봐", "려나 보"]$$::jsonb, true, now()),
('으-려던-참이다', '-(으)려던 참이다', 'advanced', 3, 3, 35, 50, $$[{"label": null, "definition": "Means 'was just about to do X' — describes an action the speaker was on the verge of starting when something else happened (often being asked to do it).", "formation": "Verb stem + -(으)려던 참이다", "examples": [["저도 지금 막 가려던 참이었어요.", "I was just about to leave right now, actually."], ["마침 너한테 연락하려던 참이었는데 잘 됐다.", "I was just about to contact you, so this works out well."]], "notes": "Frequently used to agree with or confirm a suggestion that matches what the speaker was already about to do.", "label_ko": null, "label_vi": null, "definition_ko": "'막 X하려던 참이었다'는 뜻으로, 화자가 다른 일이 일어났을 때(주로 그 일을 하라는 요청을 받았을 때) 막 시작하려던 행동을 나타낸다.", "definition_vi": "Nghĩa là 'vừa định X' — mô tả một hành động mà người nói sắp bắt đầu thì có chuyện khác xảy ra (thường là được yêu cầu làm chính việc đó).", "notes_ko": "화자가 이미 하려던 것과 일치하는 제안에 동의하거나 확인할 때 자주 쓰인다.", "notes_vi": "Thường dùng để đồng ý hoặc xác nhận một đề nghị trùng với điều người nói đã định làm."}]$$::jsonb, $$["려던 참"]$$::jsonb, true, now()),
('는-은-줄-모르다-알다', '-는/은 줄 모르다(알다)', 'advanced', 4, 3, 40, 50, $$[{"label": null, "definition": "Means 'didn't know/realize that X was the case' (or, with 알다, 'thought/knew that X was the case') — describes a (often mistaken) assumption about a fact.", "formation": "Verb/Adj modifier + 줄 모르다/알다", "examples": [["영미 씨가 한국어를 이렇게 잘하는 줄 몰랐어요.", "I didn't realize Yeong-mi was this good at Korean."], ["저는 오늘이 휴일인 줄 알았는데 아니었어요.", "I thought today was a holiday, but it wasn't."]], "notes": "Frequently used to express surprise at discovering the assumption was wrong.", "label_ko": null, "label_vi": null, "definition_ko": "'X인 줄 몰랐다'(또는 알다와 함께 'X인 줄 알았다')는 뜻으로, 어떤 사실에 대한 (흔히 잘못된) 가정을 나타낸다.", "definition_vi": "Nghĩa là 'không biết là X' (hoặc với 알다, 'tưởng là X') — diễn tả một giả định (thường sai) về một sự thật.", "notes_ko": "그 가정이 틀렸음을 알게 된 놀라움을 표현할 때 자주 쓰인다.", "notes_vi": "Thường dùng để bày tỏ sự ngạc nhiên khi phát hiện giả định đó sai."}]$$::jsonb, $$["줄 몰랐", "줄 알았"]$$::jsonb, false, now()),
('는걸요-으-ㄴ걸요', '-는걸요, -(으)ㄴ걸요', 'advanced', 3, 3, 25, 45, $$[{"label": null, "definition": "A sentence-final ending expressing mild surprise, gentle assertion, or a soft counter to what was just said: 'well, actually X, you know.'", "formation": "Verb (present) -는걸요 · Adjective -(으)ㄴ걸요", "examples": [["평소에는 몰랐는데 치마를 입으니 여성스러운걸요.", "I didn't notice before, but now that she's wearing a skirt, she looks quite feminine, doesn't she."], ["생각보다 어렵지 않은걸요. 한번 해 보세요.", "It's not as hard as you'd think, you know — give it a try."]], "notes": "Softer and more casual than a flat statement; often carries a note of newly-realized appreciation or mild pushback.", "label_ko": null, "label_vi": null, "definition_ko": "가벼운 놀람, 부드러운 주장, 또는 방금 들은 말에 대한 온화한 반박을 나타내는 문장 종결형이다: '~인걸요'.", "definition_vi": "Là đuôi kết thúc câu diễn tả sự ngạc nhiên nhẹ, khẳng định nhẹ nhàng, hoặc phản bác dịu dàng với điều vừa nghe: 'thì đúng là X mà'.", "notes_ko": "단정적인 진술보다 부드럽고 캐주얼하며, 새롭게 깨달은 감탄이나 가벼운 반박의 느낌을 담는 경우가 많다.", "notes_vi": "Mềm mại, thân mật hơn một câu khẳng định trực tiếp; thường mang cảm giác vừa nhận ra điều gì đó hoặc phản bác nhẹ."}]$$::jsonb, $$["는걸요", "ㄴ걸요", "은걸요"]$$::jsonb, true, now()),
('으-ㄹ-듯하다', '-(으)ㄹ 듯하다', 'advanced', 4, 3, 60, 55, $$[{"label": null, "definition": "Means 'it seems like X / it looks like X will happen' — a guess based on the speaker's impression, similar to -는 것 같다 but more formal.", "formation": "Verb/Adj stem + -(으)ㄹ 듯하다", "examples": [["오늘 일이 많아서 회식에 참석하지 못할 듯합니다.", "Since I have a lot of work today, it seems I won't be able to attend the dinner."], ["구름을 보니 곧 비가 올 듯해요.", "Looking at the clouds, it seems like it's about to rain."]], "notes": "More formal/written in register than -는 것 같다; common in polite or business contexts.", "label_ko": null, "label_vi": null, "definition_ko": "'X일 듯하다'는 뜻으로, 화자의 인상에 근거한 추측을 나타낸다. -는 것 같다와 비슷하지만 더 격식적이다.", "definition_vi": "Nghĩa là 'có vẻ như X' — một suy đoán dựa trên ấn tượng của người nói. Giống -는 것 같다 nhưng trang trọng hơn.", "notes_ko": "-는 것 같다보다 더 격식적이고 문어체적이며, 정중하거나 비즈니스 상황에서 흔히 쓰인다.", "notes_vi": "Trang trọng và mang tính văn viết hơn -는 것 같다; thường dùng trong bối cảnh lịch sự hoặc công việc."}]$$::jsonb, $$["듯합니다", "듯해요", "듯하다"]$$::jsonb, true, now()),
('으-ㄹ-리가-없다', '-(으)ㄹ 리가 없다', 'advanced', 4, 3, 45, 50, $$[{"label": null, "definition": "Means 'there's no way X could be true' — expresses strong disbelief or certainty that something is impossible given what the speaker knows.", "formation": "Verb/Adj stem + -(으)ㄹ 리가 없다", "examples": [["등산을 싫어하는 다나카 씨가 산에 갈 리가 없다.", "There's no way Tanaka, who hates hiking, would go to the mountains."], ["그렇게 성실한 사람이 거짓말을 할 리가 없어요.", "There's no way someone that diligent would tell a lie."]], "notes": "Expresses the speaker's confident logical conclusion, not a simple guess — stronger than -지 않을 것 같다.", "label_ko": null, "label_vi": null, "definition_ko": "'X일 리가 없다'는 뜻으로, 화자가 아는 바에 비추어 무언가가 불가능하다는 강한 불신이나 확신을 나타낸다.", "definition_vi": "Nghĩa là 'không thể nào X được' — diễn tả sự không tin hoặc chắc chắn mạnh mẽ rằng điều gì đó là không thể, dựa trên những gì người nói biết.", "notes_ko": "단순한 추측이 아니라 화자의 자신 있는 논리적 결론을 나타내며, -지 않을 것 같다보다 강하다.", "notes_vi": "Diễn tả kết luận logic tự tin của người nói, không phải một dự đoán đơn thuần — mạnh hơn -지 않을 것 같다."}]$$::jsonb, $$["리가 없"]$$::jsonb, true, now()),
('으-ㄹ-수밖에-없다', '-(으)ㄹ 수밖에 없다', 'intermediate', 5, 2, 45, 50, $$[{"label": null, "definition": "Means 'there's no choice but to X / can't help but X' — the outcome is unavoidable given the circumstances.", "formation": "Verb/Adj stem + -(으)ㄹ 수밖에 없다", "examples": [["그렇게 열심히 하는데 성공할 수밖에 없지요.", "Working that hard, of course they can't help but succeed."], ["표가 다 팔려서 다음 공연을 예매할 수밖에 없었어요.", "Since the tickets were all sold out, I had no choice but to book the next show."]], "notes": "Frames the situation as leaving no real alternative, whether that outcome is positive or negative.", "label_ko": null, "label_vi": null, "definition_ko": "'X할 수밖에 없다'는 뜻으로, 상황상 그 결과를 피할 수 없음을 나타낸다.", "definition_vi": "Nghĩa là 'không còn cách nào khác ngoài X' — kết quả là không thể tránh khỏi trong hoàn cảnh đó.", "notes_ko": "그 상황이 실제로 대안이 없음을, 결과가 긍정적이든 부정적이든 상관없이 나타낸다.", "notes_vi": "Mô tả tình huống không có lựa chọn thay thế thực sự, dù kết quả tích cực hay tiêu cực."}]$$::jsonb, $$["수밖에 없"]$$::jsonb, true, now()),
('으-ㄹ까-하다', '-(으)ㄹ까 하다', 'intermediate', 4, 2, 35, 50, $$[{"label": null, "definition": "Means 'I'm thinking of maybe doing X' — expresses a tentative, not-yet-finalized intention.", "formation": "Verb stem + -(으)ㄹ까 하다", "examples": [["내일 친구랑 영화나 볼까 해요.", "I'm thinking I might watch a movie with a friend tomorrow."], ["이번 주말에는 집에서 좀 쉴까 해요.", "I'm thinking I might just rest at home this weekend."]], "notes": "Softer and less committed than -기로 하다 (a firm decision); leaves room for the plan to change.", "label_ko": null, "label_vi": null, "definition_ko": "'X할까 한다'는 뜻으로, 아직 확정되지 않은 잠정적인 의도를 나타낸다.", "definition_vi": "Nghĩa là 'đang nghĩ là có lẽ sẽ X' — diễn tả một ý định chưa chắc chắn, chưa hoàn tất.", "notes_ko": "확고한 결정을 나타내는 -기로 하다보다 부드럽고 덜 확실하며, 계획이 바뀔 여지를 남긴다.", "notes_vi": "Nhẹ nhàng và ít chắc chắn hơn -기로 하다 (một quyết định chắc chắn); để ngỏ khả năng thay đổi kế hoạch."}]$$::jsonb, $$["까 하"]$$::jsonb, true, now()),
('으-ㄹ지도-모르다', '-(으)ㄹ지도 모르다', 'intermediate', 4, 2, 45, 50, $$[{"label": null, "definition": "Means 'might/may be that X' — expresses uncertainty about a possibility, without strong commitment either way.", "formation": "Verb/Adj stem + -(으)ㄹ지도 모르다", "examples": [["나도 모임에 가고 싶지만 일이 있어서 못 갈지도 몰라요.", "I want to go to the gathering too, but I might not be able to because I have work."], ["내일은 눈이 올지도 몰라요.", "It might snow tomorrow."]], "notes": "A fairly neutral hedge — less certain than -(으)ㄹ 것 같다 in many contexts, simply flags a real possibility.", "label_ko": null, "label_vi": null, "definition_ko": "'X일지도 모른다'는 뜻으로, 어느 쪽으로도 강하게 확신하지 않은 채 가능성에 대한 불확실함을 나타낸다.", "definition_vi": "Nghĩa là 'có thể là X' — diễn tả sự không chắc chắn về một khả năng, không nghiêng hẳn về bên nào.", "notes_ko": "비교적 중립적인 완곡 표현이다 — 많은 맥락에서 -을/ㄹ 것 같다보다 확신이 약하며, 단순히 실제 가능성이 있음을 나타낸다.", "notes_vi": "Là cách nói giảm nhẹ khá trung tính — trong nhiều ngữ cảnh, kém chắc chắn hơn -을/ㄹ 것 같다, chỉ đơn thuần đánh dấu một khả năng có thật."}]$$::jsonb, $$["지도 몰라", "지도 모르"]$$::jsonb, true, now()),
('ㄴ-는다기보다-는', '-ㄴ/는다기보다(는)', 'intermediate', 3, 3, 40, 50, $$[{"label": "Rather than A, more like B", "definition": "Rejects a description of a situation (A) as not quite right, and offers a more accurate one (B): 'I wouldn't say A, it's more that B.'", "formation": "Verb/Adj stem + -ㄴ/는다기보다(는) + B", "examples": [["다이어트를 위해 먹는다기보다는 건강을 위해 아침을 먹어요.", "I wouldn't say I eat breakfast for the diet — it's more that I eat it for my health."], ["그 여자는 여자친구였다기보다는 그냥 친구였어요.", "I wouldn't say she was my girlfriend — she was just a friend."]], "notes": "Very close to '-다고 하기보다는'; the speaker is correcting an assumed or stated description of P1 with a better one, P2.", "label_ko": null, "label_vi": null, "definition_ko": "어떤 상황에 대한 설명(A)이 정확하지 않다고 여기고 더 알맞은 설명(B)을 제시할 때 쓴다: 'A라기보다는 B이다'.", "definition_vi": "Dùng khi người nói cho rằng cách mô tả A chưa chính xác và đưa ra cách nói đúng hơn là B: 'Không hẳn là A, mà đúng hơn là B'.", "notes_ko": "'-다고 하기보다는'과 거의 같은 뜻이며, 상대가 짐작하거나 말한 내용을 더 정확한 표현으로 고쳐 말할 때 쓴다.", "notes_vi": "Gần giống '-다고 하기보다는'; dùng khi người nói sửa lại một giả định hoặc phát biểu trước đó bằng cách diễn đạt chính xác hơn."}]$$::jsonb, $$["다기보다는", "라기보다는", "다기보다"]$$::jsonb, false, now()),
('던', '-던', 'intermediate', 4, 3, 45, 50, $$[{"label": "Retrospective modifier (used to / was -ing)", "definition": "An adnominal ending that marks a noun as recalled from a past, often incomplete or repeated, personal experience: 'the N that was/used to be...'", "formation": "Verb/Adj stem + -던 + Noun", "examples": [["어렸을 때 자주 가던 식당이 문을 닫았어요.", "The restaurant I used to go to often as a kid closed down."], ["제가 입던 바지가 어디 갔지?", "Where did the pants I was wearing go?"]], "notes": "Different from -(으)ㄴ: -던 recalls an unfinished, repeated, or ongoing past state, while V-았/었던 marks a completed past action recalled from memory.", "label_ko": null, "label_vi": null, "definition_ko": "화자가 과거에 직접 경험했던, 흔히 끝나지 않았거나 반복되었던 상황을 회상하며 명사를 꾸밀 때 쓰는 관형사형 어미이다.", "definition_vi": "Đuôi định ngữ dùng khi người nói hồi tưởng một trạng thái trong quá khứ mà bản thân đã trải qua, thường là chưa hoàn thành hoặc lặp đi lặp lại.", "notes_ko": "-(으)ㄴ과 다르게 -던은 끝나지 않았거나 반복된 과거를, -았/었던은 완료된 과거를 회상할 때 쓴다.", "notes_vi": "Khác với -(으)ㄴ, -던 dùng cho trạng thái quá khứ chưa hoàn thành hoặc lặp lại, còn -았/었던 dùng cho hành động quá khứ đã hoàn thành được nhớ lại."}, {"label": "-던가(요)? (self/casual question)", "definition": "Asks a question about a recalled past fact, often to oneself or very casually to someone else, showing the speaker isn't fully sure: 'did it... again?'", "formation": "Verb/Adj stem + -던가(요)?", "examples": [["우리가 어디서 승차했던가?", "Where was it we got on again? (trying to recall)"], ["그 사람이 어디 사람이던가?", "Where was that person from again?"]], "notes": "Very informal; used when trying to recall something the speaker once knew but has forgotten, not as a real question to another person.", "label_ko": null, "label_vi": null, "definition_ko": "화자가 예전에 알았지만 잊어버린 사실을 스스로에게 묻듯이 캐물을 때 쓰는 매우 비격식적인 의문형이다.", "definition_vi": "Dùng khi người nói tự hỏi lại một điều mình từng biết nhưng đã quên; rất thân mật, không phải câu hỏi thật sự dành cho người khác.", "notes_ko": "다른 사람에게 진짜로 묻는 질문이라기보다 혼잣말처럼 기억을 더듬을 때 쓰는 표현이다.", "notes_vi": "Không phải câu hỏi thật sự hướng đến người nghe, mà giống như người nói đang lẩm bẩm cố nhớ lại điều gì đó."}]$$::jsonb, $$["던가요", "던가", "던"]$$::jsonb, false, now()),
('는-반면-에', '-는 반면(에)', 'intermediate', 4, 2, 55, 50, $$[{"label": "On the other hand / while", "definition": "Contrasts two sides of the same subject or two related situations: 'While A is true, B (the opposite/different side) is also true.'", "formation": "Verb/Adj stem + -는/(으)ㄴ 반면(에)", "examples": [["우리나라는 천연자원이 적은 반면에 인적 자원이 우수해요.", "While Korea has few natural resources, it has excellent human resources."], ["몇몇은 태닝을 하기 위해 가는 반면, 다른 몇몇은 단순히 경치를 보러 가요.", "While some go to tan, others simply go to see the scenery."]], "notes": "Roughly '~지만, however'; typically used to weigh a good point against a bad one, or vice versa.", "label_ko": null, "label_vi": null, "definition_ko": "한 대상의 두 가지 측면이나 서로 관련된 두 상황을 대조할 때 쓴다: 'A인 반면에 B이다'.", "definition_vi": "Dùng để đối chiếu hai mặt của cùng một đối tượng hoặc hai tình huống liên quan: 'Trong khi A thì B'.", "notes_ko": "'~지만, 그러나'와 비슷하며 보통 좋은 점과 나쁜 점을 대비시킬 때 자주 쓴다.", "notes_vi": "Gần giống '~지만, tuy nhiên'; thường dùng để cân nhắc một điểm tốt và một điểm xấu."}, {"label": "-는 데 비해(서)/반해(서) (compared to)", "definition": "A near-synonym of -는 반면에 that frames the contrast as a direct comparison of levels: 'Compared to how A is, B is...'", "formation": "Verb/Adj stem + -는 데 비해(서)/반해(서)", "examples": [["그 나라는 과학 기술은 여느 나라 만큼이나 발전한 데 비해 시민 의식은 여전히 후진국 수준이다.", "Compared to how developed its science and technology are, that country's civic awareness is still at a developing-nation level."], ["이 지역은 물가가 비싼 데 비해 임금 수준은 낮은 편이다.", "Compared to how expensive the cost of living is in this area, wage levels are relatively low."]], "notes": "데 비해(서) and 데 반해(서) are essentially interchangeable; don't confuse with N에 비해(서), which is a direct comparison between two nouns similar to 보다.", "label_ko": null, "label_vi": null, "definition_ko": "'~는 반면에'와 거의 같은 뜻이지만 두 대상의 수준을 직접 비교하는 느낌을 준다: 'A인 데 비해 B이다'.", "definition_vi": "Gần giống '-는 반면에' nhưng nhấn mạnh việc so sánh trực tiếp mức độ giữa hai vế: 'So với việc A thì B'.", "notes_ko": "데 비해(서)와 데 반해(서)는 거의 같은 뜻으로 바꿔 쓸 수 있으며, 명사를 직접 비교하는 'N에 비해(서)'(보다와 유사)와는 다르다.", "notes_vi": "데 비해(서) và 데 반해(서) gần như có thể thay thế cho nhau; đừng nhầm với 'N에 비해(서)' vốn so sánh trực tiếp hai danh từ, giống 보다."}]$$::jsonb, $$["는 반면", "은 반면", "ㄴ 반면", "데 비해", "데 반해"]$$::jsonb, false, now()),
('치고-는', '-치고(는)', 'intermediate', 4, 3, 30, 45, $$[{"label": "Considering / for X (generalization with exception)", "definition": "States a generalization about a category, with the sentence typically negative to say there is no exception: 'There isn't a X who/that isn't Y.'", "formation": "Noun + 치고 (+ negative predicate)", "examples": [["성공한 사람치고 부지런하지 않은 사람이 없다.", "There isn't a successful person who isn't diligent."], ["작은 호텔치고 숙박비가 비싼 편이다.", "For a small hotel, the room charge is rather expensive."]], "notes": "치고는 (with 는) softens it into 'for a X, ...(unusually)'; often paired with 편이다. 치고 alone before a negative predicate means 'there's no X that isn't...'", "label_ko": null, "label_vi": null, "definition_ko": "어떤 범주에 대한 일반화를 말할 때 쓰며, 흔히 부정문과 함께 예외가 없음을 나타낸다: 'N치고 -지 않은 것이 없다'.", "definition_vi": "Dùng để khái quát về một nhóm/loại, thường đi với câu phủ định để nói rằng không có ngoại lệ: 'Không có N nào mà không...'.", "notes_ko": "치고는(는 추가)은 'N치고는'으로 '~에 비해 예상 밖으로'라는 뉘앙스를 주며 흔히 '편이다'와 함께 쓰인다.", "notes_vi": "치고는 (thêm 는) mang sắc thái 'so với N thì lại...(bất ngờ)', thường đi kèm với 편이다."}]$$::jsonb, $$["치고는", "치고"]$$::jsonb, false, now()),
('는-편이다', '-는 편이다', 'intermediate', 5, 1, 45, 50, $$[{"label": "Tend to be / on the ... side", "definition": "Softens a description by saying something is relatively or somewhat a certain way, rather than absolutely: 'It's more on the A side' / 'tends to V.'", "formation": "Verb/Adj stem + -는/(으)ㄴ 편이다", "examples": [["제 남자친구는 키가 크고 조금 통통한 편이에요.", "My boyfriend is rather tall and a bit on the chubby side."], ["그는 커피에 비해서 녹차를 많이 마시는 편이에요.", "He tends to drink more green tea than coffee, comparatively."]], "notes": "Often used with a comparison (~에 비해서, 보다); softer and more common in everyday speech than stating a fact outright.", "label_ko": null, "label_vi": null, "definition_ko": "어떤 상태를 단정적으로 말하지 않고 '비교적, 대체로 그러하다'라고 완곡하게 표현할 때 쓴다.", "definition_vi": "Dùng để diễn đạt một cách nhẹ nhàng, không khẳng định tuyệt đối rằng điều gì đó 'tương đối, nhìn chung là như vậy'.", "notes_ko": "'~에 비해서, 보다'와 같은 비교 표현과 자주 함께 쓰이며, 단정적으로 말하는 것보다 부드러운 인상을 준다.", "notes_vi": "Thường đi cùng các cách so sánh như '~에 비해서, 보다'; tạo cảm giác nhẹ nhàng hơn so với khẳng định trực tiếp."}]$$::jsonb, $$["는 편이다", "은 편이다", "ㄴ 편이다", "는 편이", "은 편이"]$$::jsonb, true, now()),
('는-감이-있다', '-는 감이 있다', 'intermediate', 3, 2, 35, 45, $$[{"label": "Feels somewhat / a bit too...", "definition": "Expresses that something gives off a subjective feeling of being a certain way, often mildly negative — stronger and more subjective than -는 편이다.", "formation": "Verb/Adj stem + -는/(으)ㄴ 감이 있다", "examples": [["영화가 좀 너무 단순한 감이 있어.", "This movie is somewhat too simple, I feel."], ["저 선생님 수업은 지겨운 감이 있어서 싫어요.", "That teacher's class kind of feels boring, so I don't like it."]], "notes": "감(感) means 'feeling'; unlike -는 편이다 (which is comparative and non-committal), 감이 있다 states the speaker's own subjective impression more strongly.", "label_ko": null, "label_vi": null, "definition_ko": "어떤 대상에 대해 주관적으로 느껴지는 인상을 나타낼 때 쓰며, 흔히 다소 부정적인 뉘앙스를 갖는다.", "definition_vi": "Diễn đạt cảm giác chủ quan của người nói về điều gì đó, thường mang sắc thái hơi tiêu cực.", "notes_ko": "감(感)은 '느낌'이라는 뜻으로, 비교의 뉘앙스를 갖는 '-는 편이다'보다 화자의 주관적 인상을 더 강하게 드러낸다.", "notes_vi": "감(感) nghĩa là 'cảm giác'; so với '-는 편이다' mang tính so sánh, '감이 있다' thể hiện ấn tượng chủ quan của người nói mạnh hơn."}]$$::jsonb, $$["는 감이 있다", "은 감이 있다", "ㄴ 감이 있다"]$$::jsonb, true, now()),
('에다가', '-에다가', 'intermediate', 4, 1, 40, 50, $$[{"label": "Also / in addition to; on / at", "definition": "Attaches to a noun to mean 'also/and' (adding one thing to another), or marks the location where something is placed: 'on/at N.'", "formation": "Noun + 에다가 (often shortened to 에다)", "examples": [["여기에다가 성함과 나이를 써주세요.", "Please write your name and age here."], ["요즘 집안일에다가 회사 일까지 겹쳐서 힘들어 죽겠어요.", "These days housework on top of work has piled up, so I'm exhausted."]], "notes": "Colloquial; interchangeable with 뿐만 아니라/게다가 in its 'also/moreover' sense. Not to be confused with the connective -는 데다가, which attaches to verbs/adjectives.", "label_ko": null, "label_vi": null, "definition_ko": "명사에 붙어 '또한, 게다가'라는 뜻을 더하거나, 무언가가 놓이는 장소를 나타낼 때 쓴다.", "definition_vi": "Gắn vào danh từ mang nghĩa 'cũng, thêm vào đó', hoặc chỉ nơi chốn mà vật gì đó được đặt vào.", "notes_ko": "구어체 표현으로 '뿐만 아니라/게다가'와 바꿔 쓸 수 있으며, 동사/형용사에 붙는 연결어미 '-는 데다가'와는 다르다.", "notes_vi": "Là cách nói khẩu ngữ, có thể thay bằng '뿐만 아니라/게다가'; khác với vĩ tố liên kết '-는 데다가' gắn vào động từ/tính từ."}]$$::jsonb, $$["에다가", "에다"]$$::jsonb, false, now()),
('는-바람에', '-는 바람에', 'intermediate', 4, 2, 35, 50, $$[{"label": "Because of (unintended negative result)", "definition": "Links a sudden cause to a negative, unintended result: 'As a result of A (which just happened), unfortunately B.'", "formation": "Verb stem (present tense form) + -는 바람에", "examples": [["갑자기 차가 나오는 바람에 사고가 났어요.", "A car suddenly pulled out, and as a result there was an accident."], ["택시를 타는 바람에 돈을 다 썼어요.", "Because I took a taxi, I spent all my money."]], "notes": "P1 is usually stated in present tense form and P2 in past tense; both halves are typically negative/unfortunate outcomes.", "label_ko": null, "label_vi": null, "definition_ko": "예상치 못한 원인이 부정적이고 의도치 않은 결과로 이어질 때 쓴다: 'A하는 바람에 (안타깝게도) B했다'.", "definition_vi": "Dùng khi một nguyên nhân bất ngờ dẫn đến kết quả tiêu cực, ngoài ý muốn: 'Vì A (đột ngột xảy ra) nên B (đáng tiếc)'.", "notes_ko": "앞 절은 보통 현재형으로, 뒤 절은 과거형으로 쓰이며 두 절 모두 부정적이거나 아쉬운 내용인 경우가 많다.", "notes_vi": "Vế trước thường ở thì hiện tại, vế sau ở thì quá khứ; cả hai vế thường mang nội dung tiêu cực hoặc đáng tiếc."}]$$::jsonb, $$["는 바람에"]$$::jsonb, false, now()),
('는-탓에-탓이다', '-는 탓에 / 탓이다', 'intermediate', 4, 2, 40, 50, $$[{"label": "Due to the fault of / because of", "definition": "Blames a negative result on a cause, similar to -는 바람에 but centered on 'fault': 'It is B because of the fault of A.'", "formation": "Verb/Adj stem + -는/(으)ㄴ 탓에 ... / N 탓에 ...", "examples": [["공부를 하지 않은 탓에 시험에서 떨어졌어요.", "I failed the exam because I didn't study (my fault)."], ["영수는 잔소리를 하는 엄마 탓에 기분이 나빴다.", "Yeongsu was in a bad mood because of his nagging mom."]], "notes": "탓하다 as a separate verb means 'to blame someone' (e.g. 네 탓하지 마 = don't blame it on me). 탓이다 can end a sentence: '비가 온 탓이야' (it's because it rained).", "label_ko": null, "label_vi": null, "definition_ko": "부정적인 결과의 원인을 '탓(잘못)'으로 돌릴 때 쓰며, '-는 바람에'와 비슷하지만 책임/잘못의 뉘앙스가 강하다.", "definition_vi": "Đổ lỗi cho một nguyên nhân dẫn đến kết quả tiêu cực, gần giống '-는 바람에' nhưng nhấn mạnh ý 'lỗi/trách nhiệm'.", "notes_ko": "동사 '탓하다'는 '누군가를 탓하다(비난하다)'라는 뜻이며, '탓이다'는 문장을 끝맺는 서술어로도 쓰인다.", "notes_vi": "Động từ '탓하다' nghĩa là 'đổ lỗi cho ai đó'; '탓이다' cũng có thể dùng để kết thúc câu."}]$$::jsonb, $$["는 탓에", "은 탓에", "탓이다", "탓이야", "탓이에요"]$$::jsonb, false, now()),
('을까-나-지-싶다', '-을까/나/지 싶다', 'intermediate', 3, 3, 30, 45, $$[{"label": "Wonder if / think maybe (introspective)", "definition": "Expresses a soft, introspective wondering or worry about whether something is/was the case — more tentative and curious than a plain guess.", "formation": "Verb/Adj stem + -을까/나/(으)ㄴ지/는지 싶다", "examples": [["내일도 비가 많이 올까 싶네요.", "I wonder if it'll rain a lot again tomorrow."], ["철수가 이거 다 먹을 수 있나 싶었어.", "I wondered if Cheolsu could really eat all of this."]], "notes": "-을까 싶다 and -나 싶다 are close in meaning; -나 싶다 adds a touch of extra curiosity. -지 싶다 wonders while implying the speaker wants confirmation.", "label_ko": null, "label_vi": null, "definition_ko": "어떤 일이 그러한지 아닌지에 대해 조심스럽게 궁금해하거나 걱정하는 마음을 나타낸다.", "definition_vi": "Diễn đạt sự băn khoăn, lo lắng nhẹ nhàng, mang tính nội tâm về việc điều gì đó có đúng hay không.", "notes_ko": "'-을까 싶다'와 '-나 싶다'는 뜻이 비슷하며, '-나 싶다'는 궁금함이 조금 더 강조된다. '-지 싶다'는 확인받고 싶은 뉘앙스가 있다.", "notes_vi": "'-을까 싶다' và '-나 싶다' có nghĩa gần giống nhau; '-나 싶다' nhấn mạnh sự tò mò hơn. '-지 싶다' mang ý muốn được xác nhận."}]$$::jsonb, $$["을까 싶", "ㄹ까 싶", "나 싶", "는지 싶", "은지 싶"]$$::jsonb, false, now()),
('기에', '-기에', 'intermediate', 3, 3, 45, 50, $$[{"label": "Because, since (formal cause)", "definition": "A formal/written cause-and-effect connective, similar to -어서 but more literary: 'because of P1, (I) did P2.'", "formation": "Verb/Adj stem + -기에", "examples": [["한 번 한 말은 취소할 수 없기에 조심해야 합니다.", "Because you can't take back something you've already said, you must be careful."], ["배움에는 끝이 없기에 꾸준히 배워야 합니다.", "Because learning has no end, one must keep learning steadily."]], "notes": "Don't confuse with -기에는 ('from the standpoint of doing'). Plain -기에 is a cause/reason connective, mostly used in writing or formal speech.", "label_ko": null, "label_vi": null, "definition_ko": "'-어서'와 비슷하지만 더 격식적이고 문어체적인 원인-결과 연결어미이다: 'A하기에 B했다'.", "definition_vi": "Gần giống '-어서' nhưng trang trọng và mang tính văn viết hơn, nối nguyên nhân với kết quả: 'Vì A nên B'.", "notes_ko": "'-기에는'(어떤 것을 하기에는 이라는 관점을 나타냄)과 혼동하지 말 것; 단순 '-기에'는 원인을 나타내는 연결어미이다.", "notes_vi": "Đừng nhầm với '-기에는' (nghĩa 'xét theo góc độ làm gì'); '-기에' đơn thuần là vĩ tố nối chỉ nguyên nhân."}]$$::jsonb, $$["기에"]$$::jsonb, false, now()),
('에-따라-서', '-에 따라(서)', 'intermediate', 5, 1, 45, 50, $$[{"label": "Depending on / according to", "definition": "States that something varies depending on N, or acts according to N: 'It depends on N' / 'according to N, ...'", "formation": "Noun + 에 따라(서) (다르다); Verb + -는지/(으)ㄴ지에 따라(서)", "examples": [["시간에 따라서 달라요.", "It's different depending on the time."], ["누가 하는지에 따라서 달라요.", "It depends on who does it."]], "notes": "따라서 alone can mean 'therefore/according to this'. N마다 다르다 ('every N is different') is a related, simpler alternative for the same idea.", "label_ko": null, "label_vi": null, "definition_ko": "무언가가 N에 의해 달라지거나 N을 근거로 이루어짐을 나타낸다: 'N에 따라 다르다', 'N에 따라서 -하다'.", "definition_vi": "Diễn đạt điều gì đó thay đổi tùy theo N, hoặc được thực hiện dựa theo N: 'Tùy vào N mà khác nhau'.", "notes_ko": "'따라서'만 단독으로 쓰이면 '그러므로, 이에 따라'라는 뜻이 된다. 'N마다 다르다'도 비슷한 뜻의 더 간단한 표현이다.", "notes_vi": "'따라서' đứng một mình có thể mang nghĩa 'do đó, theo đó'. 'N마다 다르다' là cách nói đơn giản hơn với ý tương tự."}]$$::jsonb, $$["에 따라서", "에 따라", "느냐에 따라"]$$::jsonb, false, now()),
('고-말다', '-고 말다', 'intermediate', 4, 2, 40, 50, $$[{"label": "End up (unintentionally / regretfully)", "definition": "Marks that something undesirable ended up happening, similar to -게 되다 but always about a negative or regrettable outcome.", "formation": "Verb stem + -고 말다", "examples": [["뛰어갔는데도 지각하고 말았어요.", "Even though I ran, I ended up being late."], ["잠을 참으려고 했지만 자고 말았다.", "I tried to stay awake, but I ended up falling asleep."]], "notes": "-고 말겠다/말 테니까 flips it into a strong vow ('I will definitely...'). -고 말이다 (colloquial) adds emphasis like 'I mean...'. -(으)려다가 말았다 means 'was about to, but stopped'.", "label_ko": null, "label_vi": null, "definition_ko": "원치 않거나 아쉬운 일이 결국 일어났음을 나타내며, '-게 되다'와 비슷하지만 항상 부정적인 결과에 쓰인다.", "definition_vi": "Diễn đạt việc điều không mong muốn hoặc đáng tiếc cuối cùng đã xảy ra; giống '-게 되다' nhưng luôn mang kết quả tiêu cực.", "notes_ko": "'-고 말겠다/말 테니까'는 '반드시 ~하겠다'는 강한 다짐으로 바뀌고, '-고 말이다'는 구어체로 강조를 더한다. '-(으)려다가 말았다'는 '~하려다가 그만두었다'는 뜻이다.", "notes_vi": "'-고 말겠다/말 테니까' biến thành lời thề mạnh mẽ 'nhất định sẽ...'; '-고 말이다' là cách nói khẩu ngữ để nhấn mạnh. '-(으)려다가 말았다' nghĩa là 'định làm nhưng rồi thôi'."}]$$::jsonb, $$["고 말았", "고 말겠", "고 말 테니까", "고 말 것이다", "고 말이"]$$::jsonb, false, now()),
('고자-하다', '-고자 (하다)', 'intermediate', 3, 3, 70, 55, $$[{"label": "In order to (formal)", "definition": "A formal, written equivalent of -기 위해(서)/-(으)려고, expressing purpose or intention. Not restricted to first person.", "formation": "Verb stem + -고자 (하다)", "examples": [["이 제품이 지속적으로 좋은 반응을 얻고 있어서 생산량을 늘리고자 합니다.", "As this product continues to get a good response, we intend to increase production."], ["부모님께 드리고자 이 물건을 구매했습니다.", "I purchased this item in order to give it to my parents."]], "notes": "Cannot be used with negative markers like 안/못 directly after the stem. Common in announcements, business writing, and formal speeches.", "label_ko": null, "label_vi": null, "definition_ko": "'-기 위해(서)/-(으)려고'의 격식체·문어체 표현으로 목적이나 의도를 나타내며 1인칭에 국한되지 않는다.", "definition_vi": "Là cách nói trang trọng, mang tính văn viết của '-기 위해(서)/-(으)려고', diễn đạt mục đích hoặc ý định, không giới hạn ở ngôi thứ nhất.", "notes_ko": "동사 어간 뒤에 안/못과 같은 부정 표현을 바로 붙일 수 없으며, 공지문·업무 글·격식 있는 발표에서 자주 쓰인다.", "notes_vi": "Không thể gắn trực tiếp 안/못 sau thân động từ; thường dùng trong thông báo, văn bản công việc, bài phát biểu trang trọng."}]$$::jsonb, $$["고자"]$$::jsonb, false, now()),
('기-일쑤이다', '-기 일쑤이다', 'intermediate', 3, 3, 35, 45, $$[{"label": "Tend to / often ends up ...-ing", "definition": "Says that something happens frequently, and the frequent occurrence is usually negative: 'I'm often...' / 'has a habit of...'", "formation": "Verb stem + -기 일쑤이다", "examples": [["나는 늦게 자는 버릇이 있어서 지각하기 일쑤이다.", "I have a habit of sleeping late, so I often end up being late."], ["그 남자는 거짓말하기 일쑤예요.", "That man is always lying (has a habit of lying)."]], "notes": "일쑤 means 'being common/habitual'; almost always used with negative or undesirable habits, unlike the more neutral -곤 하다.", "label_ko": null, "label_vi": null, "definition_ko": "앞의 상황이 자주 일어남을 나타내며, 그 빈번함은 대개 부정적인 경우에 쓴다: '자주 ~하다, ~하는 버릇이 있다'.", "definition_vi": "Diễn đạt việc điều gì đó xảy ra thường xuyên, và sự thường xuyên đó thường mang nghĩa tiêu cực: 'hay, có thói quen...'.", "notes_ko": "일쑤는 '흔함, 습관적임'이라는 뜻으로, 비교적 중립적인 '-곤 하다'와 달리 거의 항상 부정적인 습관에 쓰인다.", "notes_vi": "일쑤 nghĩa là 'thường xuyên, mang tính thói quen'; khác với '-곤 하다' trung tính hơn, hầu như luôn dùng cho thói quen tiêu cực."}]$$::jsonb, $$["기 일쑤"]$$::jsonb, true, now()),
('기가-무섭게', '-기가 무섭게', 'intermediate', 3, 3, 40, 50, $$[{"label": "As soon as (emphatic)", "definition": "An emphatic version of -자마자: the moment P1 happens, P2 happens right away, with no gap at all. Cannot be used as a command.", "formation": "Verb stem + -기(가) 무섭게 (also -기가 바쁘게)", "examples": [["눈을 치우기가 무섭게 또 눈이 쌓이고 있어요.", "No sooner had I cleared the snow than it started piling up again."], ["아침에 눈 뜨기가 바쁘게 집에서 나왔어요.", "I left the house the very moment I woke up."]], "notes": "-자 (formal, written-only) is similar but implies P1 leads to P2 as a result, and also cannot be a command; both differ from -자마자 by adding extra emphasis or a cause-effect nuance.", "label_ko": null, "label_vi": null, "definition_ko": "'-자마자'를 강조한 표현으로, P1이 일어나자마자 조금의 틈도 없이 바로 P2가 일어남을 나타낸다. 명령문에는 쓸 수 없다.", "definition_vi": "Là cách nhấn mạnh của '-자마자': ngay khi P1 xảy ra, P2 xảy ra lập tức không chút khoảng cách. Không dùng trong câu mệnh lệnh.", "notes_ko": "문어체인 '-자'도 비슷하지만 P1이 P2의 원인이 됨을 암시하며 역시 명령문에는 쓸 수 없다.", "notes_vi": "'-자' (chỉ dùng trong văn viết) cũng tương tự nhưng ngụ ý P1 là nguyên nhân dẫn đến P2, và cũng không dùng trong câu mệnh lệnh."}]$$::jsonb, $$["기가 무섭게", "기 무섭게", "기가 바쁘게"]$$::jsonb, false, now()),
('조차', '-조차', 'intermediate', 4, 2, 45, 50, $$[{"label": "Even (negative only)", "definition": "Means 'even', but unlike 도/까지도, it's restricted to negative or undesirable verbs/situations, adding a sense of the unexpected.", "formation": "Noun + 조차 (+ negative predicate)", "examples": [["우리는 얼굴조차 본 적이 없어.", "We haven't even seen each other's faces."], ["너무 시끄러워서 집중할 수조차 없어요.", "It's so loud that I can't even concentrate."]], "notes": "Often used comparatively: 'there are other bad things too, but even this is bad.' Compare with 마저(도), which has a similar 'even' meaning but emphasizes being the last/worst case.", "label_ko": null, "label_vi": null, "definition_ko": "'도, 까지도'와 비슷하게 '~조차'는 '심지어'라는 뜻이지만 부정적이거나 바람직하지 않은 동사/상황에만 쓰여 의외성을 더한다.", "definition_vi": "Có nghĩa 'thậm chí' giống '도, 까지도' nhưng chỉ dùng với động từ/tình huống tiêu cực, mang thêm sắc thái bất ngờ.", "notes_ko": "'다른 나쁜 일도 있지만 이것조차 나쁘다'처럼 비교하는 맥락에서 자주 쓰인다. 비슷한 '마저(도)'는 마지막/최악의 경우를 강조한다는 점에서 다르다.", "notes_vi": "Thường dùng trong ngữ cảnh so sánh: 'còn có những điều tệ khác, nhưng ngay cả điều này cũng tệ'. '마저(도)' tương tự nhưng nhấn mạnh đây là trường hợp cuối cùng/tệ nhất."}]$$::jsonb, $$["조차"]$$::jsonb, false, now()),
('마저-도', '-마저(도)', 'intermediate', 3, 3, 55, 50, $$[{"label": "Even (as the last straw)", "definition": "Means 'even', implying N is the last in a series and its inclusion makes the situation especially bad — a formal, written equivalent of 조차.", "formation": "Noun + 마저(도)", "examples": [["가방에 있는 사탕마저 다 먹어버렸어.", "I even ate all the candy that was in my bag (the last thing left)."], ["철수마저 그 사람을 싫어하는 걸 보면 정말 별로인 사람이겠네.", "If even Cheolsu dislikes that person, they must really be no good."]], "notes": "Same core meaning as 까지도/조차 ('even'), but always negative and implies N is the last item of a group; more formal and literary in tone.", "label_ko": null, "label_vi": null, "definition_ko": "'심지어'라는 뜻이며 N이 일련의 마지막임을 암시해 상황을 더 나쁘게 만든다는 느낌을 준다. '조차'의 격식체·문어체 표현이다.", "definition_vi": "Có nghĩa 'thậm chí' giống '까지도/조차' nhưng luôn mang nghĩa tiêu cực và ngụ ý N là điều cuối cùng trong một chuỗi, khiến tình huống tệ hơn. Là cách nói trang trọng, văn viết.", "notes_ko": "'까지도/조차'와 핵심 의미는 같지만 항상 부정적이며 N이 그 무리 중 마지막임을 전제로 한다.", "notes_vi": "Cùng nghĩa cốt lõi với '까지도/조차' nhưng luôn tiêu cực và giả định N là thứ cuối cùng trong nhóm."}]$$::jsonb, $$["마저도", "마저"]$$::jsonb, false, now()),
('느니-차라리', '-느니 (차라리)', 'intermediate', 4, 2, 35, 50, $$[{"label": "Rather than (P1), P2", "definition": "Says P1 is a bad choice, so P2 (often also imperfect, but preferred) should be done instead: 'I would rather P2 than P1.'", "formation": "Verb stem + -느니 (차라리) + P2", "examples": [["팝콘을 먹느니 뻥튀기를 먹겟어.", "Rather than eat popcorn, I'd eat rice puffs."], ["이런 침대에서 잠을 자느니 바닥에서 자는 게 더 편해.", "Rather than sleep in a bed like this, sleeping on the floor is more comfortable."]], "notes": "차라리 ('rather') can stand alone: '이런 식으로 할 거면 차라리 하지를 마' (if you're going to do it this way, just don't do it at all). Note 오히려 looks similar but means 'on the contrary' with a positive slant, unlike 차라리's negative one.", "label_ko": null, "label_vi": null, "definition_ko": "P1이 나쁜 선택임을 말하고 그 대신 P2(역시 완벽하지는 않지만 더 나은 선택)를 하겠다는 뜻이다: 'P1하느니 차라리 P2하겠다'.", "definition_vi": "Nói rằng P1 là lựa chọn không tốt, nên thà làm P2 (cũng chưa hoàn hảo nhưng tốt hơn) còn hơn: 'Thà P2 còn hơn P1'.", "notes_ko": "차라리('차라리')는 단독으로도 쓸 수 있다. 비슷해 보이는 '오히려'는 '반대로'라는 뜻으로 긍정적인 뉘앙스를 갖는다는 점이 다르다.", "notes_vi": "차라리 có thể đứng một mình. '오히려' trông tương tự nhưng nghĩa là 'ngược lại' và mang sắc thái tích cực, khác với 차라리."}]$$::jsonb, $$["느니 차라리", "느니"]$$::jsonb, false, now()),
('아-어다가', '-아/어다가', 'intermediate', 3, 2, 35, 50, $$[{"label": "Do P1, then carry it and do P2 elsewhere", "definition": "Marks that an object is brought from the location of P1 to a different location where P2 happens: 'P1 (and bring it), then P2 (somewhere else).'", "formation": "Verb stem + -아/어다가", "examples": [["이 우산을 가져다가 쓰세요.", "Take this umbrella (from here) and use it (there)."], ["저기서 물고기를 잡아다가 먹을까요?", "Shall we catch fish over there and bring them back to eat?"]], "notes": "TV/written form; only used with verbs, and only makes sense when P1 and P2 happen in two different locations, with an object being brought from one to the other.", "label_ko": null, "label_vi": null, "definition_ko": "P1이 일어난 장소에서 대상을 가지고 와 다른 장소에서 P2를 함을 나타낸다: 'P1해서 가지고 와 P2하다'.", "definition_vi": "Diễn đạt việc mang một vật từ nơi xảy ra P1 sang nơi khác để làm P2: 'Làm P1 (và mang theo), rồi làm P2 (ở nơi khác)'.", "notes_ko": "주로 문어체/격식적인 상황에서 쓰이며 동사에만 결합하고, P1과 P2가 서로 다른 장소에서 일어날 때만 자연스럽다.", "notes_vi": "Thường dùng trong văn viết/trang trọng, chỉ kết hợp với động từ, và chỉ tự nhiên khi P1 và P2 xảy ra ở hai nơi khác nhau."}]$$::jsonb, $$["다가", "아다가", "어다가"]$$::jsonb, false, now()),
('아-어-대다', '-아/어 대다', 'intermediate', 3, 2, 20, 35, $$[{"label": "Keep doing (excessively / annoyingly)", "definition": "Says a third person has been doing something continuously and to an excessive, often annoying, degree.", "formation": "Verb stem + -아/어 대다", "examples": [["철수는 요즘 잠도 안 자고 게임 해 대요.", "Cheolsu's been gaming nonstop lately without even sleeping."], ["밖에서 고양이가 밤마다 울어 대서 잠을 자기 힘들어요.", "A cat outside keeps yowling every night, so it's hard to sleep."]], "notes": "Informal and not polite in tone; can also be used as a warning similar to -다가는 ('if you keep V-ing like that, ...').", "label_ko": null, "label_vi": null, "definition_ko": "제3자가 어떤 행동을 계속, 그것도 지나치게(흔히 짜증스러울 정도로) 하고 있음을 나타낸다.", "definition_vi": "Diễn đạt việc người thứ ba liên tục làm điều gì đó một cách quá mức, thường gây khó chịu.", "notes_ko": "격식을 차리지 않은 표현으로, '-다가는'처럼 경고의 의미로도 쓰일 수 있다.", "notes_vi": "Là cách nói không trang trọng; cũng có thể dùng như lời cảnh báo giống '-다가는'."}]$$::jsonb, $$["아 대", "어 대", "해 대"]$$::jsonb, false, now()),
('이자', '-이자', 'intermediate', 4, 1, 50, 50, $$[{"label": "Being both N and N", "definition": "Says a subject or object is simultaneously two (or more) things at once: 'N, and also N.'", "formation": "Noun + 이자 (+ Noun (+이자 Noun))", "examples": [["네가 내 삶의 원동력이자 희망이자 목표야.", "You are my driving force, my hope, and my goal, all at once."], ["아이유는 가수이자 배우로 많은 사람들에게 사랑 받고 있다.", "IU is loved by many people as both a singer and an actress."]], "notes": "Can chain more than two nouns (N이자 N이자 N); the subject/object genuinely holds all the roles listed, not just one or the other.", "label_ko": null, "label_vi": null, "definition_ko": "주어나 목적어가 동시에 두 가지(또는 그 이상)의 것임을 나타낸다: 'N이자 N이다'.", "definition_vi": "Diễn đạt chủ ngữ hoặc tân ngữ đồng thời là hai (hoặc nhiều) thứ cùng lúc: 'vừa là N vừa là N'.", "notes_ko": "두 개보다 많은 명사를 연결할 수도 있으며(N이자 N이자 N), 나열된 역할을 모두 동시에 가진다는 뜻이다.", "notes_vi": "Có thể nối nhiều hơn hai danh từ (N이자 N이자 N); chủ thể thực sự mang tất cả các vai trò được liệt kê cùng lúc."}]$$::jsonb, $$["이자"]$$::jsonb, false, now()),
('만-하다', '-만 하다', 'intermediate', 3, 2, 35, 50, $$[{"label": "As big/much as N", "definition": "Compares the size, number, or degree of something to N, often idiomatically: '(as big) as a N' / 'about the size of N.'", "formation": "Noun + 만 하다 / 만 한 + Noun", "examples": [["저 개는 정말 크네요. - 네, 정말 개가 송아지만 하네요.", "That dog is really big. - Yeah, it's really about the size of a calf."], ["주먹만 한 돌", "a rock about the size of a fist"]], "notes": "N만 해도 (or 하더라도) means 'for example, take N' — introducing N as a supporting example, unrelated to the size-comparison sense.", "label_ko": null, "label_vi": null, "definition_ko": "무언가의 크기, 수, 정도를 N과 비교할 때 쓰며 흔히 관용적으로 쓰인다: 'N만 하다', 'N만 한 N'.", "definition_vi": "So sánh kích thước, số lượng, mức độ của điều gì đó với N, thường mang tính thành ngữ: 'to/nhiều bằng N'.", "notes_ko": "'N만 해도(하더라도)'는 크기 비교와는 별개로 'N을 예로 들면'이라는 뜻으로, N을 예시로 제시할 때 쓴다.", "notes_vi": "'N만 해도(하더라도)' không liên quan đến so sánh kích thước, mà mang nghĩa 'lấy ví dụ N', dùng để đưa N ra làm ví dụ minh họa."}]$$::jsonb, $$["만 하다", "만 한", "만 해요", "만 했"]$$::jsonb, false, now()),
('만에', '-만에', 'intermediate', 5, 1, 45, 50, $$[{"label": "After only N (amount of time)", "definition": "Written after an amount of time to mean that something (new) happens once that amount of time has passed — emphasizing that the time was short or long.", "formation": "Time Noun + 만에", "examples": [["입학한 지 5년 만에 졸업했어요.", "I graduated 5 years after enrolling."], ["시작한 지 1시간 만에 도착했다.", "We arrived just 1 hour after starting."]], "notes": "Almost always follows '~(으)ㄴ 지 [시간] 만에' (it's been [time] since ~); emphasizes how surprisingly short or long that time was.", "label_ko": null, "label_vi": null, "definition_ko": "시간을 나타내는 말 뒤에 쓰여 그 시간이 지난 후에 (새로운) 일이 생겼음을 나타내며, 시간이 짧거나 길다는 것을 강조한다.", "definition_vi": "Viết sau khoảng thời gian để diễn đạt rằng sau khi thời gian đó trôi qua thì điều gì đó (mới) xảy ra, nhấn mạnh khoảng thời gian đó ngắn hay dài.", "notes_ko": "거의 항상 '~(으)ㄴ 지 [시간] 만에' 형태로 쓰이며, 그 시간이 뜻밖으로 짧거나 길다는 점을 강조한다.", "notes_vi": "Hầu như luôn dùng ở dạng '~(으)ㄴ 지 [thời gian] 만에'; nhấn mạnh khoảng thời gian đó ngắn hoặc dài một cách bất ngờ."}]$$::jsonb, $$["만에"]$$::jsonb, false, now()),
('고말고-요', '-고말고(요)', 'intermediate', 3, 1, 20, 45, $$[{"label": "Of course! (strong agreement)", "definition": "A strong, enthusiastic agreement meaning 'of course', 'certainly' — similar to 물론이다/당연히 그렇다.", "formation": "Verb/Adj stem (conjugated) + -고말고(요)", "examples": [["네, 숙제 다 했고말고요.", "Yes, of course I did all my homework."], ["네, 깎아 드리고말고요.", "Sure, of course I'll give you a discount."]], "notes": "Can replace -자고/-고 싶다 in offers ('보러 갈래고 → 보러 가고말고'); can also attach after -(으)ㄹ게요/겠습니다 for a formal 'of course I will'.", "label_ko": null, "label_vi": null, "definition_ko": "'물론이다, 당연히 그렇다'와 비슷하게 강하고 적극적인 동의를 나타내는 표현이다.", "definition_vi": "Là cách diễn đạt sự đồng ý mạnh mẽ, nhiệt tình, giống '물론이다, 당연히 그렇다' (dĩ nhiên, đương nhiên là vậy).", "notes_ko": "제안을 나타내는 '-자고/-고 싶다' 대신 쓸 수 있으며, '-(으)ㄹ게요/겠습니다' 뒤에 붙여 격식 있는 '당연히 하겠습니다'로도 쓸 수 있다.", "notes_vi": "Có thể thay cho '-자고/-고 싶다' khi đề nghị; cũng có thể gắn sau '-(으)ㄹ게요/겠습니다' để tạo thành cách nói trang trọng 'dĩ nhiên tôi sẽ làm'."}]$$::jsonb, $$["고말고요", "고말고"]$$::jsonb, true, now()),
('이야말로', '-이야말로', 'intermediate', 3, 2, 50, 50, $$[{"label": "Indeed / precisely the", "definition": "Emphasizes that N is indeed, definitely, or most of all the thing being discussed — 'N is indeed...' / 'the very N'.", "formation": "Noun + (이)야말로", "examples": [["사랑이야말로 결혼 생활에서 가장 중요한 것이다.", "Love is indeed the most important thing in married life."], ["그 디자인이야말로 제가 찾던 거예요.", "That design is exactly what I was looking for."]], "notes": "Emphatic particle; picks N out from among other candidates as 'exactly this one, not the others.'", "label_ko": null, "label_vi": null, "definition_ko": "N이 논의되고 있는 대상 중에서도 정말로, 확실히, 무엇보다도 그러하다는 것을 강조한다: 'N이야말로 ~이다'.", "definition_vi": "Nhấn mạnh rằng N thật sự, chắc chắn, hoặc hơn hết chính là điều đang được nói đến: 'chính N mới là...'.", "notes_ko": "강조 조사로, 다른 후보들 중에서 'N이 바로 이것이다, 다른 것이 아니다'라는 뉘앙스를 준다.", "notes_vi": "Là trợ từ nhấn mạnh, mang sắc thái 'chính N này, không phải cái khác' trong số các lựa chọn khác."}]$$::jsonb, $$["이야말로", "야말로"]$$::jsonb, false, now()),
('고도', '-고도', 'intermediate', 3, 3, 50, 50, $$[{"label": "Even after / even though (contrast)", "definition": "A stronger 'even though/even after' than -아/어도, typically about a third-person clause: 'even after/though (doing this), still...'", "formation": "Verb stem + -고도", "examples": [["그는 빵을 그렇게 많이 먹고도 배가 고프다고 한다.", "He says he's hungry even though he ate so much bread."], ["그녀는 선생님이 자기 이름을 부르는 것을 듣고도 대답하지 않았다.", "Even though she heard her teacher call her name, she did not answer."]], "notes": "Works for both present and past situations; -고 해도 is a related but distinct pattern used more in first-person 'even if I do' contexts.", "label_ko": null, "label_vi": null, "definition_ko": "'아/어도'보다 강한 '그럼에도 불구하고'라는 뜻이며 흔히 3인칭 절에 쓰인다: 'A하고도 B하다'.", "definition_vi": "Mang nghĩa 'dù vậy, mặc dù' mạnh hơn '아/어도', thường dùng với mệnh đề ngôi thứ ba: 'Dù đã A nhưng vẫn B'.", "notes_ko": "현재와 과거 상황 모두에 쓸 수 있으며, 비슷하지만 다른 '-고 해도'는 주로 1인칭의 '설령 ~해도'라는 맥락에 쓰인다.", "notes_vi": "Có thể dùng cho cả tình huống hiện tại và quá khứ; '-고 해도' tương tự nhưng khác, thường dùng ở ngôi thứ nhất với nghĩa 'dù có... đi nữa'."}]$$::jsonb, $$["고도"]$$::jsonb, false, now()),
('는-은-법이다', '-는/은 법이다', 'advanced', 3, 4, 55, 50, $$[{"label": "It's a rule / naturally the case that", "definition": "A more formal, emphatic version of -기 마련이다: states that something is a natural law or universal truth.", "formation": "Verb/Adj stem + -는/(으)ㄴ 법이다", "examples": [["사람은 쉽게 변하지 않는 법이야.", "People just don't easily change (that's the way it is)."], ["기대가 없으면 실망도 없는 법이에요.", "If there's no expectation, naturally there's no disappointment either."]], "notes": "Unlike -기 마련이다, -는 법이다 can be used with 안/못 negation. Very close in feel to '역시... N답게'.", "label_ko": null, "label_vi": null, "definition_ko": "'-기 마련이다'보다 더 격식적이고 강조된 표현으로, 무언가가 자연의 이치·보편적 진리임을 나타낸다.", "definition_vi": "Là cách nói trang trọng và nhấn mạnh hơn '-기 마련이다', diễn đạt rằng điều gì đó là quy luật tự nhiên, chân lý phổ quát.", "notes_ko": "'-기 마련이다'와 달리 '-는 법이다'는 안/못 부정형과 함께 쓸 수 있다.", "notes_vi": "Khác với '-기 마련이다', '-는 법이다' có thể dùng cùng với dạng phủ định 안/못."}, {"label": "-(으)ㄹ 법도 하다 (it's plausible that)", "definition": "A distinct, less common sense: says something isn't a certain fact but is a likely, believable possibility — 'one would expect that...'", "formation": "Verb stem + -(으)ㄹ 법도 하다", "examples": [["여러 상황을 생각해 보면 전쟁이 일어날 법도 하다.", "Thinking it over, it's plausible that a war could break out."], ["지금쯤 도착했을 법하니 전화를 한번 해 보시지요.", "They've probably arrived by now, so why don't you give them a call?"]], "notes": "법하다 alone (without 도) is more common and closer in meaning to -(으)ㄹ 수도 있다 ('probably/likely').", "label_ko": null, "label_vi": null, "definition_ko": "어떤 일이 확실한 사실은 아니지만 그럴듯하고 있음 직한 가능성임을 나타낼 때 쓴다.", "definition_vi": "Dùng khi điều gì đó không phải là sự thật chắc chắn nhưng có vẻ hợp lý, có khả năng xảy ra.", "notes_ko": "'도' 없이 '법하다'만 쓰는 것이 더 흔하며 '-(으)ㄹ 수도 있다'와 뜻이 비슷하다.", "notes_vi": "Cách dùng '법하다' (không có 도) phổ biến hơn và gần nghĩa với '-(으)ㄹ 수도 있다'."}]$$::jsonb, $$["는 법이다", "은 법이다", "ㄴ 법이다", "법도 하다", "법하다"]$$::jsonb, true, now()),
('는-ㄴ-셈이다', '-는/ㄴ 셈이다', 'advanced', 4, 3, 40, 50, $$[{"label": "Essentially / amounts to", "definition": "Says that although not literally true, a situation essentially amounts to, or could be summarized as, a certain conclusion.", "formation": "Verb/Adj stem + -는/(으)ㄴ 셈이다", "examples": [["할인을 받고 나면 한 병에 5백 원인 셈이에요.", "After the discount, it essentially comes out to 500 won a bottle."], ["결국 저 혼자 다 한 셈이지만 괜찮아요.", "In the end, it's basically like I did it all myself, but that's fine."]], "notes": "마찬가지다 ('the same/likewise') is a close, simpler synonym. Don't confuse with -는 셈 치다 ('pretend/assume that'), a different active pattern using the same 셈 root.", "label_ko": null, "label_vi": null, "definition_ko": "문자 그대로는 아니지만 어떤 상황이 결국 특정한 결론에 해당하거나 그렇게 요약될 수 있음을 나타낸다.", "definition_vi": "Diễn đạt rằng dù không đúng theo nghĩa đen, nhưng tình huống về cơ bản tương đương hoặc có thể tóm gọn thành một kết luận nào đó.", "notes_ko": "'마찬가지다'(같다, 똑같다)는 비슷하고 더 간단한 표현이다. 같은 '셈'을 쓰지만 다른 뜻인 '-는 셈 치다'(가정/치는 것으로 하다)와 혼동하지 말 것.", "notes_vi": "'마찬가지다' (giống nhau, như nhau) là từ đồng nghĩa đơn giản hơn. Đừng nhầm với '-는 셈 치다' (coi như/giả sử là), một mẫu câu chủ động khác dùng chung gốc '셈'."}]$$::jsonb, $$["는 셈이다", "은 셈이다", "ㄴ 셈이다", "는 셈이에요", "ㄴ 셈이에요"]$$::jsonb, true, now()),
('는-셈-치다-ㄴ-는다고-치다', '-는 셈 치다 / -ㄴ/는다고 치다', 'advanced', 3, 4, 25, 40, $$[{"label": "Let's assume / pretend that", "definition": "Says the speaker will treat a situation as if it were a certain way, even though it isn't (necessarily) true — 'let's just say/assume/pretend that...'", "formation": "Verb/Adj stem + -는 셈 치다 / -ㄴ/는다고 치다", "examples": [["이번은 네가 이긴 셈치자.", "Let's just say you won this time."], ["만난 적 없다고 치고 다시 시작하자.", "Let's pretend we've never met and start over."]], "notes": "-ㄴ/는다고 치다 is much more common and casual than 셈치다; 속는 셈 치고 means 'take a leap of faith / give it the benefit of the doubt' (lit. 'assuming I'm being tricked').", "label_ko": null, "label_vi": null, "definition_ko": "실제로 그렇지 않더라도 화자가 어떤 상황을 그런 것으로 여기거나 가정하겠다는 뜻이다: '~라고 치자, ~인 셈 치자'.", "definition_vi": "Diễn đạt việc người nói sẽ coi/giả định một tình huống là như vậy, dù thực tế không hẳn đúng: 'cứ coi như là...'.", "notes_ko": "'-ㄴ/는다고 치다'가 '셈 치다'보다 훨씬 더 흔하고 캐주얼하다. '속는 셈 치고'는 '밑져야 본전이라는 마음으로 한번 해보다'라는 뜻의 관용구이다.", "notes_vi": "'-ㄴ/는다고 치다' phổ biến và thân mật hơn nhiều so với '셈 치다'. '속는 셈 치고' là thành ngữ nghĩa 'cứ thử liều một phen, coi như bị lừa cũng được'."}]$$::jsonb, $$["셈 치", "다고 치", "라고 치"]$$::jsonb, false, now()),
('으-로서-으-로써', '-(으)로서/(으)로써', 'advanced', 4, 3, 70, 55, $$[{"label": "As (in the capacity/position of)", "definition": "-(으)로서 marks the role, position, or capacity in which the subject is acting: 'as/in the capacity of N.'", "formation": "Noun + (으)로서", "examples": [["동물을 사랑하는 사람으로서 마음이 너무 아프네요.", "As a person who loves animals, my heart really aches."], ["저는 그 사건의 검사로서 재판을 전담하기로 했습니다.", "As the prosecutor for that case, I decided to take full charge of the trial."]], "notes": "Often confused with N에 as 서 which doesn't exist — the key contrast is with -(으)로써 below, not with other particles.", "label_ko": null, "label_vi": null, "definition_ko": "'-(으)로서'는 주어가 어떤 역할, 지위, 자격으로 행동하는지를 나타낸다: 'N으로서'.", "definition_vi": "'-(으)로서' đánh dấu vai trò, vị trí, hoặc tư cách mà chủ ngữ đang hành động: 'với tư cách là N'.", "notes_ko": "다른 조사와 혼동되기보다는 아래의 '-(으)로써'와 혼동되기 쉬우므로 그 차이를 잘 구별해야 한다.", "notes_vi": "Thường bị nhầm lẫn với '-(으)로써' bên dưới hơn là với các trợ từ khác, nên cần phân biệt rõ."}, {"label": "-(으)로써 (by means of / made from)", "definition": "Marks the tool, ingredient, or method used to do or make something: 'made from/with/using N', or 'by means of N.'", "formation": "Noun + (으)로써", "examples": [["낙엽으로써 목면을 만들었다.", "They made a mask out of fallen leaves."], ["우리 회사는 광고로써 대부분의 수입을 올린다.", "Our company earns most of its income by means of advertising."]], "notes": "Used especially when the tool/ingredient/method isn't obvious or expected; can also mark 'including this' (예: 시험에 떨어진 것도 이번으로써 세 번째다 — 'including this time, it's the third time I've failed the exam').", "label_ko": null, "label_vi": null, "definition_ko": "무언가를 만들거나 하는 데 쓰인 도구, 재료, 방법을 나타낸다: 'N으로써 만들다/하다'.", "definition_vi": "Đánh dấu công cụ, nguyên liệu, hoặc phương pháp dùng để làm/tạo ra điều gì đó: 'bằng/nhờ N mà làm...'.", "notes_ko": "그 도구·재료·방법이 뜻밖이거나 예상 밖일 때 특히 자주 쓰이며, '이번으로써'처럼 '이것을 포함하여'라는 뜻으로도 쓰인다.", "notes_vi": "Đặc biệt hay dùng khi công cụ/nguyên liệu/phương pháp đó không hiển nhiên hoặc bất ngờ; cũng có thể mang nghĩa 'tính luôn cả lần này'."}]$$::jsonb, $$["로서", "으로서", "로써", "으로써"]$$::jsonb, false, now()),
('으-리라-고', '-(으)리라(고)', 'advanced', 1, 5, 85, 55, $$[{"label": "Will surely / I believe that (literary)", "definition": "A literary, emphatic way to express a strong belief, trust, or resolution about the future — 'I trust/believe that...'", "formation": "Verb/Adj stem + -(으)리라(고) (often with 믿다, 생각하다, 마음먹다, 말하다)", "examples": [["올해는 꼭 합격하리라.", "I will surely pass this year."], ["철수가 모델로 성공하리라고는 아무도 예상하지 못했으리라.", "Surely no one could have expected that Cheolsu would succeed as a model."]], "notes": "The verb after it (믿다, 생각하다, etc.) is often dropped/implied; found in poetic, formal, or emphatic written contexts.", "label_ko": null, "label_vi": null, "definition_ko": "미래에 대한 강한 믿음, 확신, 결의를 나타내는 문어적이고 강조적인 표현이다: '~하리라 믿는다/생각한다'.", "definition_vi": "Là cách diễn đạt mang tính văn học, nhấn mạnh niềm tin, sự tin tưởng hoặc quyết tâm mạnh mẽ về tương lai.", "notes_ko": "뒤따르는 동사(믿다, 생각하다 등)는 흔히 생략되며, 시적이거나 격식 있는 글에서 자주 보인다.", "notes_vi": "Động từ theo sau (믿다, 생각하다,...) thường được lược bỏ; hay xuất hiện trong văn thơ hoặc văn viết trang trọng."}]$$::jsonb, $$["리라고", "리라"]$$::jsonb, false, now()),
('이-나마', '-(이)나마', 'advanced', 2, 4, 55, 50, $$[{"label": "Even if just / at least (small comfort)", "definition": "Says that even though something is small, incomplete, or less than ideal, it is still welcomed or appreciated: 'even if it's just N, at least...'", "formation": "Noun + (이)나마 / Adj stem + -게나마/(으)나마", "examples": [["부족하나마 항상 최선을 다할 것입니다.", "Though it may be lacking, I will always do my best."], ["작게나마 제 성의라고 생각해서 이 선물을 받아 주시기 바랍니다.", "Please accept this gift, small as it is, as a token of my sincerity."]], "notes": "Kinda positive despite the modest/displeasing fact it's attached to; similar in feel to N(이)라도, but slightly more literary.", "label_ko": null, "label_vi": null, "definition_ko": "무언가가 작거나 불완전하거나 이상적이지 않더라도 그것만으로도 감사하고 반갑다는 뜻을 나타낸다.", "definition_vi": "Diễn đạt rằng dù điều gì đó nhỏ bé, chưa hoàn chỉnh hoặc chưa lý tưởng, vẫn được trân trọng hoặc chấp nhận: 'dù chỉ là N, ít nhất cũng...'.", "notes_ko": "부족하거나 마음에 차지 않는 사실이 붙어 있음에도 다소 긍정적인 느낌을 준다. 'N(이)라도'와 비슷하지만 조금 더 문어적이다.", "notes_vi": "Mang sắc thái khá tích cực dù đi kèm với một sự thật khiêm tốn/không như ý. Gần giống 'N(이)라도' nhưng mang tính văn viết hơn một chút."}]$$::jsonb, $$["나마"]$$::jsonb, false, now()),
('고서야-아-어서야', '-고서야/아/어서야', 'advanced', 2, 4, 55, 50, $$[{"label": "Only after / not until", "definition": "Emphasizes that P2 could only happen after P1 was completed (-고서야), or only while/once P1 was the case (-아/어서야): 'only after P1 did P2 happen.'", "formation": "Verb stem + -고서야 (completed action) / -아/어서야 (state/condition)", "examples": [["나는 약을 며칠이나 먹고서야 감기가 나았다.", "It was only after taking medicine for several days that my cold got better."], ["날이 밝아서야 우리는 잃어버린 것을 찾을 수 있었다.", "It was only once dawn broke that we were able to find what we'd lost."]], "notes": "Can add 수 없다/겠니? to emphasize how difficult/impossible something was ('바보가 아니고서야 그럴 수는 없지' — 'unless you're a fool, that can't be'); -고서도 is a related pattern meaning 'even after'.", "label_ko": null, "label_vi": null, "definition_ko": "P1이 끝난 후에야(-고서야) 혹은 P1인 상태가 되어서야(-아/어서야) P2가 비로소 일어날 수 있었음을 강조한다.", "definition_vi": "Nhấn mạnh rằng P2 chỉ có thể xảy ra sau khi P1 hoàn thành (-고서야), hoặc chỉ khi P1 là tình trạng đó (-아/어서야): 'chỉ sau khi P1 thì P2 mới...'.", "notes_ko": "'수 없다/겠니?'를 붙여 얼마나 어렵거나 불가능한 일이었는지를 강조할 수 있다. '-고서도'는 '~하고도'라는 관련 표현이다.", "notes_vi": "Có thể thêm '수 없다/겠니?' để nhấn mạnh mức độ khó khăn hoặc bất khả thi. '-고서도' là mẫu câu liên quan mang nghĩa 'dù đã...'."}]$$::jsonb, $$["고서야", "아서야", "어서야"]$$::jsonb, false, now()),
('다시피-하다', '-다시피 (하다)', 'advanced', 3, 3, 45, 50, $$[{"label": "As you'd (know / see / hear...)", "definition": "Attaches to verbs of perception/thought (알다, 보다, 듣다, 느끼다, 짐작하다, 예상하다) to mean 'as you already know/see/hear.'", "formation": "Verb stem (알다, 보다, 듣다, etc.) + -다시피", "examples": [["너도 알다시피 난 정치에 관심이 없어.", "As you know, I have no interest in politics."], ["우리 둘 다 느끼다시피 지금 날씨에는 어디에도 갈 수 없어.", "As we both can feel, we can't go anywhere in this weather."]], "notes": "Common set: 알다시피, 보다시피, 듣다시피, 느끼다시피, 짐작하다시피, 예상하다시피.", "label_ko": null, "label_vi": null, "definition_ko": "지각·인지 동사(알다, 보다, 듣다, 느끼다, 짐작하다, 예상하다) 뒤에 붙어 '~하는 것처럼, 이미 알다시피'라는 뜻을 나타낸다.", "definition_vi": "Gắn vào các động từ nhận thức/tri giác (알다, 보다, 듣다, 느끼다, 짐작하다, 예상하다) mang nghĩa 'như bạn đã biết/thấy/nghe'.", "notes_ko": "자주 쓰이는 조합: 알다시피, 보다시피, 듣다시피, 느끼다시피, 짐작하다시피, 예상하다시피.", "notes_vi": "Các tổ hợp thường gặp: 알다시피, 보다시피, 듣다시피, 느끼다시피, 짐작하다시피, 예상하다시피."}, {"label": "-다시피 하다 (practically / basically doing)", "definition": "Says that P1 is almost, though not exactly, the same as V — 'practically/basically V-ing.'", "formation": "Verb stem + -다시피 하다", "examples": [["그는 연구실에서 살다시피 했어요.", "He practically lived in the lab."], ["다이어트 때문에 매일 굶다시피 하는 사람들이 많아요.", "Many people practically starve themselves every day because of dieting."]], "notes": "When the verb is passive, use -다시피 하고 있다 (e.g. 마비되다시피 하고 있다 — 'it's practically paralyzed').", "label_ko": null, "label_vi": null, "definition_ko": "P1이 정확히는 아니지만 V와 거의 같음을 나타낸다: '거의 ~하는 것과 마찬가지로 하다'.", "definition_vi": "Diễn đạt P1 gần như, dù không chính xác, giống với V: 'gần như là đang làm V'.", "notes_ko": "동사가 피동형일 때는 '-다시피 하고 있다' 형태로 쓴다 (예: 마비되다시피 하고 있다).", "notes_vi": "Khi động từ ở dạng bị động, dùng dạng '-다시피 하고 있다' (ví dụ: 마비되다시피 하고 있다)."}]$$::jsonb, $$["다시피"]$$::jsonb, false, now()),
('을락-말락-하다', '-을락 말락 하다', 'advanced', 1, 4, 20, 40, $$[{"label": "On the verge of / about to (barely)", "definition": "Describes something that is right on the edge of happening — alternately seeming to happen and not happen, or just barely occurring.", "formation": "Verb stem + -(으)ㄹ락 말락 하다", "examples": [["단추가 떨어질락 말락 해요.", "The button is about to fall off (hanging by a thread)."], ["천장에 손이 닿을락 말락 해요.", "My hand can just barely reach the ceiling."]], "notes": "Also seen as V(의락)V(의락) with fixed opposite verb pairs, e.g. 오르락내리락하다 (keep going up and down), 들락날락하다 (keep going in and out).", "label_ko": null, "label_vi": null, "definition_ko": "무언가가 일어날 듯 말 듯한, 즉 일어날락 말락 아슬아슬한 상태에 있음을 나타낸다.", "definition_vi": "Miêu tả điều gì đó đang ở ranh giới sắp xảy ra — lúc như xảy ra lúc như không, hoặc chỉ vừa mới xảy ra.", "notes_ko": "V(의락)V(의락) 형태로 정해진 반대말 동사 쌍과 함께 쓰이기도 한다 (예: 오르락내리락하다, 들락날락하다).", "notes_vi": "Cũng xuất hiện ở dạng V(의락)V(의락) với các cặp động từ trái nghĩa cố định (ví dụ: 오르락내리락하다, 들락날락하다)."}]$$::jsonb, $$["락 말락"]$$::jsonb, true, now()),
('아-어-보니-까-고-보니-까', '-아/어 보니(까) / -고 보니(까)', 'advanced', 4, 3, 35, 50, $$[{"label": "Realize / find out after trying or doing", "definition": "Marks a situation where the speaker learns or realizes a fact only after having tried (-아/어 보니까) or completed (-고 보니까) something.", "formation": "Verb stem + -아/어 보니(까) / Verb stem + -고 보니(까)", "examples": [["아이폰을 써 보니까 다른 핸드폰을 사용할 수 없다.", "Now that I've tried using an iPhone, I can't use any other phone."], ["이 사람을 만나고 보니 좋은 사람 같아요.", "Now that I've met this person, they seem like a good person."]], "notes": "Often ends with 게 됐다/생겼다/깨달았다; -더니 is a related but distinct pattern that always centers on the speaker's own subject and past experience.", "label_ko": null, "label_vi": null, "definition_ko": "무언가를 시도해 보고(-아/어 보니까) 혹은 끝내고 나서(-고 보니까) 비로소 어떤 사실을 알게 되었음을 나타낸다.", "definition_vi": "Diễn đạt việc người nói chỉ nhận ra hoặc phát hiện một sự thật sau khi đã thử (-아/어 보니까) hoặc hoàn thành (-고 보니까) điều gì đó.", "notes_ko": "흔히 '게 됐다/생겼다/깨달았다'로 끝맺으며, 비슷하지만 다른 '-더니'는 항상 화자 자신의 과거 경험을 중심으로 한다.", "notes_vi": "Thường kết thúc bằng '게 됐다/생겼다/깨달았다'; '-더니' tương tự nhưng khác, luôn xoay quanh trải nghiệm quá khứ của chính người nói."}]$$::jsonb, $$["아 보니", "어 보니", "고 보니"]$$::jsonb, false, now())
